// 300 diepe weetjes. De uitleg is bewust eenvoudig geformuleerd maar behoudt
// de volledige technische diepgang (jargon wordt uitgelegd, niet weggelaten).

export type Weetje = {
  id: number
  categorie: string
  vraag: string
  uitleg: string
}

export const WEETJES: Weetje[] = [
  { id: 1, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een balanswiel een amplitude rond 270° nodig heeft — te veel en de kleppaal "klopt over" (knocking), waardoor het horloge juist vóórloopt', uitleg: 'De amplitude is hoever de balans per halve tik uitzwaait. Rond 270 graden werkt het ankermechanisme in zijn beste bereik: de gang hangt dan nauwelijks af van hoe strak de veer staat. Zwaait de balans te ver door (boven ongeveer 300 graden), dan slaat het rolletje tegen de verkeerde kant van de ankervork aan (dit heet knocking). De balans krijgt dan een extra duwtje op het verkeerde moment, waardoor elke tik iets korter duurt en het horloge plotseling fors voorloopt. Daarom regelt men bij volle veer op zo\'n 270 graden, met marge naar boven en onder.' },
  { id: 2, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een lage "beat error" (< 0,5 ms) betekent dat de balans symmetrisch tikt en het horloge in elke stand gelijk loopt', uitleg: 'Beat error is het tijdsverschil tussen de tik naar links en de tik naar rechts. Het ontstaat als de ruststand van de balans niet precies in het midden tussen de ankervorkhoorns ligt, waardoor het horloge in de ene richting net anders wordt aangeduwd dan in de andere. Bij een verschil onder 0,5 milliseconde duren beide tikken praktisch even lang en \'ademt\' de spiraalveer keurig symmetrisch. Zo\'n symmetrische tik reageert veel minder op de standveranderingen die optreden als je het horloge draait. Daardoor loopt het horloge in verschillende posities gelijkmatiger.' },
  { id: 3, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een horloge in verschillende standen anders loopt: zwaartekracht trekt aan een minuscuul onbalansje in het balanswiel (positieafwijking)', uitleg: 'Een balans is nooit perfect uitgebalanceerd; er blijft altijd een minuscuul zwaar plekje aan één kant. Staat het horloge rechtop, dan trekt de zwaartekracht aan dat plekje en remt het de balans in de ene halve slag af terwijl het hem in de andere versnelt; dat verandert de uitzwaai en dus de gang. Ligt het horloge plat (wijzerplaat boven of onder), dan valt de zwaartekracht samen met de draaias en verdwijnt dit effect grotendeels, zodat plat en rechtop systematisch verschillen. In verticale standen speelt bovendien extra lagerwrijving mee. Fabrikanten wegen de balans daarom nauwkeurig uit; een tourbillon middelt de standfouten weg door de hele gangregelaar te laten ronddraaien.' },
  { id: 4, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom Nivarox-spiralen van een elinvar-legering zijn die nauwelijks uitzet bij temperatuur en amper magnetisch is', uitleg: 'Hoe snel een horloge tikt, hangt vooral af van de veerkracht (stijfheid) van de spiraalveer. Bij gewoon staal wordt die stijfheid minder als het warmer wordt, waardoor de veer slapper wordt en het horloge achterloopt. Speciale legeringen zoals Nivarox (ijzer en nikkel met wat chroom, beryllium en titaan) zijn juist zo gemaakt dat hun stijfheid over een breed temperatuurbereik vrijwel gelijk blijft. Daardoor corrigeert de veer zichzelf en is een dure temperatuur-compenserende balans niet meer nodig. De nikkelbasis maakt het materiaal bovendien nauwelijks magnetisch, zodat een magneet de veer veel minder verstoort dan bij staal.' },
  { id: 5, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een oud horloge met stalen spiraal na contact met een magneet ineens uren voorloopt — de windingen plakken aan elkaar', uitleg: 'Een stalen spiraalveer is magnetiseerbaar en blijft na contact met een sterke magneet zelf een beetje magnetisch. De windingen liggen vlak boven elkaar en worden dan magnetische polen die elkaar aantrekken en tijdens het ademen van de veer aan elkaar plakken. Daardoor doet een kortere lengte van de veer nog mee met trillen, en een kortere veer trilt sneller, zodat het horloge flink voorloopt. Pas na ontmagnetiseren met een apparaatje dat een steeds zwakker wisselveld geeft, verdwijnt het effect. Moderne veren van Nivarox of silicium zijn juist gekozen omdat ze nauwelijks magnetisch worden.' },
  { id: 6, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een marinechronometer op een cardanische ophanging lag, zodat scheepsbewegingen de gang niet stoorden', uitleg: 'Een cardanische ophanging (gimbal) bestaat uit twee in elkaar geneste draairingen met een tegenwicht, zodat de doos met het uurwerk door de zwaartekracht altijd horizontaal blijft terwijl het schip rolt en stampt. Zo blijft het uurwerk plat liggen, precies de stand waarvoor het is afgeregeld en waarin de standfouten het kleinst zijn. Het gevoelige mechanisme (meestal een chronometer-echappement) verdraagt kantelen en schokken slecht, en de gimbal houdt de balans uit die verstorende standen. Daardoor bleef de gang stabiel genoeg om, via het tijdsverschil met de bekende haventijd, op zee de lengtegraad te bepalen.' },
  { id: 7, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom horlogeolie na een paar jaar verhardt en verharst — de belangrijkste reden dat een uurwerk elke 4–5 jaar open moet', uitleg: 'De olie in een uurwerk reageert met zuurstof, licht en warmte: de lichte bestanddelen verdampen en de rest klontert samen tot een taaie, harsachtige massa. Daardoor wordt de olie plaatselijk dikker en kruipt ze weg van de plekken waar ze juist moet zitten. Op zwaar belaste punten, zoals de ankerpaletten en het opwindwerk, geeft dat meer wrijving, minder uitzwaai en uiteindelijk droge metaal-op-metaalslijtage. Omdat de gang direct afhangt van stabiele wrijving, moet het uurwerk elke vier à vijf jaar uit elkaar, worden schoongemaakt en opnieuw gesmeerd. Moderne synthetische oliën en een coating (epilame) die de olie op zijn plek houdt, rekken dat interval op.' },
  { id: 8, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een "remontoir d\'égalité" een constante kracht aan de gang levert, los van of de veer vol of bijna leeg is', uitleg: 'De kracht van een opgewonden veer is niet constant: hoog bij een volle veer, laag als de veer bijna leeg is, en dat verschil beïnvloedt de gang. Een remontoir d\'égalité zet vlak vóór het tikkende deel een klein extra energiebuffertje (een kort veertje of gewichtje), dat met vaste tussenpozen steeds opnieuw op dezelfde spanning wordt geladen door het hoofdmechanisme. De gangregelaar krijgt zijn energie dus alleen uit dat buffertje, dat telkens even sterk is, ongeacht of de hoofdveer vol of leeg is. Zo blijft de aandrijfkracht constant en dus ook de uitzwaai en de gang, over de hele looptijd. Dit werkt exacter dan een snek, die de kracht slechts geleidelijk afvlakt.' },
  { id: 9, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een echappement maar 30–40% van de veerenergie doorgeeft; de rest gaat verloren aan wrijving en schokken', uitleg: 'In het gangbare Zwitserse ankermechanisme wordt de kracht doorgegeven door schuivend contact tussen de ankerpaletten en de tanden van het echappementsrad, en schuiven kost altijd energie. Bij elke ontgrendeling schuurt een tand over de palet, dan volgt een schokje bij het doorgeven van de impuls en het opvangen van de volgende tand, waarbij energie in warmte en trillingen weglekt. Ook het bedienen van de veiligheidspal en het heen en weer bewegen van de zware ankermassa kost energie. Netto bereikt daardoor maar ongeveer een derde van de veerenergie de balans als nuttige duw. Constructies met minder schuifwrijving, zoals het co-axiaal- of het chronometer-echappement, halen juist een beter rendement.' },
  { id: 10, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een "Guillaume-balans" twee metalen combineert om de "middagfout" van temperatuur te compenseren', uitleg: 'Een compensatiebalans van twee metalen buigt bij temperatuurverandering, omdat de twee metalen verschillend uitzetten; zo verplaatst hij massa en corrigeert hij de gangfout van een stalen spiraal. Maar er blijft een restfout: de correctie klopt bij twee ijktemperaturen en net niet bij de temperatuur ertussenin (de \'middagfout\'). Charles-Edouard Guillaume maakte een speciale nikkelstaal-legering die niet gelijkmatig uitzet en gebruikte die voor de binnenlaag van de balans. Gecombineerd met gewoon messing verplaatst de massa nu niet-lineair met de temperatuur, waardoor ook die tussenliggende restfout grotendeels wegvalt. Zo bleef de gang over een breed temperatuurbereik nauwkeurig, tot de elinvar-spiraal dit type balans overbodig maakte.' },
  { id: 11, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom een COSC-chronometer tussen −4 en +6 seconden per dag moet blijven, gemeten in vijf standen en drie temperaturen', uitleg: 'De COSC test losse uurwerken vijftien dagen lang, en de gemiddelde daggang moet daarbij tussen min 4 en plus 6 seconden per etmaal liggen. Die scheve marge bestaat omdat een licht voorlopend horloge in de praktijk prettiger is en een goed afgeregeld uurwerk makkelijker net iets snel loopt. In vijf standen (twee plat, drie rechtop) komen de standfouten door onbalans en lagerwrijving aan het licht, en metingen bij ongeveer 8, 23 en 38 graden toetsen de temperatuurcompensatie van spiraal en balans. Naast de gemiddelde gang gelden er aparte eisen aan bijvoorbeeld de spreiding tussen standen en de grootste afwijking. Zo wordt niet alleen het gemiddelde, maar ook de constantheid gewaarborgd.' },
  { id: 12, categorie: 'Mechanische horloges & precisietijd', vraag: 'Waarom "hacking seconds" een aparte remhefboom vereist die goedkope uurwerken missen', uitleg: 'Bij hacking seconds stopt de secondewijzer zodra je de kroon uittrekt, zodat je het horloge op de seconde nauwkeurig kunt gelijkzetten. Daarvoor is een klein veerhefboompje nodig dat bij het uittrekken tegen de rand van de balans drukt en die door wrijving afremt, waardoor het hele raderwerk stilstaat. Zonder dat hefboompje blijft de balans doortikken en kun je alleen op de minuut afstellen. Goedkope uurwerken laten dit onderdeel weg om kosten en montagewerk te sparen, waardoor exact op de seconde synchroniseren niet lukt.' },
  { id: 13, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een straalmotor "spool-up lag" heeft: de zware compressor op toeren brengen kost seconden — cruciaal bij een doorstart', uitleg: 'Bij een straalmotor bepaalt vooral het toerental van de compressor de stuwkracht, en die draaiende compressor plus turbine is zwaar en dus traag op gang te brengen. Geef je gas, dan moet de extra brandstof eerst dat gewicht opvoeren tegen de draaitraagheid en de luchtweerstand in; pas na enkele seconden neemt de luchtstroom en dus de stuwkracht echt toe. Vanuit stationair, met een laag toerental, duurt dat het langst. Daarom houden piloten bij een doorstart de motoren liever niet te ver terug en duwen ze de gashendels vroeg vooruit, want elke seconde telt tot de stuwkracht er is. De motorcomputer (FADEC) begrenst de brandstoftoename bovendien om te voorkomen dat de compressor de stroming verliest, wat de vertraging bewust nog iets verlengt.' },
  { id: 14, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een turbofan een aparte "N1" en "N2" heeft: twee assen die mechanisch losgekoppeld op verschillende toeren draaien', uitleg: 'Een moderne turbofan heeft twee assen die in elkaar liggen maar niet met elkaar verbonden zijn. De ene as (N1) koppelt de grote fan en de lagedrukcompressor aan de lagedrukturbine; de andere (N2) koppelt de hogedrukcompressor aan de hogedrukturbine. Ze draaien vrij op elk hun eigen, aerodynamisch beste toerental. Dat is nodig omdat de grote fan het efficiëntst is bij een laag toerental, terwijl de kleine hogedruktrappen juist snel moeten draaien om de lucht onder de goede hoek aan te blijven stromen en niet de stroming te verliezen. N2 is de belangrijkste waarde bij het starten en voor de brandstofregeling; N1 geeft bij de meeste turbofans het beste weer hoeveel stuwkracht de motor levert.' },
  { id: 15, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom "compressor stall" en "surge" ontstaan als de luchtstroom losraakt en terugslaat, soms met een knal en vlam uit de inlaat', uitleg: 'Elke compressorschoep is een klein vleugeltje met een aanstroomhoek; wordt die hoek te groot (door te snel gas geven, een verstoorde inlaat of te hoge tegendruk), dan laat de lucht los van de schoep, net als bij een overtrekkende vleugel. Zo\'n losgeraakte plek kan zich uitbreiden (rotating stall), en bij een volledige surge klapt de hele compressie om en stroomt de samengeperste lucht kortstondig terug naar de inlaat. Die plotselinge drukomkering geeft een harde knal, en hete of onverbrande gassen kunnen als vlam uit de inlaat of uitlaat slaan. Zodra de tegendruk wegvalt, herstelt de stroming en kan het zich herhalen tot de brandstof wordt teruggeregeld. Constructief houdt men surge weg met verstelbare schoepen, aftapkleppen en genoeg veiligheidsmarge in de regeling.' },
  { id: 16, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom variabele "stator vanes" in de compressor meedraaien om stall bij lage toeren te voorkomen', uitleg: 'De vaste schoepen (stators) tussen de draaiende trappen richten de lucht onder de juiste hoek naar de volgende trap. Bij lage toeren draait de as verhoudingsgewijs te snel ten opzichte van de trage luchtstroom, waardoor de lucht onder een te steile hoek op de schoepen komt en dreigt los te raken. Verstelbare statorschoepen draaien dan mee en \'voordraaien\' de lucht alvast in de draairichting, wat die hoek verkleint en de schoepen veilig laat werken. Bij hoge toeren draaien ze terug naar een rechtere stand voor maximale doorstroming en rendement. Zo werkt de motor stabiel over een veel breder toerenbereik zonder de stroming te verliezen.' },
  { id: 17, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een "bleed valve" bij het opstarten lucht wegblaast zodat de compressor niet in surge schiet', uitleg: 'Bij het starten en op lage toeren zijn de voorste en achterste compressortrappen niet op elkaar afgestemd: de kleinere achterste trappen kunnen de aangevoerde lucht niet goed kwijt, waardoor lucht zich opstuwt en de voorste trappen richting stall duwt. Een aftapklep (bleed valve) opent dan en blaast een deel van de lucht uit de middentrappen naar buiten. Daardoor daalt de tegendruk op de voorste trappen, houdt de luchtstroom daar een veilige aanstroomhoek en verliest de compressor de stroming niet. Zodra de motor genoeg toeren maakt en de trappen weer bij elkaar passen, sluit de klep voor maximaal rendement.' },
  { id: 18, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom turbinebladen inwendig hol zijn en met filmkoeling werken — de gassen zijn heter dan het smeltpunt van het metaal', uitleg: 'De verbrandingsgassen die de eerste turbinetrap binnenkomen, zijn heter dan het smeltpunt van het gebruikte nikkelmetaal. Om dat te overleven zijn de turbinebladen hol en stroomt er van binnenuit koelere lucht doorheen, die eerder uit de compressor is afgetapt. Via honderden minuscule gaatjes komt die lucht naar buiten en vormt een dun, koel laagje over het blad dat het metaal van de hete gasstroom scheidt (filmkoeling). Van binnen helpen ribbels en gerichte luchtstraaltjes de warmte extra af te voeren. Samen met een keramische isolatielaag kan de turbine zo draaien bij gastemperaturen die het kale metaal meteen zouden laten bezwijken.' },
  { id: 19, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een keramische "thermal barrier coating" op turbinebladen honderden graden isoleert', uitleg: 'Een thermische barrierecoating is een dun keramisch laagje, meestal van zirkoniumoxide, dat bovenop een hechtlaag op de turbinebladen zit. Dat keramiek geleidt warmte heel slecht, waardoor er over die dunne laag een groot temperatuurverschil kan staan. Samen met de koellucht binnen in het blad houdt het het onderliggende metaal enkele honderden graden koeler dan de hete gassen eromheen. De laag heeft een poreuze, kolomvormige structuur die genoeg kan meerekken om bij opwarmen en afkoelen niet af te bladderen. Zo kan de motor bij een hogere gastemperatuur en dus hoger rendement draaien zonder dat de bladen bezwijken.' },
  { id: 20, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een uitgevallen straalmotor via de "windmill" van de luchtstroom opnieuw kan ontsteken, mits snel genoeg', uitleg: 'Vliegt een toestel hard genoeg, dan blaast de aanstromende lucht de fan en compressor als een windmolentje rond, ook als de motor uit staat (windmilling). Dat door de wind aangedreven draaien levert genoeg luchtdruk en luchtstroom in de verbrandingskamer om, na het weer aanzetten van brandstof en ontsteking, de verbranding op gang te brengen en de motor vanzelf weer op te laten komen. Cruciaal is dat de snelheid binnen het in het handboek vastgelegde herstartgebied blijft, want daaronder draait de windmolen te traag en moet de APU of een startmotor helpen. Bij te lage snelheid of te grote hoogte lukt herstart niet zonder hulp. Daarom is snel handelen met genoeg snelheid bepalend voor een geslaagde herontsteking.' },
  { id: 21, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een "FADEC" volledig digitaal de brandstof regelt en de piloot de motor niet meer direct kan overbelasten', uitleg: 'Een FADEC is een dubbel uitgevoerde motorcomputer die op basis van de gashendelstand en veel sensoren (toerentallen, temperaturen, drukken) de brandstoftoevoer en de verstelbare onderdelen regelt. Omdat hij volledige zeggenschap heeft, vertaalt hij de pilootcommando\'s naar de gewenste stuwkracht, maar altijd binnen vooraf ingestelde grenzen. Hij bewaakt continu limieten zoals de maximale uitlaattemperatuur, het toerental en hoe snel de motor opkomt, en knijpt de brandstof af om oververhitting, overtoeren of het verliezen van de stroming te voorkomen. De piloot vraagt dus stuwkracht, maar de computer bepaalt hoeveel brandstof veilig kan; de motor rechtstreeks overbelasten kan niet meer. Dat verbetert bovendien het verbruik en vereenvoudigt de start.' },
  { id: 22, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een "geared turbofan" de fan langzamer laat draaien dan de turbine — veel stiller en zuiniger', uitleg: 'Een grote fan werkt het efficiëntst bij een laag toerental, want anders naderen de bladtippen de geluidssnelheid, wat verlies en lawaai geeft; de lagedrukturbine levert juist het meeste rendement bij een hoog toerental. Zitten fan en turbine op dezelfde as, dan moet je een compromis kiezen. Een geared turbofan zet er een tandwielkast (reductie) tussen, zodat de fan bijvoorbeeld drie keer langzamer draait dan de turbine. Zo werken beide op hun eigen ideale toerental, wat een hogere efficiëntie, lager brandstofverbruik en veel minder fanlawaai oplevert. De prijs is de complexiteit en de warmte-afvoer van die zwaarbelaste tandwielkast.' },
  { id: 23, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom de uitlaat van sommige motoren "chevrons" (zaagtandranden) heeft om lawaai te dempen', uitleg: 'Uitlaatlawaai ontstaat vooral daar waar de snelle uitlaatstraal op de tragere buitenlucht botst en grote wervels vormt die veel laagfrequent geluid maken. Chevrons, de zaagtandvormige inkepingen aan de rand van de uitlaat, wekken gecontroleerde langswervels op die de snelle en trage lucht geleidelijker en over een groter grensvlak mengen. Daardoor breken de grote wervels in kleinere, wat het bromgeluid meetbaar vermindert en de rest naar minder hinderlijke, hogere tonen verschuift. Het resultaat is minder grondlawaai, vooral bij de start, tegen een klein verlies aan stuwkracht. De vorm is dus een compromis tussen stilte en prestatie.' },
  { id: 24, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een "hung start" ontstaat als de motor blijft steken op laag toerental zonder op te komen', uitleg: 'Bij het starten brengt een startmotor (meestal via perslucht van de APU) de compressor op toeren, tot de ontstoken verbranding het overneemt en de motor zelf doordraait. Bij een hung start ontsteekt de brandstof wel, maar blijft het toerental hangen op een te laag niveau zonder verder op te komen. Dat gebeurt als het aandrijvende en het verbrandingsvermogen niet opwegen tegen de weerstand, bijvoorbeeld doordat de startmotor te vroeg wegvalt, de luchtdruk te laag is, de brandstofregeling hapert of men op grote hoogte start. Omdat het toerental laag blijft, is er weinig koelende luchtstroom en loopt de uitlaattemperatuur snel op, wat de motor bedreigt. De juiste reactie is de brandstof afsluiten en de start afbreken.' },
  { id: 25, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom "EGT" (uitlaatgastemperatuur) de kritische limiet bij het starten is — te heet en de bladen smelten', uitleg: 'De uitlaatgastemperatuur (EGT) is een indirecte maat voor de veel hetere temperatuur vlak vóór de turbine, die je niet rechtstreeks kunt meten maar die bepaalt hoe lang de turbinebladen meegaan. Tijdens het starten draait de motor nog langzaam, dus stroomt er weinig koelende lucht doorheen en geeft toegevoegde brandstof snel een sterke temperatuurpiek. De turbinebladen werken normaal al vlak bij hun grens en leunen op luchtkoeling; bij te weinig luchtstroom en een te hoge EGT verliezen ze hun sterkte en kunnen ze vervormen of plaatselijk smelten. Daarom bewaken bemanning en motorcomputer de EGT bij de start als kritische grens en breken ze af bij een dreigende oververhitting (hot start).' },
  { id: 26, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een APU in de staart de motoren met perslucht start en het toestel aan de grond van stroom voorziet', uitleg: 'De APU is een kleine, zelfstandige gasturbine, meestal in de staart, die niet voor stuwkracht dient maar voor perslucht en stroom. Bij het starten van de hoofdmotoren levert de APU hogedruklucht aan de pneumatische startmotoren, die de grote compressoren op starttoeren brengen; een accu is daarvoor niet krachtig genoeg. Aan de grond drijft de APU een generator aan die het toestel van stroom voorziet en levert hij lucht voor de airco, zodat een grondaggregaat of draaiende hoofdmotoren niet nodig zijn. De APU zelf wordt gestart met een accu of grondstroom en kan in de lucht als noodstroombron dienen. Zo maakt hij het vliegtuig grotendeels onafhankelijk van voorzieningen op de grond.' },
  { id: 27, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom "anti-ice" hete lucht via de vleugelvoorrand blaast en dat via extra bleed brandstof kost', uitleg: 'IJs op de vleugelvoorrand verstoort de luchtstroom, vergroot de weerstand en verlaagt de maximale lift, waardoor het toestel eerder overtrekt; gevaarlijk dus. Het anti-ijssysteem tapt daarom hete perslucht af uit de compressor van de motoren en leidt die langs de binnenkant van de voorrand, zodat het metaal warm genoeg blijft om ijsvorming te voorkomen. Maar die afgetapte lucht was al door de compressor samengeperst en had anders aan de stuwkracht bijgedragen; door haar weg te nemen daalt het motorrendement en moet er meer brandstof branden voor dezelfde stuwkracht. Daarom kost anti-ice merkbaar extra brandstof en zet men het alleen aan in ijscondities. Sommige moderne toestellen gebruiken elektrische verwarming om dit verlies te vermijden.' },
  { id: 28, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een "ram air turbine" (RAT) uitklapt en op windkracht noodstroom levert als alle motoren uitvallen', uitleg: 'De ram air turbine is een klein propellertje dat bij een totale uitval van stroom en hydrauliek automatisch in de rijwind wordt uitgeklapt. De aanstromende lucht drijft de turbine aan, die via een generator of pomp noodstroom en hydraulische druk levert voor de belangrijkste systemen, zoals de primaire besturing en de basisinstrumenten. Omdat de RAT alleen de energie van de langsstromende lucht gebruikt, werkt hij ook als alle motoren stilstaan, zolang het toestel maar genoeg snelheid houdt. Het geleverde vermogen is beperkt en neemt af bij lagere snelheid, dus de RAT voedt bewust alleen de vitale onderdelen. Hij is zo de allerlaatste terugval, zoals bij de noodlanding op de Hudson.' },
  { id: 29, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom cabinedruk met een "outflow valve" geregeld wordt die lucht gecontroleerd laat ontsnappen, niet met inpompen alleen', uitleg: 'De motoren leveren via afgetapte lucht continu een grote, min of meer vaste luchtstroom aan de cabine; die instroom bijregelen om de druk fijn te sturen is traag en lastig. Daarom houdt het systeem de instroom ongeveer constant en regelt het de cabinedruk aan de uitgang, met een outflow valve die meer of minder opent zodat er precies genoeg lucht ontsnapt. Knijp je de klep dicht, dan stijgt de druk; open je hem, dan daalt hij, en zo kan de cabinehoogte soepel worden geregeld bij klim en daling. Aparte overdruk- en onderdrukventielen beschermen de romp tegen te grote drukverschillen. Deze uitstroomregeling ververst tegelijk voortdurend de cabinelucht.' },
  { id: 30, categorie: 'Luchtvaart — motoren & systemen', vraag: 'Waarom een "pitot-static"-systeem hoogte en snelheid puur uit luchtdruk afleidt — en bevriezing dodelijke fouten gaf (AF447)', uitleg: 'Het pitot-statische systeem meet twee luchtdrukken: de gewone omgevingsdruk (statisch) en de hogere druk die een naar voren gerichte buis (de pitotbuis) opvangt door de rijwind. Uit de statische druk volgt via de standaardatmosfeer de hoogte, en het verschil tussen beide drukken levert de gemeten luchtsnelheid. Er zijn geen bewegende meetdelen nodig, maar alles hangt af van open, onbelemmerde drukopeningen. Verstoppen de pitotbuizen door ijskristallen, dan bevriest die drukmeting en geeft de snelheidsmeter foutieve, tegenstrijdige waarden. Bij vlucht AF447 leidden zulke bevroren pitotbuizen tot onbetrouwbare snelheden, uitschakeling van de automatische piloot en uiteindelijk een fatale overtreksituatie.' },
  { id: 31, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom een "vortex generator" — een klein vinnetje — de grenslaag bewust verstoort om loslaten uit te stellen', uitleg: 'Vlak langs het vleugeloppervlak ligt de grenslaag, een dun laagje trager stromende lucht; loopt de druk op (naar de achterrand of bij een grote invalshoek), dan dreigt die laag los te raken, wat overtrek en weerstand geeft. Een vortex generator is een klein, schuin geplaatst vinnetje dat een draaikolkje opwekt dat energierijke lucht van boven naar beneden de grenslaag in mengt. Die extra energie helpt de grenslaag de drukstijging langer te weerstaan, zodat de stroming pas verder naar achteren loslaat. Daardoor blijven de roeren tot een hogere invalshoek werken en wordt de maximale lift groter, tegen een beetje extra weerstand in kruisvlucht. Ze staan vaak net vóór de rolroeren of op de romp, waar loslaten het gevaarlijkst is.' },
  { id: 32, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom "wake turbulence" achter een groot vliegtuig zo krachtig is dat kleinere toestellen minutenlang moeten wachten', uitleg: 'Een vleugel maakt lift door onder hogere en boven lagere druk op te bouwen; aan de vleugeltippen stroomt de lucht om dat drukverschil heen en vormt twee krachtige, tegengesteld draaiende wervels. Hoe zwaarder en langzamer het toestel (zoals net na de start of vlak voor de landing), hoe sterker die wervels, want de lift moet het volle gewicht dragen. De wervels hangen achter en onder de vliegbaan, zakken langzaam en vallen pas na één tot enkele minuten uiteen. Een kleiner toestel dat erin vliegt, kan een plotselinge rolbeweging krijgen die de rolroeren niet aankunnen, met verlies van controle. Daarom houdt de verkeersleiding vaste tijds- en afstandsminima aan achter zware vliegtuigen.' },
  { id: 33, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom "winglets" niet de wervels tegenhouden maar de opwaartse tipstroom deels in stuwkracht omzetten', uitleg: 'Aan de vleugeltip stroomt lucht van de hogedruk-onderkant naar de lagedruk-bovenkant en veroorzaakt zo de tipwervel en de bijbehorende extra weerstand. Een winglet houdt die wervel niet tegen, maar staat als een klein verticaal vleugeltje in die schuin naar buiten-omhoog gerichte tipstroming. Doordat de winglet in die scheve stroming zelf lift maakt, wijst een deel van die kracht naar voren en werkt dus als een beetje stuwkracht die de weerstand deels goedmaakt. Tegelijk verplaatst en verzwakt de winglet de wervel, wat de extra weerstand van de hele vleugel verlaagt. Netto krijg je een beter liftrendement en lager verbruik, mits het extra oppervlak niet te veel wrijving toevoegt.' },
  { id: 34, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom een "swept wing" bij lage snelheid eerst aan de tip overtrekt — gevaarlijk, want daar zitten de rolroeren', uitleg: 'Bij een pijlvormige (naar achteren geveegde) vleugel stroomt een deel van de lucht langs de vleugel naar de tip toe, waardoor de trage grenslaag zich daar opstuwt en de tip aerodynamisch zwaarder wordt belast. Daardoor bereikt de tip bij een oplopende invalshoek als eerste zijn grens en trekt daar het eerst over. Dat is gevaarlijk omdat juist bij de tips de rolroeren zitten: bij een tipstall werken die niet meer en kan het toestel ongecontroleerd gaan rollen. Bovendien schuift het liftverlies aan de achterste tip het drukpunt naar voren, waardoor de neus bij het overtrekken kan oplichten en de situatie verergert. Ontwerpers bestrijden dit met wing fences, vortex generators, een geleidelijke draaiing in de vleugel (washout) of stall strips die de wortel eerst laten overtrekken.' },
  { id: 35, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom een "stall strip" bewust de wortel eerst laat overtrekken zodat de piloot waarschuwing voelt vóór controleverlies', uitleg: 'Een stall strip is een klein driehoekig lijstje op de voorrand vlak bij de vleugelwortel. Loopt de invalshoek op, dan verstoort dat scherpe randje daar plaatselijk de stroming, zodat de wortel iets eerder overtrekt dan de rest van de vleugel. Doordat de wortel het eerst loslaat, stroomt er turbulente lucht over de staart en romp, wat een voelbaar trillen (buffet) geeft: een natuurlijke overtrekwaarschuwing voor de piloot. Tegelijk blijven de tips, en dus de rolroeren, langer goed aangestroomd, zodat de piloot de dwarsbesturing houdt en het toestel niet plotseling over een vleugel wegrolt. Zo wordt een gecontroleerde, voorspelbare overtrek afgedwongen in plaats van een abrupt controleverlies.' },
  { id: 36, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom "Mach tuck" een snel vliegtuig spontaan de neus laat zakken zodra er schokgolven op de vleugel komen', uitleg: 'Nadert een toestel de kritische snelheid, dan wordt de lucht over de bovenkant van de vleugel plaatselijk sneller dan het geluid en vormt zich een schokgolf. Achter die schokgolf laat de stroming los en verschuift de liftverdeling, waardoor het aangrijpingspunt van de lift naar achteren opschuift. Komt dat punt achter het zwaartepunt te liggen, dan ontstaat een moment dat het toestel spontaan de neus laat zakken (tuck under). Dat is verraderlijk omdat het duiken de snelheid nog verder opvoert, wat de schokgolf versterkt en het effect vergroot: een zichzelf versterkende spiraal. Bij oudere straaljagers kon dit in een onherstelbare duik eindigen; moderne toestellen bestrijden het met Mach-trimsystemen en een pijlvleugel die de kritische snelheid opschuift.' },
  { id: 37, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom "Dutch roll" een slingerende koppeling van gieren en rollen is die een yaw damper automatisch onderdrukt', uitleg: 'Dutch roll is een slingerende beweging waarbij gieren (met de neus zwenken) en rollen aan elkaar gekoppeld zijn: giert het toestel, dan gaat de vooruit bewegende vleugel sneller door de lucht, maakt meer lift en rolt omhoog, wat via de vleugelpijling en de staartvin weer een tegengestelde zwenk opwekt. Zo beschrijft de neus een liggende acht. Toestellen met veel pijling en veel opwaartse vleugelhoek (V-stelling) hebben veel rolstabiliteit maar te weinig demping in de zwenkrichting, waardoor deze slecht gedempte slingering optreedt. Een yaw damper meet met een sensor de beginnende zwenk en stuurt automatisch het richtingsroer tegengesteld, zodat de slingering snel uitdooft voordat passagiers er last van hebben. Zonder die demper zou de piloot het handmatig moeten onderdrukken.' },
  { id: 38, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom "ground effect" de lift vlak boven de baan vergroot en een zwaar toestel soms weigert te "landen"', uitleg: 'Vlak boven de grond, op minder dan ongeveer één spanwijdte hoogte, laat het baanoppervlak de tipwervels minder ruimte om zich te vormen. Daardoor verzwakken die wervels en neemt de neerwaartse luchtstroom (downwash) af, wat de effectieve invalshoek vergroot en de extra weerstand verlaagt. Het gevolg is dat de vleugel bij dezelfde snelheid meer lift maakt en minder weerstand ondervindt zodra het toestel de grond nadert. Een te snel of te zwaar binnenkomend toestel blijft daardoor op dat luchtkussen zweven (floaten) en wil niet zakken tot de snelheid genoeg is gedaald. Piloten anticiperen door met de juiste nadersnelheid en flare te vliegen, zodat het toestel op het bedoelde punt neerzet.' },
  { id: 39, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom een "flat spin" bijna onherstelbaar is: de romp schermt het richtingsroer af van de luchtstroom', uitleg: 'In een vlakke tolvlucht (flat spin) draait het toestel bijna horizontaal snel om zijn verticale as, terwijl beide vleugels diep zijn overtrokken en het toestel vrijwel recht naar beneden zakt. De lucht komt daardoor vooral van onderaf, en de romp en horizontale staart werken als een scherm dat de aanstromende lucht wegneemt bij het richtingsroer. Zonder goede aanstroming levert dat roer nauwelijks nog kracht om de draaiing te stoppen, terwijl de uit elkaar liggende massa\'s de tol juist in stand houden. Bovendien blijven de vleugels overtrokken zolang de rotatie doorgaat, zodat de piloot de invalshoek niet zomaar kan verlagen. Herstel vereist heel specifieke, soms onmogelijke stuurbewegingen; daarom hebben testvliegtuigen soms een antitolparachute.' },
  { id: 40, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom "adverse yaw" het toestel bij het inzetten van een bocht juist de verkeerde kant op laat gieren', uitleg: 'Om een bocht in te zetten gebruik je de rolroeren: aan de buitenkant van de bocht gaat het roer omlaag en maakt daar meer lift, aan de binnenkant gaat het omhoog en maakt minder lift. Maar meer lift betekent ook meer weerstand, dus de omhoog rollende buitenvleugel ondervindt meer weerstand dan de binnenvleugel. Dat verschil zwenkt de neus juist naar buiten, tegen de gewenste bochtrichting in; dit heet adverse yaw (\'averechts gieren\'). De piloot compenseert door tegelijk het richtingsroer in de bochtrichting te gebruiken (gecoördineerd sturen). Ontwerpers beperken het met rolroeren die naar boven verder uitslaan dan naar beneden, of met Frise-rolroeren die aan de opgaande kant extra weerstand geven.' },
  { id: 41, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom "V1" het beslissingsmoment is: erna moet je opstijgen, ook met een uitgevallen motor', uitleg: 'V1 is de vooraf berekende beslissingssnelheid tijdens de startloop, afgestemd op het gewicht, de baanlengte en de omstandigheden. Onder V1 is er nog genoeg baan over om bij een storing veilig af te breken en tot stilstand te remmen. Boven V1 is die remafstand er niet meer en zou afbreken tot een overrun leiden, terwijl er dan wel genoeg baan en prestatie is om, desnoods met één uitgevallen motor, door te starten en te klimmen. Daarom is V1 het punt waarop de beslissing definitief valt: eenmaal voorbij V1 zet de bemanning de start onvoorwaardelijk door. De waarde wordt zo gekozen dat beide scenario\'s precies binnen de beschikbare baan passen.' },
  { id: 42, categorie: 'Luchtvaart — aerodynamica & vlieggedrag', vraag: 'Waarom een "balanced field length" het punt is waarop doorstarten en afbreken evenveel baan kosten', uitleg: 'Valt een motor uit tijdens de startloop, dan zijn er twee opties: afbreken en remmen tot stilstand, of doorstarten met de resterende motoren tot een veilige klimhoogte. Beide benodigde afstanden hangen af van de snelheid waarbij de storing optreedt, oftewel van de gekozen V1: een hogere V1 verlengt de stopafstand maar verkort de doorstartafstand, en omgekeerd. De balanced field length is de baanlengte bij die V1 waarbij de stopafstand precies gelijk is aan de doorstartafstand. In dat evenwichtspunt is de benodigde baan het kortst voor de gegeven omstandigheden, want beide scenario\'s passen dan binnen dezelfde lengte. Zo bepaalt men de minimale veilige baanlengte voor een bepaald startgewicht.' },
  { id: 43, categorie: 'Trein & spoor', vraag: 'Waarom een treinwiel een conische loopvlakhoek (1:20 of 1:40) heeft, zodat het zichzelf in het spoor centreert', uitleg: 'De twee wielen van een treinas zitten vast op één gemeenschappelijke as en draaien dus even snel; hun loopvlak is licht kegelvormig (typisch 1:20 of 1:40). Loopt de wielset naar één kant uit het midden, dan rolt het ene wiel op een grotere en het andere op een kleinere effectieve diameter. Omdat ze even snel draaien, legt het wiel met de grotere diameter meer afstand af per omwenteling, waardoor de wielset vanzelf een boog naar het spoormidden maakt. Zo stuurt de kegelvorm de as terug naar het midden, zonder dat de flenzen de rails hoeven te raken. De flenzen dienen daardoor alleen als laatste veiligheid tegen ontsporen, niet voor de gewone geleiding.' },
  { id: 44, categorie: 'Trein & spoor', vraag: 'Waarom die conus boven een kritische snelheid juist "hunting oscillation" veroorzaakt en er dempers nodig zijn', uitleg: 'Dezelfde kegelvorm die de wielset centreert, is eigenlijk een terugkoppeling die de as steeds naar het midden duwt, waardoor die om dat midden gaat slingeren met een zijwaartse-en-zwenkende beweging. Bij lage snelheid wordt die slingering genoeg gedempt, maar boven een kritische snelheid wordt ze instabiel en versterkt ze zichzelf: de wielset gaat zigzaggend tegen beide spoorstaven aan lopen, het zogenoemde hunting. Dat geeft harde stoten, slijtage en in het uiterste geval ontsporingsgevaar. Daarom krijgen draaistellen hydraulische slingerdempers (yaw dampers) en een goed gekozen wielprofiel en vering, die de kritische snelheid opschuiven en de slingering onderdrukken. Zo blijft de trein ook bij hoge snelheid stabiel in het spoor lopen.' },
  { id: 45, categorie: 'Trein & spoor', vraag: 'Waarom rails in bochten een lichte "cant" (verkanting) hebben en er een "cant deficiency" wordt toegestaan voor comfort', uitleg: 'In een bocht is een naar binnen gerichte kracht nodig om de trein de bocht door te sturen; door de buitenste spoorstaaf hoger te leggen (verkanting of cant) kantelt het spoor, zodat een deel van het gewicht die kracht levert en de zijwaartse belasting op rails en reizigers afneemt. De verkanting is berekend voor één bepaalde \'evenwichtssnelheid\', waarbij de reiziger geen zijwaartse kracht voelt. Omdat op hetzelfde spoor snelle en langzame treinen rijden, kun je niet voor iedereen de ideale cant leggen; men kiest een compromis en staat bewust een cant deficiency toe, het tekort aan verkanting waardoor snellere treinen nog een beetje zijwaartse kracht voelen. Die restkracht wordt begrensd op wat nog comfortabel en veilig is. Kantelbaktreinen kunnen dat tekort vergroten door de bak actief in de bocht te laten hellen.' },
  { id: 46, categorie: 'Trein & spoor', vraag: 'Waarom continu gelaste rails bij warmte kunnen "buckelen" (spoorspatting) en met een neutrale spanningstemperatuur worden gelegd', uitleg: 'Doorgelaste rails vormen een kilometerslang stalen geheel dat aan de uiteinden en door de bevestiging op de dwarsliggers wordt vastgehouden, zodat het bij warmte niet vrij kan uitzetten. In plaats van langer te worden, bouwt de rail dan enorme inwendige drukspanning op naarmate het warmer wordt. Wordt die druk groter dan de zijwaartse weerstand van het steenbed (ballast), dan wijkt het spoor plotseling zijwaarts uit in een boog: spoorspatting (buckling), wat ontsporing kan veroorzaken. Om dat te beheersen wordt de rail vastgelegd bij een bewust gekozen neutrale temperatuur (in ons klimaat vaak rond 20 à 25 graden), zodat de rail dan spanningsvrij is en de druk in de zomer en de trek in de winter beperkt en symmetrisch blijven. Een breed, goed aangedrukt ballastbed vergroot bovendien de weerstand tegen uitknikken.' },
  { id: 47, categorie: 'Trein & spoor', vraag: 'Waarom die lange rails het hele jaar enorme trek- en drukspanning opslaan zonder de oude voegen', uitleg: 'Vroeger lagen rails in korte stukken met voegen en kiertjes die de uitzetting door warmte opvingen, maar die voegen gaven lawaai, slijtage en onderhoud. Doorgelaste rails hebben die kiertjes niet, dus de rail kan bij warmte niet uitzetten omdat hij vast op de liggers en in de ballast zit. Verhinderde uitzetting verandert dan in inwendige spanning: bij warm weer staat de rail onder flinke drukspanning, bij kou onder trekspanning. Omdat staal erg stijf is, worden die spanningen heel groot terwijl de rail nauwelijks van lengte verandert. Het spoorontwerp, met een goed aangedrukt ballastbed en de juiste neutrale temperatuur, zorgt dat deze het jaar rond opgeslagen spanningen veilig binnen de perken blijven.' },
  { id: 48, categorie: 'Trein & spoor', vraag: 'Waarom een "check rail" aan de binnenkant van scherpe bochten het wiel tegenhoudt om ontsporen te voorkomen', uitleg: 'In heel scherpe bochten en bij wissels drukt de flens van het buitenwiel hard tegen de buitenste spoorstaaf, met kans dat het wiel omhoog klimt en ontspoort. Een check rail (contrarail) is een extra rail vlak binnen de binnenste spoorstaaf, met een smalle geul ertussen. Die contrarail vangt de achterkant van de binnenste wielflens op en houdt de hele wielset zijwaarts op zijn plaats, zodat het buitenwiel niet tegen of over de buitenrail kan klimmen. Zo wordt de zijdelingse geleiding over beide kanten verdeeld en blijft de speling binnen veilige grenzen. Bij wisselkruisingen zorgt de check rail er bovendien voor dat het wiel de juiste kant van het hartstuk volgt.' },
  { id: 49, categorie: 'Trein & spoor', vraag: 'Waarom een trein met "dynamische remming" de tractiemotoren als generator gebruikt en energie terugvoedt', uitleg: 'De elektromotoren die een trein aandrijven, kunnen ook andersom werken: laat je ze door de wielen ronddraaien in plaats van dat zij aandrijven, dan werken ze als generator en zetten ze de bewegingsenergie van de trein om in stroom. Die opgewekte stroom levert een tegenwerkende kracht die de trein afremt, zonder mechanische wrijving van remblokken. Bij weerstandsremming wordt die energie in weerstanden als warmte verstookt, maar bij regeneratief remmen gaat de stroom via de bovenleiding terug het net op, waar andere treinen hem gebruiken. Dat bespaart energie en spaart de mechanische remmen flink. Regeneratie werkt alleen zolang er iemand op het net stroom afneemt en bij hogere snelheden; bij heel lage snelheid nemen de wrijvingsremmen het over.' },
  { id: 50, categorie: 'Trein & spoor', vraag: 'Waarom de lage staal-op-staal-adhesie een trein kilometers laat nodig hebben om te stoppen', uitleg: 'Remmen berust op de wrijving tussen wiel en rail, en de maximale remkracht is de aslast maal de wrijvingscoëfficiënt (de grip). Tussen glad staal en glad staal is die grip heel laag, in de orde van 0,1 tot 0,2, veel lager dan tussen rubber en asfalt. Daardoor kan een trein maar een fractie van de valversnelling aan vertraging opbrengen zonder dat de wielen blokkeren en glijden. Bij de hoge snelheid en enorme massa van een trein levert die kleine vertraging een remweg op van honderden meters tot ruim een kilometer. Daarom moeten treinen ver vooruit anticiperen op seinen en kunnen ze niet op zicht stoppen; nat blad of vocht verlaagt de grip nog verder, wat zandstrooiers moeten compenseren.' },
  { id: 51, categorie: 'Trein & spoor', vraag: 'Waarom "sanding" (zand voor de wielen) bij nat blad op de rails in de herfst de grip herstelt', uitleg: 'In de herfst pletten de zware wielen afgevallen blad tot een dun, glad en glibberig laagje op de rail. Staal op staal heeft al weinig grip, en dat laagje maakt het nog gladder, zodat een trein doorslipt of doorschiet bij remmen. Vlak voor het wiel blaast de trein daarom zand op de rail; de harde kwartskorrels breken door de gladde film heen en verhogen de wrijving. De korrels worden in het contactvlak fijngedrukt en vormen kleine houvastpuntjes, waardoor optrekken en remmen weer werken. Moderne treinen doseren dat zand automatisch zodra ze slip of glijden meten, precies onder het juiste wiel.' },
  { id: 52, categorie: 'Trein & spoor', vraag: 'Waarom een pantograaf een koolstofsleepstuk heeft dat expres slijt om de dure koperdraad te sparen', uitleg: 'De stroomafnemer (pantograaf) schuurt langs de bovenleiding en door dat glijdende contact slijt er altijd iets weg; de vraag is alleen wat. Men kiest bewust koolstof (grafiet) als het onderdeel dat opoffert, omdat het zacht is, zichzelf smeert en zo de veel duurdere koperdraad spaart. Grafiet dooft bovendien de vonkboog die ontstaat als het contact even loslaat, wat inbranden en putjes in de draad beperkt. De koolstukjes zijn goedkoop en snel te vervangen bij onderhoud, terwijl kilometers koperdraad vervangen enorm duur zou zijn.' },
  { id: 53, categorie: 'Trein & spoor', vraag: 'Waarom een spoorstroomkring een trein detecteert doordat de assen het circuit kortsluiten', uitleg: 'Bij een spoorstroomkring staat er een lage spanning tussen de twee rails van een baanvak, en aan het eind meet een relais of er stroom loopt. Zonder trein loopt die stroom en houdt het relais het vak als \'vrij\' aan. Rijdt een trein het vak in, dan verbinden de stalen assen en wielen de twee rails met elkaar (een kortsluiting), de stroom vloeit nu via de assen weg, het relais valt af en het vak wordt als \'bezet\' gemeld. Het mooie is dat elke storing, zoals een gebroken rail of stroomuitval, óók het relais laat afvallen, dus altijd naar de veilige \'bezet\'-melding leidt.' },
  { id: 54, categorie: 'Trein & spoor', vraag: 'Waarom hogesnelheidslijnen vaak ballastloos (op beton) worden gebouwd, omdat losse ballast bij 300 km/u wegwaait', uitleg: 'Bij 300 km/u wekken de onderkant van de trein en de luchtdruk tussen trein en spoor zulke sterke luchtstromen op dat losse steenslag (ballast) omhoog kan worden gezogen en weggeslingerd, wat gevaarlijke projectielen en schade geeft. Daarom legt men de rails op een doorlopende betonnen plaat (slab track), zodat er geen los materiaal meer is dat kan opwaaien. Zo\'n vaste baan houdt de exacte ligging ook veel beter vast, terwijl losse ballast onder de belasting langzaam verschuift en steeds opnieuw moet worden aangestampt. De hogere aanlegkosten verdien je terug met veel minder onderhoud en de nauwkeurige ligging die je bij hoge snelheid nodig hebt.' },
  { id: 55, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom een schroef "cavitatie" krijgt: de druk daalt zo laag dat het water kookt en imploderende belletjes het metaal wegvreten', uitleg: 'Aan de zuigkant van een snel draaiend schroefblad stroomt het water zo snel dat de druk er sterk daalt; volgens de wet van Bernoulli gaat hogere snelheid samen met lagere druk. Zakt die druk onder de dampspanning, dan \'kookt\' het water bij gewone temperatuur en vormt het dampbelletjes. Stromen die belletjes mee naar een gebied met hogere druk, dan klappen ze heftig dicht en schieten ze een piepklein waterstraaltje met een enorme drukpiek tegen het metaal. Dat gebeurt keer op keer, waardoor het metaal vermoeit en er kleine putjes worden uitgeslagen (cavitatie-erosie). Cavitatie kost bovendien stuwkracht en maakt veel lawaai en trillingen.' },
  { id: 56, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom marineschroeven scheef (skewed) en met veel bladen zijn, om cavitatiegeluid te minimaliseren', uitleg: 'Achter de scheepsromp stroomt het water ongelijkmatig aan, en een sterk teruggebogen (skewed) blad glijdt daar geleidelijk in plaats van in één klap doorheen, zodat de drukschommelingen worden uitgesmeerd en cavitatie later en zachter begint. Meer bladen verdelen dezelfde stuwkracht over meer oppervlak, waardoor elk blad minder zwaar belast wordt en er minder sterke onderdruk ontstaat, wat cavitatie verder uitstelt. Minder en zachtere cavitatie betekent minder implosies en dus veel minder onderwatergeluid, wat cruciaal is voor onopvallende onderzeeërs en marineschepen. De bladvorm wordt zo ontworpen dat de belasting van tip tot wortel gelijkmatig verloopt, wat ook trillingen dempt.' },
  { id: 57, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom een "bulbous bow" een tegengestelde boeggolf maakt die de eigen boeggolf uitdooft en zo weerstand spaart', uitleg: 'De ronde bol onder de waterlijn duwt water vooruit en maakt zo een eigen golf die precies tegengesteld is aan de golf van de eigenlijke boeg. Twee tegengestelde golven doven elkaar deels uit (destructieve interferentie), waardoor de boeggolf kleiner wordt en er minder energie in golven verloren gaat (golfweerstand). Omdat die golfweerstand sterk van de snelheid afhangt, is de bulb afgestemd op een bepaalde snelheid en diepgang en werkt hij daarbuiten minder goed of zelfs averechts. Bij de ontwerpsnelheid levert dit een meetbare brandstofbesparing op, vooral bij grote, snelle schepen.' },
  { id: 58, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom een groot schip in ondiep water "squat" krijgt en dieper komt te liggen naarmate het sneller vaart', uitleg: 'In ondiep, nauw water moet het water dat het schip wegduwt zich met hogere snelheid door de krappe ruimte onder en naast de romp wringen. Sneller stromend water heeft een lagere druk (Bernoulli), dus onder de romp ontstaat onderdruk die het hele schip omlaag zuigt en vaak wat voorover laat kantelen; dit heet squat. Het effect groeit ongeveer met het kwadraat van de snelheid en wordt veel sterker naarmate er minder water onder de kiel overblijft. Kapiteins die dit onderschatten zijn al aan de grond gelopen, ook al gaf de zeekaart in rust genoeg diepte.' },
  { id: 59, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom "parametric rolling" ontstaat als golven de stabiliteit ritmisch veranderen en het schip zichzelf aan het slingeren praat', uitleg: 'Vaart een schip recht op de golven af, dan verandert de vorm van het ondergedompelde deel steeds terwijl golfberg en golfdal langs de romp lopen, waardoor de stabiliteit ritmisch sterker en zwakker wordt. Valt die stabiliteitsschommeling ongeveer twee keer per natuurlijke slingerperiode samen, dan krijgt elke slinger er net op tijd energie bij en bouwt de beweging zichzelf op tot heel grote hoeken; dit heet parametrische resonantie. Het is dus geen gewone resonantie op een duwende kracht van buitenaf, maar een slingering die groeit doordat de stabiliteit zelf verandert; het treft vooral slanke schepen zoals containerschepen. De uitslagen kunnen zo groot worden dat containers overboord slaan, wat leidde tot waarschuwingssystemen aan boord.' },
  { id: 60, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom containerschepen een "lashing bridge" en verdraaide sjorstangen gebruiken om stapels tegen slingeren te borgen', uitleg: 'De containerstapels aan dek krijgen door slingeren, stampen en wind grote krachten te verduren, die vooral op de onderste containers en hun draaisloten (twistlocks) trekken en drukken. Een lashing bridge is een verhoogd stalen loopplatform waarmee je de sjortangen hoger kunt vastmaken, zodat je hoge stapels over meer lagen vastzet en de druk op de onderste containers daalt. De diagonaal geplaatste sjortangen vangen de zijwaartse krachten op en verbinden de containerhoeken met het dek, zodat de hele stapel stijver wordt. Zonder die combinatie zou je veel lager moeten stapelen en dus minder kunnen laden.' },
  { id: 61, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom een "Plimsoll-merk" aparte lijnen heeft voor zoet, zout, tropisch en winterwater vanwege dichtheidsverschil', uitleg: 'Een schip zakt tot het gewicht van het weggeduwde water gelijk is aan zijn eigen gewicht (wet van Archimedes); is dat water minder dicht, dan moet het schip dieper zakken voor hetzelfde gewicht. Zoet water is lichter dan zout water, en warm tropisch water is lichter dan koud winterwater, dus hetzelfde beladen schip ligt in die gevallen dieper. De streepjes van het Plimsoll-merk geven per situatie aan hoe diep het schip maximaal mag liggen, zodat er altijd genoeg boord boven water (reservedrijfvermogen) overblijft. Zo mag een schip in warm zoet water dieper geladen worden dan in koud, zout water op de ruige Noord-Atlantische route.' },
  { id: 62, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom "degaussing"-spoelen het magnetische veld van een stalen romp neutraliseren tegen magnetische zeemijnen', uitleg: 'Een stalen romp wordt in het aardmagnetisch veld zelf een beetje magnetisch en verstoort daardoor lokaal het aardveld; elk schip heeft zo een eigen magnetische \'handtekening\'. Magnetische zeemijnen voelen juist die verstoring en ontploffen als een schip passeert. Degaussing-spoelen zijn stroomdraden door de romp die een tegengesteld magnetisch veld opwekken, precies genoeg om de eigen magnetisme van het schip op te heffen, zodat er bijna geen verstoring overblijft. De stroom door die spoelen wordt bijgeregeld naar koers en breedtegraad, omdat de benodigde compensatie meedraait met de stand van het schip in het aardveld.' },
  { id: 63, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom een roer pas werkt als er schroefwater langs stroomt — daarom stuurt een schip nauwelijks zonder gas', uitleg: 'Een roer stuurt door als een soort vleugel een zijwaartse kracht in het water op te wekken, en die kracht groeit met het kwadraat van de snelheid waarmee het water langs het roerblad stroomt. Draait de schroef vlak vóór het roer, dan spuit die een krachtige waterstraal recht tegen het roer, zodat er zelfs bij lage vaart veel stroming en dus veel stuurkracht is. Zonder aandrijving stroomt er alleen water langs het roer door de eigen snelheid van het schip, en die is laag, dus een bijna stilliggend of uitrollend schip stuurt nauwelijks. Een korte stoot gas geeft daarom meteen stuurkracht, ook al versnelt het schip nauwelijks.' },
  { id: 64, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom een "azipod" de hele schroefgondel kan draaien en zo een apart roer overbodig maakt', uitleg: 'Een azipod is een gondel buiten de romp met een elektromotor die de schroef direct aandrijft, en die gondel kan volledig 360 graden ronddraaien. Omdat je de stuwstraal in elke richting kunt richten, levert de schroef zelf de zijwaartse kracht waarvoor je anders een apart roer nodig had, dus dat roer wordt overbodig. Dit geeft uitzonderlijke wendbaarheid: het schip kan zijwaarts verhalen en op de plek draaien, en de trekkende schroef stroomt in schoon water aan wat vaak zuiniger is. Doordat de motor buitenboord zit, vervallen ook de lange aandrijfassen en tandwielkasten binnenin, wat ruimte en trillingen bespaart.' },
  { id: 65, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom "free surface effect" — klotsend water in een half gevulde tank — de stabiliteit drastisch verlaagt', uitleg: 'In een half gevulde tank schuift de vloeistof bij elke slinger mee naar de laagste kant, zodat dat gewicht steeds met de rolbeweging meebeweegt. Dat meelopende gewicht werkt de oprichtende kracht tegen, alsof het zwaartepunt van het schip virtueel omhoog schuift, en dat verlaagt de effectieve stabiliteit. Hoe erg dit is hangt af van het wateroppervlak in de tank, en vooral van de breedte: die telt tot de derde macht mee, terwijl de hoeveelheid vloeistof er nauwelijks toe doet. Daarom deelt men tanks in de lengte op met schotten en geldt de regel: liefst tanks helemaal vol of helemaal leeg. Onderschatting van dit \'free surface effect\' heeft al schepen doen kapseizen.' },
  { id: 66, categorie: 'Scheepvaart & maritiem', vraag: 'Waarom ballasttanks met vreemd zeewater een wereldwijd invasieprobleem gaven en nu verplicht gezuiverd worden', uitleg: 'Schepen pompen in de vertrekhaven zeewater in ballasttanks om stabiel te liggen en lozen dat ergens anders weer; met dat water reizen larven, plankton, bacteriën en kleine dieren mee naar heel andere zeeën. Losgelaten in een nieuw gebied zonder natuurlijke vijanden kunnen die exoten zich explosief vermeerderen en de inheemse soorten verdringen, met grote schade voor natuur en economie. Daarom verplicht het Ballastwaterverdrag behandeling, bijvoorbeeld filteren en dan met UV-licht of chemicaliën ontsmetten, of het ballastwater midden op zee verversen waar de overlevingskans klein is. Het doel is het aantal levende organismen in geloosd water onder strenge grenzen te brengen.' },
  { id: 67, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom "detonatie" (klop) een drukgolf is die de vlam ongecontroleerd laat ontploffen en zuigers doorboort', uitleg: 'Normaal ontsteekt de bougie het mengsel en brandt een vlamfront rustig door de cilinder. Bij detonatie (klop) wordt de rest van het nog onverbrande mengsel door de oplopende druk en hitte zo ver samengeperst dat het spontaan en bijna in één klap zelf ontbrandt. Die bijna-explosie stuurt scherpe drukgolven door de cilinder, hoorbaar als \'pingelen\', en de hoge druk- en temperatuurpieken kunnen de zuiger, ringen en cilinderkop beschadigen. Een hogere octaanwaarde maakt de brandstof beter bestand tegen dat spontaan ontbranden en voorkomt zo klop.' },
  { id: 68, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom "pre-ignition" gevaarlijker is dan klop: de lading ontsteekt al vóór de bougievonk, door een gloeiend puntje', uitleg: 'Bij pre-ignition ontbrandt het mengsel al vóórdat de bougie vonkt, doordat een gloeiend heet plekje, zoals een oververhitte klep, koolaanslag of bougiepunt, het zelf aansteekt. Omdat de verbranding te vroeg begint, loopt de druk al op terwijl de zuiger nog omhoog komt, dus de motor werkt tegen zichzelf in en de piekdruk wordt extreem hoog. Die hitte maakt het gloeiende plekje nog heter, waardoor het verschijnsel zichzelf versterkt en binnen een paar omwentelingen de motor kan slopen. In tegenstelling tot klop, dat pas ná de vonk komt en met een latere ontsteking te temmen is, kun je pre-ignition niet via de ontsteking bijsturen, en daarom is het gevaarlijker.' },
  { id: 69, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom moderne downsize-turbomotoren gevoelig zijn voor "LSPI", waarbij de olie zelf vroegtijdig ontbrandt', uitleg: 'LSPI (low-speed pre-ignition) treft kleine, zwaar belaste turbomotoren die al bij lage toeren veel lucht en dus hoge druk en temperatuur in de cilinder hebben. Onder die omstandigheden kan een minuscuul druppeltje motorolie, vermengd met brandstof, van de cilinderwand loskomen en het mengsel vóór de bougievonk aansteken. De daaropvolgende ongecontroleerde, zeer krachtige verbranding lijkt op zware klop en kan in één enkele slag al de zuiger of drijfstang breken. De samenstelling van de olie, vooral het calciumgehalte, blijkt sterk te bepalen hoe groot de kans op LSPI is, en daarom zijn er speciale olievoorschriften ontwikkeld.' },
  { id: 70, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom variabele kleptiming (VVT) de motor bovenin meer lucht laat happen en onderin soepel houdt', uitleg: 'Het beste moment om de kleppen te openen en sluiten hangt af van het toerental, omdat de luchtstroom bij hoge toeren heel anders beweegt dan bij lage. Variabele kleptiming (VVT) verdraait de nokkenas zodat bij hoge toeren de inlaatklep langer openblijft; de vaart die de instromende lucht al heeft, propt de cilinder dan voller (hogere vulling) en levert meer vermogen. Bij lage toeren beperkt het systeem juist de periode dat in- en uitlaatklep tegelijk open staan, zodat er weinig verse lucht wegvlucht en weinig uitlaatgas terugstroomt, wat een rustig, soepel stationair loopgedrag geeft. Zo geeft één motor zowel veel trekkracht onderin als piekvermogen bovenin.' },
  { id: 71, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom veel klepoverlap een sportmotor stationair hobbelig laat lopen maar bovenin meer vermogen geeft', uitleg: 'Klepoverlap is het moment rond de bovenste stand van de zuiger waarop de inlaat- en uitlaatklep even tegelijk open staan. Bij hoge toeren helpt dat: de snel uitstromende uitlaatgassen zuigen als het ware verse lucht mee naar binnen (scavenging), wat de cilinder beter vult. Bij lage toeren en stationair ontbreekt die snelheid, waardoor uitlaatgas terug de inlaat in wordt geduwd en verse lucht ongebruikt naar de uitlaat lekt, zodat de verbranding per slag onregelmatig wordt. Dat wisselvallige mengsel veroorzaakt het typische hobbelende, ongelijke stationair loopgedrag van sportieve nokkenassen. De ontwerper ruilt dus stationaire rust in voor extra vulling en vermogen hoog in de toeren.' },
  { id: 72, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom een dieselmotor tot zelfontbranding comprimeert en dus geen bougie maar gloeikaarsen voor de koude start heeft', uitleg: 'Een dieselmotor gebruikt geen vonk: hij perst de lucht zo sterk samen dat die vanzelf heter wordt dan de temperatuur waarbij ingespoten diesel spontaan ontbrandt, en zo ontsteekt de brandstof zichzelf. Bij een koude motor koelen de koude cilinderwanden die samengeperste lucht echter zo veel af dat het net niet heet genoeg wordt om betrouwbaar te ontsteken. Gloeikaarsen zijn elektrische verwarmingselementjes die de verbrandingsruimte voorverwarmen, zodat er bij het starten toch genoeg hitte is voor zelfontbranding. Zodra de motor draait en op temperatuur is, houdt de compressiewarmte de ontsteking vanzelf gaande en zijn de gloeikaarsen niet meer nodig.' },
  { id: 73, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom een dieselmotor bij te lichte belasting "wet stacking" krijgt: onverbrande diesel verglaast de uitlaat', uitleg: 'Draait een dieselmotor lang met te weinig belasting, dan wordt de verbranding niet heet genoeg en verbrandt de ingespoten diesel niet volledig. De onverbrande diesel en roet slaan neer in de cilinders, op de kleppen, in de turbo en in de uitlaat, waar ze een olieachtige, glazige laag vormen; dat \'natte\' zit in de naam wet stacking. Die afzettingen verlagen het rendement, verstoppen de uitlaat en kunnen kleppen en turbo aantasten. Je voorkomt het door de motor af en toe flink te belasten, zodat hij heet genoeg wordt om die afzettingen weg te branden.' },
  { id: 74, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom een turbo "lag" heeft: de uitlaatgassen moeten het schoepenwiel eerst op toeren brengen', uitleg: 'Een turbo wordt aangedreven door de uitlaatgassen: die laten een turbinewiel draaien, dat via een gemeenschappelijke as het compressorwiel meeneemt dat de motor extra lucht geeft. Geef je plots gas, dan moet de energie in de uitlaatgassen eerst het draaiende wiel op toeren brengen voordat er merkbare laaddruk is, want dat wiel heeft massa en wil door zijn traagheid niet meteen sneller draaien. Die vertraging tussen gasgeven en drukopbouw is de turbolag; ze is groter naarmate het wiel zwaarder is en de uitlaatstroom bij lage toeren geringer. Oplossingen zijn lichtere wielen, kleinere of dubbele turbo\'s, verstelbare turbinegeometrie en elektrische ondersteuning om die traagheid te overbruggen.' },
  { id: 75, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom een "wastegate" de laaddruk begrenst door uitlaatgas om de turbine heen te leiden', uitleg: 'Zonder regeling zou een turbo bij hoge toeren steeds meer laaddruk blijven opbouwen tot schadelijke waarden, omdat er dan volop uitlaatgas de turbine aandrijft. Een wastegate is een regelbare klep die een deel van het uitlaatgas óm de turbine heen laat stromen, zodat de turbine minder energie krijgt en niet verder versnelt. Door dat teveel aan gas af te laten, wordt de laaddruk op een veilig ingesteld maximum gehouden, meestal geregeld door een membraan of elektronica die de actuele druk terugkoppelt. Zo blijft de motor beschermd tegen overdruk, terwijl de gewenste maximale laaddruk wél volledig benut wordt.' },
  { id: 76, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom een intercooler de hete perslucht koelt zodat er meer zuurstofmassa in de cilinder past', uitleg: 'Als de turbo lucht samenperst, wordt die lucht flink warm, en warme lucht is bij dezelfde druk ijler (minder dicht). Het vermogen hangt af van de hoeveelheid zuurstof die per slag in de cilinder komt, dus hete, ijle lucht bevat minder zuurstof en levert minder vermogen. Een intercooler is een soort radiateur die de samengeperste lucht afkoelt voordat die de cilinder in gaat; koelere lucht is dichter, zodat er bij dezelfde druk meer zuurstof binnenkomt. Koelere lucht vermindert bovendien de kans op klop, waardoor je een gunstiger ontstekingstijdstip kunt gebruiken en er extra rendement bij komt.' },
  { id: 77, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom een automaat een "torque converter" met vloeistofkoppeling heeft en pas boven een "stall speed" kracht doorgeeft', uitleg: 'Een koppelomvormer geeft kracht door via olie: een pomp aan de motorzijde slingert olie tegen een turbine die aan de wielen vastzit, dus er is geen starre verbinding en de motor kan blijven draaien terwijl de auto stilstaat. Bij lage toeren is de oliestroom te zwak om de stilstaande turbine mee te trekken, waardoor er tot een bepaald toerental (de stall speed) nauwelijks kracht doorkomt en de auto met draaiende motor kan blijven staan. Boven dat toerental wordt de oliestroom sterk genoeg om de turbine mee te nemen en de auto te laten optrekken. Een tussenwieltje (stator) keert de terugstromende olie om, waardoor de omvormer bij een groot snelheidsverschil het koppel zelfs vermenigvuldigt en zo extra trekkracht bij het wegrijden geeft.' },
  { id: 78, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom die converter een "lock-up clutch" heeft die op de snelweg mechanisch vergrendelt tegen sliprendementverlies', uitleg: 'Een koppelomvormer geeft kracht door via een oliestroom, en tussen de pomp en de turbine zit altijd een klein snelheidsverschil (slip), waarbij een deel van de energie in warmte verloren gaat. Bij constante snelheid op de snelweg is dat verlies onnodig en kost het extra brandstof. Een lock-up clutch is een mechanische koppeling die de pomp en turbine bij genoeg snelheid rechtstreeks aan elkaar klemt, zodat de slip verdwijnt en de kracht bijna verliesvrij doorgaat, alsof er een directe as zit. Bij optrekken of manoeuvreren gaat de lock-up weer los, zodat de soepele, koppelvermenigvuldigende oliekoppeling terugkomt.' },
  { id: 79, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom een "limited slip differential" voorkomt dat één doorslippend wiel al het koppel opslokt', uitleg: 'Een gewoon (open) differentieel verdeelt het koppel altijd gelijk over beide wielen, maar laat ze wel verschillend snel draaien; het maximaal doorgeefbare koppel wordt daardoor bepaald door het wiel met de minste grip. Verliest één wiel zijn grip, dan draait dat vrijwel weerstandloos door, en omdat de verdeling gelijk blijft, krijgt het andere wiel evenveel, dus bijna geen, koppel en blijft de auto staan. Een limited slip differential zet tussen de twee ashelften een koppeling, bijvoorbeeld met wrijvingsplaten of een slim tandwielmechanisme, die het snelheidsverschil tegenwerkt en zo koppel naar het wiel met de meeste grip stuurt. Zo kan het wiel met grip echt trekken, in plaats van dat alle kracht in het doorslippende wiel wegvloeit.' },
  { id: 80, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom "torque steer" ontstaat bij sterke voorwielaandrijvers met ongelijk lange aandrijfassen', uitleg: 'Bij voorwielaandrijving zit de motor vaak niet in het midden, waardoor de linker en rechter aandrijfas verschillend lang zijn en onder een andere hoek staan. Trek je hard op, dan verdraaien die twee assen door hun verschillende lengte en stijfheid ongelijk, en verschilt ook de hoek waaronder de kracht bij het wiel aangrijpt, zodat de twee voorwielen ongelijke trek- en stuurkrachten krijgen. Dat verschil trekt via de stuuras aan het stuur, waardoor de auto onder vol gas naar één kant wil sturen; dat heet torque steer. Constructies zoals even lange assen met een tussenlager, of een aangepaste stuurgeometrie, dringen dit effect terug.' },
  { id: 81, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom "brake fade" komt door kokende remvloeistof (vapor lock) óf door uitgassende nieuwe remblokken', uitleg: 'Bij hard remmen wordt bewegingsenergie in warmte omgezet, en die hitte kan zo hoog oplopen dat de remvloeistof gaat koken; de dampbellen die dan ontstaan zijn samendrukbaar, dus het pedaal zakt weg en de druk komt niet meer bij de remzuigers aan (vapor lock). Remvloeistof neemt na verloop van tijd vocht op, wat het kookpunt verlaagt en dit erger maakt. Een tweede oorzaak: nieuwe of oververhitte remblokken geven bij hoge temperatuur gassen en harsen af die een dun gaslaagje tussen blok en schijf vormen, waardoor de grip tijdelijk daalt. In beide gevallen neemt de remkracht af bij dezelfde pedaaldruk; verse remvloeistof en goed ingereden remblokken beperken het probleem.' },
  { id: 82, categorie: 'Auto — motoren & aandrijving', vraag: 'Waarom een dubbelekoppelingsbak de volgende versnelling al voorselecteert en zo schakelt zonder krachtonderbreking', uitleg: 'Een dubbelekoppelingsbak heeft twee aparte koppelingen en assen, meestal één voor de oneven en één voor de even versnellingen. Terwijl de ene koppeling de huidige versnelling aandrijft, wordt op de andere as de volgende versnelling alvast klaargelegd, zonder dat die koppeling al aangrijpt. Bij het schakelen gaat de ene koppeling open en de andere vrijwel tegelijk dicht, zodat de aandrijving overspringt op de al voorgekozen versnelling zonder dat de kracht naar de wielen even wegvalt. Dat geeft supersnelle, schokvrije schakelingen; de computer voorspelt daarbij welke versnelling waarschijnlijk volgt, om die op tijd voor te selecteren.' },
  { id: 83, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom een transistor kleiner maken hem sneller én lekker maakt — lekstroom werd de grens van Moore\'s law', uitleg: 'Kleinere transistors hebben kortere kanalen en minder capaciteit, waardoor ze sneller schakelen en per bewerking minder energie kosten. Maar bij het verkleinen wordt de isolatielaag onder de gate zo flinterdun en het kanaal zo kort dat elektronen er kwantummechanisch doorheen \'tunnelen\' en het kanaal niet meer helemaal dichtgaat: er lekt stroom, óók als de transistor \'uit\' zou moeten staan. Die lekstroom groeit ongunstig mee bij verder verkleinen en gaat de schakelenergie overheersen, zodat kleiner maken niet meer vanzelf zuiniger is. Dit doorbrak de oude vuistregel (Dennard-schaling) en werd, samen met de warmteafvoer, een fundamentele rem op de vooruitgang achter de wet van Moore.' },
  { id: 84, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom "dark silicon" bestaat: je kunt niet alle transistors tegelijk aanzetten zonder de chip te laten smelten', uitleg: 'Sinds de oude schaalregel (Dennard) niet meer opgaat, daalt het verbruik per transistor niet meer evenredig met de verkleining, terwijl het aantal transistors per chip wél blijft groeien. Daardoor zou alle transistors tegelijk laten schakelen meer warmte geven dan de chip kwijt kan, en dus veel te heet worden. Om binnen dat warmtebudget te blijven, moet op elk moment een deel van de chip uit of op laag vermogen staan; dat inactieve deel heet \'dark silicon\'. Ontwerpers benutten dit door gespecialiseerde deelblokken (accelerators) in te bouwen die alleen aangaan wanneer je ze nodig hebt, in plaats van één groot blok dat altijd draait.' },
  { id: 85, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom DRAM elke paar milliseconden ververst moet worden omdat de lading uit de minuscule condensatortjes lekt', uitleg: 'Een DRAM-cel bewaart één bit als een beetje elektrische lading op een piepklein condensatortje, dat via één transistor wordt aangesloten. Dat condensatortje is niet perfect: door lekstroom via de transistor en het isolatiemateriaal vloeit de lading langzaam weg, waardoor het opgeslagen niveau binnen een paar milliseconden onbetrouwbaar wordt. Om de gegevens te bewaren leest een \'refresh\' periodiek elke rij uit en schrijft de opgefriste waarde meteen terug, waardoor de lading weer wordt aangevuld. Dat constant verversen kost stroom en tijd, en het is de reden dat DRAM \'dynamisch\' heet, in tegenstelling tot SRAM dat zijn waarde zonder refresh vasthoudt.' },
  { id: 86, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom "Rowhammer" een beveiligingslek is: snel wisselen van één geheugenrij klapt bits in de buurrij om', uitleg: 'In modern DRAM liggen de geheugenrijen zó dicht op elkaar dat het razendsnel en herhaald aanspreken van één rij, via elektrische koppeling, de lading in de buurrijen versneld laat weglekken. Lekt er tussen twee gewone verversingen genoeg lading weg, dan kan een bit in zo\'n buurrij omklappen zonder dat die rij zelf werd aangesproken. Een aanvaller kan dit expres uitlokken door bewust op \'aanvaller\'-rijen te \'hameren\' en zo bits veranderen in geheugen waar hij eigenlijk niet bij mag, bijvoorbeeld in de tabellen die geheugenrechten regelen. Zo wordt een fysiek betrouwbaarheidsprobleem een echt beveiligingslek; een tegenmaatregel is het gericht extra verversen van juist die buurrijen.' },
  { id: 87, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom SRAM sneller maar veel groter is dan DRAM — zes transistors per bit tegen één condensator', uitleg: 'Een SRAM-cel bewaart een bit in een terugkoppelluslus van meestal zes transistors, die de waarde actief vasthoudt zolang er stroom is. Omdat die waarde meteen als een stabiel spanningsniveau klaarstaat en niet uit een zwak ladinkje hoeft te worden opgehaald en versterkt, is uitlezen razendsnel en is geen refresh nodig. Een DRAM-cel gebruikt daarentegen maar één transistor en één condensatortje, wat veel minder oppervlak per bit kost en dus veel meer geheugen op dezelfde ruimte geeft. Het is dus een afweging: SRAM is snel maar duur en groot per bit (voor caches), DRAM is trager maar compact en goedkoop (voor werkgeheugen).' },
  { id: 88, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom flash-geheugen slijt: elke schrijfbeurt beschadigt de isolatielaag een klein beetje', uitleg: 'Flash bewaart een bit als lading op een geïsoleerd \'zwevend\' poortje, afgeschermd door een heel dun isolatielaagje (tunnel-oxide). Bij schrijven en wissen worden elektronen met een sterk elektrisch veld dwars door dat laagje geduwd, en telkens blijven er een paar elektronen in het laagje hangen of ontstaan er minuscule beschadigingen. Na vele duizenden tot honderdduizenden keren is dat laagje zo aangetast dat het lading gaat lekken of niet meer betrouwbaar laat schrijven, waardoor de cel zijn waarde niet meer vasthoudt. Deze slijtage per cel is de reden dat flash maar een eindig aantal schrijf- en wisbeurten heeft en dat de controller de belasting over alle cellen spreidt.' },
  { id: 89, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom een SSD "wear leveling" en "TRIM" gebruikt om slijtage te spreiden en snelheid te houden', uitleg: 'Omdat elke flash-cel maar een beperkt aantal schrijfbeurten overleeft, verdeelt de controller met \'wear leveling\' de schrijfacties bewust over alle blokken, zodat niet steeds dezelfde cellen slijten en de hele schijf gelijkmatig veroudert. Flash kan bovendien niet zomaar overschrijven: een blok moet eerst helemaal gewist worden voordat er opnieuw in kan worden geschreven, wat extra kopieerwerk (write amplification) oplevert. Met het TRIM-commando vertelt het besturingssysteem welke pagina\'s bij verwijderde bestanden horen en dus niet meer nodig zijn, zodat de controller die alvast kan wissen en niet nodeloos meekopieert. Zo blijft de schrijfsnelheid hoog en gaan de cellen langer mee.' },
  { id: 90, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom een schakelende voeding "dead time" inbouwt zodat de twee schakelaars nooit tegelijk aan staan (shoot-through)', uitleg: 'In een brugschakeling staan twee schakelaars (transistors) in serie tussen de plus en de min van de voeding, en normaal is er maar één van beide tegelijk geleidend. Omdat echte transistors niet oneindig snel uitschakelen, zou de ene meteen inschakelen terwijl de andere nog niet helemaal dicht is beide even laten geleiden, wat een kortsluiting dwars over de voeding vormt (shoot-through) met een vernietigende stroompiek. Daarom last men een korte \'dode tijd\' in waarin beide schakelaars uit staan, zodat de uitschakelende transistor gegarandeerd is gestopt voordat de andere aangaat. Die dode tijd is een compromis: te kort geeft kortsluiting, te lang kost rendement en geeft vervorming.' },
  { id: 91, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom een MOSFET zijn schakelsnelheid vooral uit "gate charge" haalt, niet uit de kanaalweerstand', uitleg: 'Een MOSFET stuur je met een spanning op zijn gate, maar die gate vormt samen met het kanaal een klein condensatortje dat je eerst moet op- of ontladen voordat de transistor van geleidend naar sperrend omschakelt. De schakeltijd hangt dus vooral af van hoe snel de aansturing die gate-lading kan aan- en afvoeren, en dat wordt bepaald door de beschikbare stuurstroom. De kanaalweerstand (RDS(on)) bepaalt daarentegen vooral het verlies wanneer de transistor volledig aan staat, niet de snelheid van het omschakelen zelf. Daarom is de totale gate-lading, meer dan de kanaalweerstand, de bepalende maat voor de schakelverliezen en dus voor het gedrag bij hoge schakelfrequenties.' },
  { id: 92, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom elektrolytische condensatoren bol gaan staan als hun vloeistof uitdroogt (het "capacitor plague"-schandaal)', uitleg: 'Een natte elektrolytische condensator bevat een vloeibaar elektrolyt dat samen met een dun oxidelaagje op aluminiumfolie de eigenlijke isolatie vormt. Door veroudering, hitte of een verkeerd samengesteld elektrolyt ontstaan er binnenin gassen en verdampt het elektrolyt, waardoor de druk oploopt en het dopje via de ingekerfde bovenkant bol gaat staan of openscheurt. Bij het \'capacitor plague\' rond het jaar 2000 was een instabiel elektrolytmengsel de oorzaak, waardoor massaal condensatoren te vroeg gingen gassen en uitvielen. Het opbollen is dus een zichtbaar teken dat de condensator zijn capaciteit kwijtraakt en van binnen slechter geleidt, wat vooral in voedingen tot storingen leidt.' },
  { id: 93, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom loodvrij soldeer spontaan "tin whiskers" groeit die apparatuur kortsluiten — een NASA-nachtmerrie', uitleg: 'Zuiver tin, zoals in loodvrij soldeer, kan spontaan haarfijne kristallijne draadjes laten uitgroeien, de \'tin whiskers\', die na verloop van tijd millimeters lang worden. Ze ontstaan doordat inwendige spanning in de tinlaag, bijvoorbeeld door temperatuurwisselingen, zich ontlaadt door tin langs de korrelranden naar buiten te persen. Vroeger onderdrukte een paar procent lood in het soldeer die groei goed, maar sinds loodvrij solderen wettelijk verplicht werd, is het probleem terug. Zo\'n geleidend draadje kan naburige contacten kortsluiten en heeft in ruimtevaart- en militaire elektronica al tot uitval geleid, wat het een gevreesd betrouwbaarheidsprobleem maakt.' },
  { id: 94, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom een "brownout" (te lage spanning) elektronica meer beschadigt dan een korte stroomuitval', uitleg: 'Bij een volledige stroomuitval valt de apparatuur netjes uit en herstart later, maar bij een \'brownout\' blijft er wél spanning staan, alleen te laag. Een voeding die een vast vermogen moet leveren, trekt bij lagere ingangsspanning juist méér stroom om dat vermogen vol te houden, wat transformatoren, schakelaars en kabels laat oververhitten. Bovendien kunnen chips en microcontrollers bij te lage spanning in een halfwerkende, onbepaalde toestand blijven hangen in plaats van veilig te resetten, waardoor ze hun uitgangen verkeerd aansturen. Ook motoren en relais kunnen bij onderspanning blijven \'trekken\' zonder in te schakelen, wat extra warmte en slijtage geeft; daarom hebben goede voedingen een beveiliging die bij te lage spanning bewust uitschakelt.' },
  { id: 95, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom "metastabiliteit" een flip-flop tijdelijk in een onbeslisbare halftoestand tussen 0 en 1 laat hangen', uitleg: 'Een flip-flop moet zijn data-ingang stabiel hebben rond de klokflank, binnen een klein tijdvenster (de setup- en hold-tijd). Verandert het signaal juist in dat venster, dan wordt de interne terugkoppellus op een tussenpunt geladen en balanceert de uitgang even op een wankel evenwicht, precies tussen 0 en 1. Vanuit dat labiele punt zakt de flip-flop uiteindelijk wel naar een geldige 0 of 1, maar wánneer dat gebeurt is onvoorspelbaar en kan langer duren dan normaal, wat verderop foute uitlezingen geeft. Dit is onvermijdelijk bij het overnemen van signalen die niet met de klok meelopen; men beperkt het risico met een keten van meerdere flip-flops achter elkaar, die de kans op een overblijvende halftoestand snel verkleint.' },
  { id: 96, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom een "watchdog timer" een vastgelopen microcontroller automatisch herstart', uitleg: 'Een watchdog timer is een aparte aftellende teller die door de goed werkende software op tijd moet worden teruggezet (de watchdog \'aaien\') voordat hij nul bereikt. Zolang het programma normaal doorloopt, wordt de teller steeds op tijd bijgevuld en gebeurt er niets. Loopt de software echter vast in een eindeloze lus of raakt hij in een ongeldige toestand, dan blijft dat bijvullen uit en telt de watchdog helemaal af. Bij nul geeft hij een hardwarematige reset, waardoor de microcontroller vanzelf herstart naar een bekende begintoestand zonder dat er iemand aan te pas komt, wat vooral in onbemande of veiligheidskritische systemen belangrijk is.' },
  { id: 97, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom "electromigratie" koperspoortjes op een chip na jaren letterlijk wegslijt door de elektronenstroom', uitleg: 'In de flinterdunne koperbaantjes op een chip is de stroom zo geconcentreerd dat de stromende elektronen bij botsingen een duwtje geven aan de metaalatomen (de \'elektronenwind\'). Over lange tijd schuiven die atomen zo mee met de stroom: op de ene plek verdwijnt metaal en ontstaan er gaatjes (voids), terwijl het zich verderop ophoopt tot bultjes (hillocks). De gaatjes verhogen plaatselijk de weerstand tot het baantje uiteindelijk breekt, terwijl de ophopingen kortsluiting met een buurbaantje kunnen maken. Deze langzame, door de stroom aangedreven verplaatsing van metaal beperkt hoeveel stroom een baantje aankan en dus hoe lang het meegaat, en wordt bij verdere miniaturisering een steeds zwaardere ontwerpbeperking.' },
  { id: 98, categorie: 'Elektronica & halfgeleiders', vraag: 'Waarom een "band-gap referentie" een exacte spanning levert die niet met temperatuur meebeweegt', uitleg: 'Een bandgap-referentie combineert twee spanningen die tegengesteld op temperatuur reageren. De basis-emitterspanning van een transistor daalt als het warmer wordt, terwijl het verschil tussen twee zulke spanningen bij verschillende stroomsterktes juist stijgt met de temperatuur. Tel je die stijgende term met precies de juiste factor op bij de dalende term, dan heffen de temperatuureffecten elkaar grotendeels op, zodat de som over een breed temperatuurbereik vrijwel constant blijft. De uitkomst ligt rond de \'bandgap\'-spanning van silicium (ongeveer 1,2 volt), en daar dankt deze stabiele, temperatuurongevoelige referentie zijn naam aan.' },
  { id: 99, categorie: 'RF, antennes & signalen', vraag: 'Waarom bij hoge frequenties de stroom alleen door de buitenste micrometers van een draad loopt (skin-effect)', uitleg: 'Een wisselstroom in een draad wekt een wisselend magnetisch veld op, en dat veld wekt binnen in de draad zelf tegengestelde wervelstroompjes op (wetten van Faraday en Lenz). Die wervelstromen werken de stroom in de kern van de draad tegen en versterken hem aan de buitenkant, zodat de stroom naar het oppervlak wordt verdrongen. De diepte waarover de stroom nog echt loopt (de indringdiepte) wordt kleiner naarmate de frequentie hoger is, zodat bij hoge frequenties alleen een dun laagje van enkele micrometers aan de buitenkant meedoet. Omdat er zo minder bruikbare doorsnede overblijft, stijgt de weerstand met de frequentie; daarom gebruikt men bij hoge frequenties holle geleiders, buizen of litze-draad (veel dunne, geïsoleerde draadjes samen).' },
  { id: 100, categorie: 'RF, antennes & signalen', vraag: 'Waarom een "Yagi"-antenne richtwerking krijgt door passieve "directors" en een "reflector" naast het gevoede element', uitleg: 'Bij een Yagi-antenne wordt alleen het middelste staafje (de dipool) rechtstreeks gevoed; de andere staven zijn passief en vangen energie op door de straling van dat middelste element, waarna ze zelf weer uitstralen. Doordat de reflector iets langer en de directors iets korter dan resonant zijn, krijgen de stroompjes in die staven net het juiste faseverschil, zodat de heruitgestraalde golven naar voren precies optellen en naar achteren elkaar uitdoven. De reflector achter de dipool kaatst de energie naar voren, en de rij directors ervoor knijpt de bundel verder samen naar voren. Het resultaat is een sterk gerichte, krachtige bundel langs de as, zonder dat die extra staven eigen voeding nodig hebben.' },
  { id: 101, categorie: 'RF, antennes & signalen', vraag: 'Waarom een antenne resonant moet zijn op een kwart of halve golflengte om efficiënt te stralen', uitleg: 'Een antenne straalt pas goed als hij \'resonant\' is: op de juiste maat afgestemd op de golflengte. Dan pendelt er geen energie nutteloos heen en weer, maar gaat alle vermogen daadwerkelijk de lucht in. Een halvegolfdipool past een halve golflengte precies, met de sterkste stroom in het midden en niets aan de uiteinden. Maak je de antenne veel te kort, dan gedraagt hij zich als een kleine condensator die het signaal tegenhoudt, en verdwijnt bijna al het vermogen als warmte in plaats van als straling.' },
  { id: 102, categorie: 'RF, antennes & signalen', vraag: 'Waarom een verkeerd afgesloten coaxkabel het signaal terugkaatst (staande golf/SWR) en de zender kan beschadigen', uitleg: 'Een coaxkabel geeft zijn hele vermogen alleen af als het apparaat aan het eind precies dezelfde \'impedantie\' (elektrische weerstand voor wisselsignalen) heeft als de kabel. Klopt dat niet, dan kaatst een deel van het signaal terug. De heen- en teruggaande golf tellen op tot een \'staande golf\', waarvan de scheefheid je meet als SWR. Op de pieken kan de spanning veel hoger oplopen dan normaal, en het teruggekaatste vermogen komt terug in de zender, waar het de eindtransistoren extra opwarmt en kan slopen.' },
  { id: 103, categorie: 'RF, antennes & signalen', vraag: 'Waarom een phased array zijn bundel elektronisch stuurt via minuscule faseverschillen tussen honderden elementjes', uitleg: 'Een phased array is een veld van vele kleine antennes die allemaal hetzelfde signaal uitzenden. Door elk element net iets eerder of later te laten zenden, versterken de golven elkaar in één gekozen richting en doven ze elkaar ernaast uit; zo ontstaat een smalle bundel. Verander je die minieme tijdverschillen, dan draait de bundel mee, puur elektronisch, zonder dat er iets beweegt. Omdat er geen mechaniek meebeweegt, kan zo\'n radar in microseconden van doel naar doel springen en zelfs meerdere bundels tegelijk maken.' },
  { id: 104, categorie: 'RF, antennes & signalen', vraag: 'Waarom multipath een signaal via omwegen laat aankomen en zo geesten op oude tv\'s en fouten in gps gaf', uitleg: 'Multipath betekent dat hetzelfde signaal je ontvanger niet alleen rechtstreeks bereikt, maar ook via omwegen die tegen gebouwen, bergen of de grond weerkaatsen. Die omweg is langer, dus de gekaatste kopie komt later aan en verstoort het directe signaal. Op oude tv zag je die vertraagde kopie als een tweede, verschoven spookbeeld naast het echte. Bij gps meet de ontvanger door zo\'n omweg een te lange looptijd naar de satelliet, wat de plaatsbepaling meters kan laten missen, vooral tussen hoge gebouwen.' },
  { id: 105, categorie: 'RF, antennes & signalen', vraag: 'Waarom 50 ohm de standaard-impedantie is: een compromis tussen minste verlies en meeste vermogen', uitleg: 'Bij een coaxkabel met lucht erin botsen twee wensen: de laagste signaalverliezen liggen rond 77 ohm, maar het meeste vermogen kun je doorsturen rond 30 ohm. Vijftig ohm ligt daar netjes tussenin, zodat je redelijk weinig verlies én een fatsoenlijk vermogen krijgt. Bij gangbare kabeldiktes valt die 50 ohm bovendien praktisch uit. En omdat de hele industrie dezelfde waarde aanhoudt, passen kabels, stekkers en meters onderling zonder dat er iets terugkaatst.' },
  { id: 106, categorie: 'RF, antennes & signalen', vraag: 'Waarom een Faraday-kooi radiogolven tegenhoudt maar een laagfrequent magnetisch veld nauwelijks', uitleg: 'In een Faraday-kooi schuift een binnenkomend elektrisch veld de vrije elektronen in het metaal net zo lang tot zij een tegenveld opwekken dat het veld binnenin wegpoetst; bij snelle radiogolven werkt dat prima. Een traag of stilstaand magnetisch veld glipt er echter dwars doorheen, want daar is geen elektrische component om af te schermen en de opgewekte tegenstromen zijn te zwak. Voor magnetisme heb je juist een speciaal materiaal nodig, zoals mu-metaal, dat de veldlijnen door zichzelf omleidt. Een gaaskooi is dus een spiegel voor radiogolven, maar bijna doorzichtig voor langzaam magnetisme.' },
  { id: 107, categorie: 'RF, antennes & signalen', vraag: 'Waarom near field en far field van een antenne fysisch heel verschillend gedrag vertonen', uitleg: 'Vlak bij de antenne, in het nabije veld, wiebelt energie elke trilling heen en weer tussen antenne en omgeving zonder echt weg te stralen, en de veldsterkte zakt razendsnel als je verder gaat. Verderop, in het verre veld, heeft de golf zich losgemaakt tot een nette lopende golf waarin het elektrische en magnetische deel loodrecht op elkaar staan in een vaste verhouding. Daar ligt het stralingspatroon vast en neemt de sterkte gewoon af met de afstand. De grens ligt ongeveer op 2 keer de antennemaat in het kwadraat, gedeeld door de golflengte.' },
  { id: 108, categorie: 'RF, antennes & signalen', vraag: 'Waarom intermodulatie twee schone signalen valse frequenties laat maken in een niet-lineaire versterker', uitleg: 'In een ideale versterker blijven twee tonen keurig apart, maar een echte versterker vervormt een beetje, en die vervorming vermenigvuldigt de tonen met elkaar. Zo ontstaan nieuwe som- en verschilfrequenties; berucht zijn de \'derde-orde\' producten, want die vallen vlak naast de originele tonen en zijn dus niet weg te filteren. Deze valse tonen groeien razendsnel: verdubbel je het ingangssignaal, dan worden zij acht keer zo sterk. Daarom drukt men de lineariteit van een ontvanger uit in het \'IP3\'-punt, een denkbeeldig snijpunt dat aangeeft hoe schoon hij blijft.' },
  { id: 109, categorie: 'RF, antennes & signalen', vraag: 'Waarom een satelliet-uplink een andere frequentie gebruikt dan de downlink om zichzelf niet te overstemmen', uitleg: 'Een satelliet vangt een piepzwak signaal uit de ruimte op en zendt tegelijk een fors versterkt signaal terug. Zouden beide op dezelfde frequentie zitten, dan zou zijn eigen krachtige zender rechtstreeks in zijn gevoelige ontvanger lekken en die verdoven. Door heen- en teruggaand signaal op verschillende frequenties te zetten, kan een filter het eigen zendsignaal van het binnenkomende scheiden. Zo blijft de ontvanger het enorme eigen vermogen de baas. De teruglink krijgt meestal de lagere frequentie, want die verzwakt minder in de atmosfeer, precies waar het zwakke signaal dat nodig heeft.' },
  { id: 110, categorie: 'RF, antennes & signalen', vraag: 'Waarom de Doppler-shift van een laagvliegende satelliet de ontvangstfrequentie continu laat verschuiven', uitleg: 'Een satelliet in een lage baan scheert met kilometers per seconde langs je grondstation, en zijn snelheid recht naar je toe of van je af verandert steeds tijdens de overkomst. Terwijl hij nadert, worden de golven samengeperst en klinkt de frequentie hoger; terwijl hij wegdraait, worden ze uitgerekt en zakt de frequentie, net als de veranderende toon van een voorbijrazende sirene. Precies bovenlangs is de snelheid naar je toe even nul en flitst de frequentie snel door haar rustwaarde: de bekende S-vormige Doppler-curve. Ontvangers voor gps of Iridium moeten die verschuiving continu bijstellen om vergrendeld te blijven.' },
  { id: 111, categorie: 'Optiek & fotografie', vraag: 'Waarom sferische aberratie een lens aan de randen onscherp maakt en focus shift geeft bij afstoppen', uitleg: 'Bij een bolvormig geslepen lens breken de stralen die door de rand vallen sterker dan die door het midden, zodat ze niet op één punt samenkomen; dat heet sferische aberratie. Rond scherpe puntjes ontstaat daardoor een wazige gloed en smeert het brandpunt uit. Zet je het diafragma dichter, dan blokkeer je juist die afdwalende randstralen, maar omdat die eerder scherpstelden dan de middelste, verschuift het scherpe vlak een stukje: dat is focus shift. Optici lossen dit op met asferisch (niet perfect bolvormig) geslepen lenzen of slim gecombineerde lensgroepen.' },
  { id: 112, categorie: 'Optiek & fotografie', vraag: 'Waarom chromatische aberratie kleuren splitst omdat glas elke golflengte iets anders breekt', uitleg: 'Glas buigt niet elke kleur even sterk: blauw licht wordt meer afgebogen dan rood, een eigenschap die dispersie heet. Daardoor stelt elke kleur op een net iets andere afstand scherp en lopen de kleuren zijdelings uiteen, wat gekleurde randjes om contrasten geeft. Hoe sterk een glassoort de kleuren splitst, geeft men aan met het Abbe-getal. Door een licht buigend \'kroonglas\' te combineren met een sterk splitsend \'flintglas\' in een dubbele lens, brengen fabrikanten twee kleuren weer op hetzelfde punt samen.' },
  { id: 113, categorie: 'Optiek & fotografie', vraag: 'Waarom een apochromaat drie golflengten samenbrengt met speciale glassoorten (fluoriet)', uitleg: 'Een gewone kleurgecorrigeerde lens (achromaat) brengt maar twee kleuren op één brandpunt samen, waardoor er een rest van meestal groen of paars overblijft: het secundaire spectrum. Een apochromaat pakt drie kleuren tegelijk en drukt die rest sterk weg, maar dat vraagt om glas dat kleuren wel héél weinig en op een ongewone manier splitst. Fluoriet (calciumfluoride) en speciale ED-glazen hebben precies dat afwijkende gedrag, waardoor de kleuren over een breder bereik samenvallen. Het resultaat is een vrijwel kleurzoomvrij, contrastrijk beeld, onmisbaar in telescopen en telelenzen.' },
  { id: 114, categorie: 'Optiek & fotografie', vraag: 'Waarom diffractie bij een té klein diafragma de scherpte juist weer verslechtert (diffraction limit)', uitleg: 'Licht dat door een klein gaatje gaat, buigt om de rand en vormt op de sensor geen puntje maar een klein schijfje met ringen eromheen (het Airy-schijfje). Hoe kleiner het diafragma, hoe groter dat schijfje, tot het meerdere pixels bestrijkt en fijne details vervagen; dat is het diffractielimiet. Bij een wijd open diafragma helpt afstoppen nog, want dan overheersen de lensfouten. Maar voorbij een bepaald punt wint de diffractie en zakt de scherpte weer, hoe goed de lens ook is. Het scherpst zit je dus in het midden, waar de lensfouten al klein zijn maar de diffractie nog niet baas is.' },
  { id: 115, categorie: 'Optiek & fotografie', vraag: 'Waarom focus breathing — beeldhoek die verandert bij scherpstellen — bij cinelenzen taboe is', uitleg: 'Bij veel lenzen bewegen tijdens het scherpstellen inwendige lensgroepen, waardoor de beeldhoek een tikje verandert en het beeld lijkt in of uit te zoomen: focus breathing. Voor foto\'s maakt dat niets uit, maar in film zie je bij een scherptewissel van voor- naar achtergrond het kader \'mee ademen\', wat de illusie breekt en het monteren bemoeilijkt. Cinelenzen worden daarom zo gebouwd dat de beeldhoek over het hele scherpstelbereik gelijk blijft. Dat lukt met interne scherpstelling waarbij extra lensgroepen de vergroting constant houden.' },
  { id: 116, categorie: 'Optiek & fotografie', vraag: 'Waarom een apodisatiefilter de onscherpe randen zacht laat uitvloeien maar een stop licht kost', uitleg: 'Een apodisatiefilter is een grijsverloop in de lens: helder in het midden en geleidelijk donkerder naar de rand. Juist de randstralen vormen de harde omtrek van een onscherpe lichtvlek, en door die te verzwakken krijgt elk wazig lichtbolletje een zachte, uitvloeiende rand in plaats van een scherpe schijf. Zo wordt de overgang tussen scherp en onscherp romig. De prijs is licht: omdat de rand van de opening wordt gedimd, komt er ongeveer een stop minder licht door. Daardoor is het praktische T-getal van de lens hoger dan het theoretische f-getal.' },
  { id: 117, categorie: 'Optiek & fotografie', vraag: 'Waarom een sensor microlenzen boven elke pixel heeft om licht te vangen dat anders tussen de pixels verdwijnt', uitleg: 'Op een sensor is maar een deel van elke pixel echt lichtgevoelig; de rest gaat op aan bedrading en schakelingen, zeker bij oudere ontwerpen. Licht dat op die dode zones valt, zou verloren gaan. Een minuscuul lensje boven elke pixel bundelt daarom het licht van de hele pixel naar het kleine gevoelige plekje eronder, wat de opbrengst en dus de gevoeligheid flink verhoogt. Valt het licht schuin in, aan de rand van het beeld, dan schuift men die lensjes een beetje naar het midden toe om donkere hoeken te beperken.' },
  { id: 118, categorie: 'Optiek & fotografie', vraag: 'Waarom rolling shutter rechte objecten scheeftrekt omdat de sensor regel voor regel wordt uitgelezen', uitleg: 'Een CMOS-sensor met \'rolling shutter\' leest niet alle pixels tegelijk uit, maar scant regel voor regel van boven naar beneden. Elke beeldlijn wordt dus op een iets later moment vastgelegd, en beweegt het onderwerp of de camera in die milliseconden, dan staat de onderkant net ergens anders dan de bovenkant. Daardoor kantelen rechte lijnen scheef, buigen propellers krom en golft snel bewegend beeld (het jelly-effect). Een \'global shutter\' legt alle pixels op precies hetzelfde moment vast en voorkomt dit, maar is duurder en ingewikkelder.' },
  { id: 119, categorie: 'Optiek & fotografie', vraag: 'Waarom moiré ontstaat als een fijn patroon botst met het pixelraster, en waarom sommige camera\'s een AA-filter hebben', uitleg: 'Moiré is een bemonsteringsfout: is een patroon fijner dan het pixelraster kan navertellen, dan \'vouwt\' het terug als een valse, veel grovere golf met kleurzweem. Vooral het kleurenmozaïek op de sensor maakt dat zichtbaar als regenboogkleuren op strak geweven stof. Een optisch anti-aliasingfilter splitst elk detailpuntje een piepklein beetje uit, zodat de te fijne details worden weggehaald vóór de sensor ze vastlegt. De prijs is een tikje minder scherpte, en daarom laten sommige camera\'s met heel veel pixels dat filter juist weg en vertrouwen ze op hun hoge pixeldichtheid.' },
  { id: 120, categorie: 'Optiek & fotografie', vraag: 'Waarom een polarisatiefilter reflecties van glas en water wegneemt maar op blank metaal niet werkt', uitleg: 'Licht dat schuin weerkaatst van glas of water raakt sterk \'gepolariseerd\': het trilt vooral in één vlak, het sterkst rond de zogeheten Brewsterhoek. Draai je een polarisatiefilter dwars op dat vlak, dan blokkeert het precies dat reflectielicht en verdwijnt de schittering. Metaal is echter een geleider en houdt bij weerkaatsing de trillingsrichting grotendeels in stand, zodat de reflectie niet netjes in één vlak trilt. Daarom kun je een spiegeling op chroom of blank metaal niet met zo\'n filter wegdraaien.' },
  { id: 121, categorie: 'Optiek & fotografie', vraag: 'Waarom vignettering aan de hoeken komt door de cosinus-vierde-machtswet van de lichtinval', uitleg: 'Naar de hoeken van het beeld valt het licht onder een steeds schuinere hoek, en verschillende meetkundige effecten samen laten de helderheid dan afnemen met de vierde macht van de cosinus van die hoek. Die \'cosinus-vierde\' komt uit drie effecten die elk een cosinus geven, plus de iets grotere afstand naar de hoek. Het gevolg is dat de hoeken altijd wat donkerder zijn dan het midden, los van enige mechanische afscherming. Groothoeklenzen hebben er het meest last van, omdat daar de hoeken het schuinst zijn; ontwerpers corrigeren met een aangepaste bouw of een lichte helderheidscorrectie.' },
  { id: 122, categorie: 'Optiek & fotografie', vraag: 'Waarom een teleconverter wel de brandpuntsafstand vergroot maar evenredig licht en scherpte inlevert', uitleg: 'Een teleconverter is een extra lensje achter je objectief dat het beeld verder uitvergroot, waardoor de effectieve brandpuntsafstand met de vergrotingsfactor toeneemt. Maar de lichtopening groeit niet mee, dus wordt het beeld donkerder: een 2x-converter kost twee stops licht. Bovendien vergroot hij niet alleen het beeld, maar ook alle foutjes en de onscherpte van de hoofdlens, zodat het geheel minder scherp oogt. Je krijgt dus meer bereik zonder zware telelens, maar levert lichtsterkte en detail in.' },
  { id: 123, categorie: 'Audio-engineering', vraag: 'Waarom vinyl bij opname én weergave een RIAA-curve nodig heeft: lage tonen verzwakt, hoge versterkt, om de groef leefbaar te houden', uitleg: 'Bij het snijden van een plaat zou een zware bas de groef zo breed laten uitslaan dat de naald en de buurgroeven in gevaar komen, terwijl fijne hoge tonen in de ruis zouden verdrinken. Daarom verzwakt men bij het opnemen de bas en versterkt men de hoge tonen (de RIAA-curve), zodat de groef beheersbaar blijft en de ruis minder opvalt. Bij het afspelen doet de phono-voorversterker precies het omgekeerde en herstelt zo de oorspronkelijke balans. Vaste tijdwaarden van 3180, 318 en 75 microseconden leggen die curve wereldwijd exact vast.' },
  { id: 124, categorie: 'Audio-engineering', vraag: 'Waarom een basreflexpoort een Helmholtz-resonator is die op één frequentie bas versterkt maar eronder de conus onbeschermd laat', uitleg: 'De luchtprop in de reflexbuis en de lucht in de kast vormen samen een trillend systeem (een Helmholtz-resonator) met één afstemfrequentie waarop die luchtprop krachtig meebeweegt. Rond die frequentie versterkt de buis de bas mooi mee, terwijl de conus zelf juist rustig kan blijven. Maar onder die afstemfrequentie draait de buis om en werkt hij tegen: de kast \'lekt\' akoestisch en de conus verliest de luchtveer die hem afremde, zodat hij ongecontroleerd ver uitslaat. Daarom is een subsonisch filter belangrijk, dat de allerlaagste tonen wegneemt en overbelasting voorkomt.' },
  { id: 125, categorie: 'Audio-engineering', vraag: 'Waarom een luidspreker wordt beschreven met Thiele-Small-parameters die het gedrag in een kast voorspellen', uitleg: 'Thiele-Small-parameters vatten het gedrag van een luidsprekerchassis samen in een paar getallen, zoals de eigen resonantiefrequentie, een dempingswaarde en een \'equivalent luchtvolume\'. Die getallen vertalen de veerkracht, het gewicht en de demping van de bewegende conus naar rekenbare waarden, zodat je het lagetonengedrag kunt voorspellen als een gedempte trilling. Daarmee berekent een ontwerper vooraf het benodigde kastvolume en de te verwachten bascurve, nog voordat er iets gebouwd is. Vooral het luchtvolume en de dempingswaarde bepalen de keuze tussen een dichte of een reflexkast.' },
  { id: 126, categorie: 'Audio-engineering', vraag: 'Waarom je expres dither-ruis toevoegt aan digitale audio om kwantisatievervorming te ruilen voor onhoorbare ruis', uitleg: 'Bij het digitaliseren wordt elk meetpunt afgerond naar de dichtstbijzijnde stap. Bij zachte signalen is die afrondfout niet willekeurig maar loopt hij mee met het signaal, en dat hoor je als lelijke vervorming. Voeg je vóór het afronden een beetje ruis toe, ongeveer één stapje groot (dither), dan wordt dat verband verbroken en verandert de vervorming in een egale, onafhankelijke ruisvloer. Zo blijft zelfs een heel zacht signaal gemiddeld nog kloppen en verdwijnt de vieze vervorming. Met \'noise shaping\' duw je die ruis bovendien naar tonen waar het oor toch weinig van merkt.' },
  { id: 127, categorie: 'Audio-engineering', vraag: 'Waarom een crossover groepsvertraging introduceert en de tweeter soms in tegenfase wordt aangesloten', uitleg: 'Een passieve crossover verdeelt het geluid met spoelen en condensatoren over woofer en tweeter, maar die onderdelen verschuiven ook de fase, en per frequentie anders. Dat uit zich als groepsvertraging: sommige tonen komen een fractie later. Bij een gangbaar filter lopen woofer en tweeter rond het overgangsgebied ongeveer een halve golf uit de pas, zodat ze elkaar daar zouden uitdoven. Door de tweeter met omgekeerde plus en min aan te sluiten, corrigeer je die halve golf en tellen de tonen weer netjes op. Welke polariteit klopt, hangt dus af van het filtertype en hoe de conussen staan.' },
  { id: 128, categorie: 'Audio-engineering', vraag: 'Waarom phantom power (48V) via dezelfde twee aders een condensatormicrofoon voedt zónder het signaal te storen', uitleg: 'Phantom power zet 48 volt gelijkspanning via twee gelijke weerstanden op allebei de signaaldraden van een gebalanceerde microfoonkabel, zodat beide draden precies dezelfde gelijkspanning voeren. Het geluid zit in het verschil tussen die twee draden, en omdat de gelijkspanning op beide even groot is, valt hij in dat verschil weg en stoort dus niets. De microfoon tapt zijn voeding af uit die gemeenschappelijke spanning, terwijl koppelcondensatoren de gelijkspanning bij de mengtafel tegenhouden. Zo reizen voeding en geluid samen over dezelfde twee draden zonder elkaar te hinderen.' },
  { id: 129, categorie: 'Audio-engineering', vraag: 'Waarom comb filtering ontstaat als hetzelfde geluid met vertraging bij je oor komt en frequenties uitdooft', uitleg: 'Bereikt een geluid je oor zowel rechtstreeks als via een korte omweg, bijvoorbeeld een weerkaatsing of een tweede microfoon, dan komen twee kopieën met een klein tijdverschil samen. Bij tonen waar dat verschil precies een halve golf is, botsen ze tegengesteld en doven ze uit; bij een hele golf versterken ze juist. Dat herhaalt zich op vaste frequentie-afstanden, zodat de klank een rij pieken en diepe dalen krijgt die op de tanden van een kam lijkt: comb filtering. Hoe langer de vertraging, hoe dichter die inkepingen bij elkaar liggen.' },
  { id: 130, categorie: 'Audio-engineering', vraag: 'Waarom een class-D versterker de luidspreker met razendsnelle aan/uit-pulsen stuurt en toch koel blijft', uitleg: 'Een class-D versterker stuurt de luidspreker met razendsnelle aan/uit-pulsen: de transistoren staan altijd volledig open of volledig dicht, en de gemiddelde pulsbreedte volgt het geluid. Een schakelaar die helemaal open staat heeft nauwelijks spanning over zich, en dicht laat hij geen stroom door, dus verstookt hij in beide standen bijna geen vermogen; het rendement haalt zo\'n 90 procent. Een gewone lineaire versterker staat juist voortdurend \'half open\' en verbrandt daarbij veel energie als warmte. Een filter aan de uitgang middelt de pulsen weer tot een gladde geluidsgolf voor de luidspreker.' },
  { id: 131, categorie: 'Audio-engineering', vraag: 'Waarom loudness war-compressie muziek luider laat klinken maar dynamiek onherstelbaar wegknijpt', uitleg: 'In de loudness war knijpen studio\'s met zware compressie het geluid samen om het gemiddelde niveau op te pompen, terwijl de digitale piek vastligt op het maximum. Door de zachte stukken op te trekken en de pieken af te toppen, wordt het verschil tussen piek en gemiddelde kleiner, waardoor het nummer bij gelijke piek luider en voller klinkt. Maar dat aftoppen wist de natuurlijke dynamiek en de scherpe aanzetten van klanken definitief uit de opname; die informatie is weg en komt niet terug. Moderne afspeelnormen (LUFS) trekken dat luidheidsvoordeel er inmiddels weer af, zodat het samenknijpen zinloos is geworden.' },
  { id: 132, categorie: 'Audio-engineering', vraag: 'Waarom de Fletcher-Munson-curves verklaren waarom bas verdwijnt zodra je zachter zet', uitleg: 'De Fletcher-Munson-curven laten zien dat je oor niet voor alle tonen even gevoelig is, en dat die gevoeligheid bovendien met het volume verandert. Het oor is het scherpst rond een paar kilohertz en veel minder gevoelig voor heel lage en heel hoge tonen, en dat verschil is bij zacht afspelen extra groot. Zet je de muziek zachter, dan zakken de laagste tonen dus sneller onder je hoorgrens dan het midden, waardoor de bas onevenredig lijkt te verdwijnen. Een loudness-knop compenseert dat door bij laag volume juist de bas en de hoge tonen wat op te tillen.' },
  { id: 133, categorie: 'Audio-engineering', vraag: 'Waarom jitter — timingfouten in de klok van een DAC — hoorbare vervorming toevoegt', uitleg: 'Een digitaal-naar-analoog-omzetter zet meetpunten om op de tikken van een klok, en die tikken horen precies gelijkmatig te vallen. Jitter is de kleine wiebel in die tikken: een punt komt dan iets te vroeg of te laat, wat neerkomt op een foutje in de sterkte, groter naarmate het signaal sneller verandert. Omdat die tijdfout meeloopt met de toonhoogte, ontstaan er extra zijtonen rond de klanken, hoorbaar als vervorming of een ruwe, korrelige klank. Het effect is het ergst bij hoge, harde tonen, en men bestrijdt het met een zeer stabiele klok en een tussenbuffer die de timing opnieuw netjes zet.' },
  { id: 134, categorie: 'Audio-engineering', vraag: 'Waarom een ribbon-microfoon tweezijdig (figure-8) opneemt door zijn open opgehangen folie', uitleg: 'In een ribbon-microfoon hangt een dun, geplooid strookje aluminium vrij tussen twee magneetpolen, met beide kanten open naar de lucht. Het reageert niet op de luchtdruk zelf, maar op het drukverschil tussen voor- en achterkant, en beweegt dus mee met de luchtstroom. Geluid van voren en van achteren duwt het strookje even hard maar tegengesteld, terwijl geluid recht van opzij op beide kanten gelijk drukt en zichzelf opheft. Zo ontstaat vanzelf het achtvormige opnamepatroon dat voor en achter opneemt maar de zijkanten volledig negeert.' },
  { id: 135, categorie: 'Metallurgie & materialen', vraag: 'Waarom staal harder wordt door quenchen: snel afkoelen vangt koolstof in een gespannen martensiet-rooster', uitleg: 'Heet staal bestaat als \'austeniet\', een kristalvorm die veel koolstof opgelost kan houden. Koel je langzaam af, dan krijgt die koolstof de tijd om weg te kruipen en vormt zich zacht staal. Dompel je het gloeiende staal juist bliksemsnel af (quenchen), dan krijgt de koolstof die kans niet en klapt het kristalrooster in één keer om naar \'martensiet\': een sterk vervormd rooster met de koolstof erin gevangen. Die opgesloten koolstof zet het rooster enorm onder spanning, wat het verschuiven van de metaallagen blokkeert. Daardoor wordt het staal keihard, maar ook bros.' },
  { id: 136, categorie: 'Metallurgie & materialen', vraag: 'Waarom je daarna moet ontlaten (temperen), anders is het glashard en breekt het bros', uitleg: 'Vers gehard staal (martensiet) zit boordevol inwendige spanning en gevangen koolstof, waardoor het extreem hard maar zo bros is dat het bij een klap kan versplinteren. Bij ontlaten verwarm je het opnieuw, maar minder heet, zodat een deel van de koolstof uit het rooster kan schuiven en als fijne korreltjes neerslaat, terwijl de spanning ontspant. Je levert daarmee wat hardheid in, maar wint flink aan taaiheid en schokbestendigheid. Met de ontlaattemperatuur stelt de metaalbewerker de balans tussen hard en taai precies af op wat het onderdeel moet kunnen.' },
  { id: 137, categorie: 'Metallurgie & materialen', vraag: 'Waarom waterstofbrosheid een hoogvaste bout maanden na montage spontaan laat knappen', uitleg: 'Waterstofatomen die bij verzinken, beitsen of roesten in het staal belanden, zijn zo klein dat ze door het metaal kruipen en zich verzamelen op de zwaarst belaste plek, zoals de kern van de schroefdraad. Daar verzwakken ze de binding tussen de metaalkorrels, zodat er minder kracht nodig is om een scheurtje te laten groeien. Onder blijvende trekspanning schuift de waterstof langzaam mee naar de scheurpunt en groeit de scheur van binnenuit, tot de bout weken of maanden later ineens en zonder waarschuwing knapt. Juist heel sterk staal is gevoelig, omdat het weinig \'rek\' over heeft. Kort na het verzinken uitbakken drijft de waterstof er weer uit.' },
  { id: 138, categorie: 'Metallurgie & materialen', vraag: 'Waarom spanningscorrosie roestvast staal in chloorrijke zwembadlucht onzichtbaar laat scheuren — dodelijke plafondinstortingen', uitleg: 'Spanningscorrosie treedt op als drie dingen samenkomen: trekspanning, een gevoelig materiaal en een agressief milieu, en roestvast staal is juist berucht gevoelig voor chloride. In de warme, chloriderijke lucht boven een zwembad tasten chloride-deeltjes de beschermende oxidehuid plaatselijk aan, waarna onder spanning fijne, vertakte haarscheurtjes door het metaal groeien. Aan de buitenkant blijft dat vrijwel onzichtbaar, terwijl het dragende deel van binnen wegvalt, tot een ophangstaaf plotseling breekt. Zo stortte in Zwitserland een zwembadplafond in dat aan roestvaste staven hing; sindsdien raadt men in zulke ruimtes andere legeringen aan.' },
  { id: 139, categorie: 'Metallurgie & materialen', vraag: 'Waarom creep metaal onder constante belasting bij hoge temperatuur langzaam laat uitrekken tot bezwijken', uitleg: 'Creep is het traag, blijvend uitrekken van metaal dat lang onder een vaste belasting staat bij hoge temperatuur, ruwweg boven veertig procent van het smeltpunt (in graden Kelvin gerekend). Bij die hitte worden atomen zo beweeglijk dat ze langs elkaar kunnen schuiven en de korrels langzaam verschuiven, waardoor het materiaal uitrekt terwijl de spanning ver onder de breukgrens blijft. Het verloopt in drie fasen: eerst afnemend snel, dan een lange fase met vrijwel gelijke snelheid, en ten slotte een versnelling waarin holtes samenvloeien tot breuk. Turbinebladen en stoomleidingen worden daarom bewust op een beperkte levensduur ontworpen.' },
  { id: 140, categorie: 'Metallurgie & materialen', vraag: 'Waarom turbinebladen als één enkel kristal worden gegoten, zodat er geen korrelgrenzen zijn om langs te kruipen', uitleg: 'Een gewoon gietstuk bestaat uit veel kleine kristallen (korrels) met grenzen ertussen, en juist die grenzen zijn bij hoge temperatuur de zwakke plek waarlangs het metaal traag uitrekt. Door een turbineblad heel gericht te laten stollen vanuit één enkel beginkristal, via een spiraalvormige \'sluis\' die maar één korrel doorlaat, groeit het hele blad uit tot één ongebroken kristal zonder enige korrelgrens. Daarmee verdwijnt de belangrijkste zwakke route en kan het blad heter en langer mee. Bovendien richt men het kristal zo dat de sterkste richting langs de zwaarste belasting ligt, wat het nog taaier maakt.' },
  { id: 141, categorie: 'Metallurgie & materialen', vraag: 'Waarom tinpest tin bij kou tot grijs poeder laat verkruimelen en orgelpijpen en tinnen knopen sloopte', uitleg: 'Tin kan in twee kristalvormen bestaan: het glanzende metalen wit-tin dat normaal stabiel is, en het brosse grijs-tin dat onder ongeveer dertien graden de stabiele vorm wordt. Zakt de temperatuur daaronder, dan begint de omzetting naar grijs-tin, en omdat dat veel meer ruimte inneemt met een heel ander rooster, verkruimelt het metaal tot grijs poeder. De omzetting gaat traag, maar versnelt zichzelf: eenmaal ontstaan grijs-tin steekt naburig tin aan, zodat de \'pest\' zich als een besmetting verspreidt. In koude winters verwoestte dit orgelpijpen, tinnen knopen en museumstukken.' },
  { id: 142, categorie: 'Metallurgie & materialen', vraag: 'Waarom sigma-fase roestvast staal bij bepaalde temperaturen bros maakt na lang verhitten', uitleg: 'Sigma-fase is een harde, brosse verbinding rijk aan chroom en ijzer die in roestvast staal ontstaat als het lang op een temperatuur tussen ongeveer 600 en 900 graden blijft. Ze vormt zich vooral op de korrelgrenzen en trekt daarbij chroom weg uit de omgeving, wat het staal niet alleen bros maakt maar plaatselijk ook minder roestbestendig. Omdat sigma nauwelijks taai is, keldert de schokbestendigheid, vooral bij kamertemperatuur na afkoelen. Duplex- en hooggelegeerde roestvaste soorten zijn extra gevoelig, wat hun toegestane werktemperatuur en de warmte bij het lassen beperkt.' },
  { id: 143, categorie: 'Metallurgie & materialen', vraag: 'Waarom koudlassen in vacuüm twee schone metaaloppervlakken spontaan laat samensmelten (een probleem in de ruimte)', uitleg: 'Metaalatomen aan een oppervlak zoeken graag bindingspartners, maar op aarde is elk metaal bedekt met een dun oxidelaagje en aangehechte gassen die kaal contact verhinderen. In het harde vacuüm van de ruimte kan die beschermlaag ontbreken of afslijten, en dan komen twee schone, gelijke metaaloppervlakken die tegen elkaar drukken met hun atomen binnen bindingsafstand. De atomen kunnen niet zien welk stuk van welk oppervlak kwam en vormen gewoon metaalbindingen, zodat de delen zonder warmte of druk aan elkaar vastvriezen: koudlassen. Bewegende delen in satellieten kunnen zo blokkeren, wat men voorkomt met verschillende metalen, coatings of smeermiddelen.' },
  { id: 144, categorie: 'Metallurgie & materialen', vraag: 'Waarom vermoeiing metaal laat breken ver onder de bezwijksterkte, puur door herhaalde belasting (de Comet-rampen)', uitleg: 'Bij steeds wisselende belasting stapelt plaatselijke vervorming zich op bij zwakke punten zoals hoeken, gaten of krassen, ook al blijft de spanning ruim onder de grens waarbij het metaal normaal bezwijkt. Daar ontstaat een microscheurtje dat bij elke belasting een piepklein stukje verder groeit en op de breuk fijne groeiribbels achterlaat. Zodra het overgebleven deel te dun wordt, breekt het onderdeel ineens af. Bij de De Havilland Comet begonnen zulke scheuren bij de hoeken van de bijna vierkante ramen, onder de druk die elke vlucht opnieuw op de romp kwam; dat leidde tot rampen en tot de latere afgeronde vliegtuigramen.' },
  { id: 145, categorie: 'Metallurgie & materialen', vraag: 'Waarom galvanische corrosie het onedele metaal versneld wegvreet als twee metalen elkaar nat raken', uitleg: 'Raken twee verschillende metalen elkaar aan terwijl ze samen nat zijn, bijvoorbeeld in zilte lucht, dan ontstaat er een klein batterijtje met een spanningsverschil tussen beide. Het onedelere metaal wordt de minpool: het staat elektronen af en lost daardoor versneld op, terwijl het edelere metaal juist beschermd blijft. Is het onedele stukje klein en het edele groot, dan gaat dat aanvreten nog sneller. Men keert dit bewust om met \'opofferingsanodes\' van zink of magnesium, die zichzelf laten wegvreten om staal of scheepsrompen te sparen.' },
  { id: 146, categorie: 'Metallurgie & materialen', vraag: 'Waarom aluminium meteen een taai oxidehuidje vormt dat beschermt — behalve tegen chloride, dat het doorprikt (putcorrosie)', uitleg: 'Aluminium is chemisch juist heel reactief en verbindt zich meteen met zuurstof, maar de oxidelaag die zo ontstaat is dicht, hecht sterk en is maar enkele nanometers dun; ze sluit het metaal af en herstelt zichzelf bij een krasje. Dat maakt aluminium in de praktijk goed bestand tegen corrosie. Chloride-deeltjes zijn echter klein en agressief en kunnen die laag op één plek doorprikken, waarna daar het kale metaal versneld oplost. In het putje dat zo ontstaat verzuurt het milieu en houdt het chloride de aanval lokaal gaande, zodat een diep, smal gat groeit terwijl de rest gaaf lijkt. Daarom is putcorrosie in zeewater en strooizout de zwakke plek van aluminium.' },
  { id: 147, categorie: 'Metallurgie & materialen', vraag: 'Waarom work hardening een paperclip breekt als je hem een paar keer heen en weer buigt', uitleg: 'Metaal buigt doordat hele lagen atomen langs elkaar schuiven via kleine roosterfoutjes (dislocaties), en bij elke buiging komen er nieuwe bij. Die foutjes raken in elkaar verstrikt en blokkeren elkaar, waardoor verder buigen steeds moeilijker gaat: het metaal wordt lokaal harder maar ook brosser, dat heet werkverharding. In de buigzone hoopt de schade zich buiging na buiging op, tot het materiaal geen rek meer over heeft en er microscheurtjes ontstaan die snel doorbreken. Die combinatie van verharding en opgebouwde schade laat de paperclip na een paar keer heen en weer buigen afknappen.' },
  { id: 148, categorie: 'Metallurgie & materialen', vraag: 'Waarom uitgloeien (annealing) een vervormd metaal weer zacht en buigbaar maakt door de korrels te herstellen', uitleg: 'Koud vervormd metaal zit vol opgehoopte roosterfoutjes en spanning, wat het hard en bros heeft gemaakt. Verhit je het boven een bepaalde temperatuur, dan krijgen de atomen genoeg beweeglijkheid voor drie stappen: eerst ontspant de spanning, dan kiemen er volledig nieuwe, spanningsvrije korrels die de oude vervormde structuur opeten (herkristallisatie), en daarna groeien die korrels wat aan. Het resultaat is weer zacht, taai en goed buigbaar metaal. Zo kan een fabrikant het materiaal tussen bewerkingen door telkens opnieuw kneedbaar maken.' },
  { id: 149, categorie: 'Metallurgie & materialen', vraag: 'Waarom Damascus- en wootzstaal hun patroon danken aan carbide-banden op nanoschaal', uitleg: 'Oud wootzstaal heeft veel koolstof, en bij traag stollen en smeden vormen zich daarin evenwijdige banden van ijzer-carbide, een keihard bestanddeel. Onderzoek liet zien dat in die banden zelfs flinterdunne carbide-draadjes en koolstof-buisjes op nanoschaal kunnen zitten, ontstaan door sporen van bepaalde elementen die als katalysator werkten. Ets je het geslepen oppervlak, dan reageren de carbiderijke en carbidearme banden verschillend, waardoor het bekende waterachtige golfpatroon zichtbaar wordt. De afwisseling van harde carbidebanden en taaier staal gaf deze klingen tegelijk hardheid en taaiheid; modern Damascus bootst dat na door verschillende staalsoorten op elkaar te stapelen.' },
  { id: 150, categorie: 'Metallurgie & materialen', vraag: 'Waarom shot peening een oppervlak met kogeltjes bombardeert om er drukspanning in te persen tegen vermoeiing', uitleg: 'Bij shot peening beschieten talloze kleine kogeltjes het oppervlak, en elke inslag rekt de buitenste laag een beetje blijvend uit. Het diepere materiaal rekt niet mee en wil die opgerekte huid terugtrekken, zodat er aan het oppervlak een blijvende drukspanning achterblijft, in evenwicht met een lichte trekspanning dieper weg. Vermoeiingsscheuren ontstaan en groeien juist onder trekspanning aan het oppervlak, en die moet die ingebrachte drukspanning eerst overwinnen voordat een scheur kan opengaan. Daardoor begint een scheur later en groeit hij trager, wat veren, tandwielen en assen veel langer laat meegaan.' },
  { id: 151, categorie: 'Bouwkunde & constructie', vraag: 'Waarom de Tacoma Narrows-brug niet bezweek door resonantie maar door zelfaangedreven aero-elastische flutter', uitleg: 'Het verhaal dat de wind precies de eigen trillingsfrequentie van de brug raakte klopt niet. Wat er echt gebeurde heet flutter: het slanke, platte brugdek begon te draaien, en die draaiing veranderde de hoek waaronder de wind het dek raakte. Daardoor gingen de luchtkrachten met de beweging mee in plaats van die af te remmen, en pompten ze telkens extra energie in de trilling. Zo voedt de brug zijn eigen beweging: boven een bepaalde windsnelheid slingert de draaitrilling steeds verder op, ongeacht hoe hard het exact waait. Wervels achter het dek startten eerst de op-en-neer-beweging, maar de dodelijke draaibeweging kwam door die koppeling tussen dek en wind.' },
  { id: 152, categorie: 'Bouwkunde & constructie', vraag: 'Waarom voorgespannen beton met strak getrokken kabels de zwakke treksterkte van beton omzeilt', uitleg: 'Beton kan enorme druk hebben maar breekt al bij lichte trek, dus in een gewone balk scheurt het zodra het onderaan wordt opgerekt. Bij voorgespannen beton trekt men stalen kabels strak aan en laat die het beton als een klem samendrukken. De hele doorsnede staat zo permanent onder druk. Als de belasting het beton dan zou willen oprekken, moet die eerst die ingebouwde druk overwinnen voordat er echt trek ontstaat, zodat het beton onder gebruik gedrukt blijft en niet scheurt. Zo benut men de sterke kant van beton en vermijdt men de zwakke, wat slankere en langere overspanningen mogelijk maakt.' },
  { id: 153, categorie: 'Bouwkunde & constructie', vraag: 'Waarom één gebroken "post-tension"-kabel een hele vloer kan laten instorten door kettingreactie', uitleg: 'In een post-tensioned vloer zitten stalen kabels die na het gieten strak zijn aangespannen en aan de vloerranden verankerd; elke kabel draagt een flink deel van de last. Breekt er één door roest of een ankerfout, dan valt zijn bijdrage plotseling weg en moeten de buurkabels die last erbij nemen, waardoor hun spanning oploopt. Omdat de kabels als een strak gekoppeld systeem werken, kan de overbelasting van kabel naar kabel doorlopen als een ritssluiting die opengaat. Bovendien komt bij het breken opeens veel opgeslagen spanning vrij, zoals een geknapt elastiek terugschiet, wat de schade ter plekke nog vergroot.' },
  { id: 154, categorie: 'Bouwkunde & constructie', vraag: 'Waarom "punching shear" een vlakke betonvloer rond een kolom kan laten doorponsen (ramp warenhuis Sampoong)', uitleg: 'Bij een vlakke betonvloer rust de vloer op een kolom via een klein contactvlak, waar de dwarskracht dus enorm geconcentreerd is. Rond de kolomkop kan de vloer daardoor plotseling doorbreken langs een kegelvormig scheurvlak, ongeveer onder 45 graden, zodra de schuifspanning te hoog wordt. Dit doorponsen gebeurt bros en zonder waarschuwing, en zonder extra wapening of een verbrede kolomkop is er geen reserve. Bij het Sampoong-warenhuis maakten het verplaatsen van zware koelmachines en het versmallen van kolommen de spanning te groot; één kolomkop ponste door en de vloeren stortten er als dominostenen achteraan.' },
  { id: 155, categorie: 'Bouwkunde & constructie', vraag: 'Waarom de toren van Pisa gestabiliseerd is door aan de hóge zijde bodem weg te zuigen', uitleg: 'De toren van Pisa helde over doordat de zachte klei- en zandbodem aan de zuidkant meer inzakte dan aan de noordkant, oftewel ongelijke verzakking. Om de toren terug te kantelen boorde men schuin onder de hoge noordzijde en zoog daar heel voorzichtig kleine beetjes grond weg, zodat juist die kant iets zakte. Men koos bewust de hoge kant, omdat verzwaren aan de lage kant de fundering nog verder had kunnen belasten of destabiliseren. De ingreep werd millimeter voor millimeter gemeten en bracht de helling een halve graad terug, tot een stabiel evenwicht.' },
  { id: 156, categorie: 'Bouwkunde & constructie', vraag: 'Waarom een wolkenkrabber een "tuned mass damper" — een enorme slinger — in de top heeft tegen windbeweging', uitleg: 'Een hoge, slanke toren trilt van nature langzaam en dempt weinig, waardoor wind en luchtwervels hem zo kunnen laten wiegen dat bewoners het onaangenaam voelen. Een tuned mass damper is een grote massa, opgehangen als slinger of op veren, die precies zo is afgesteld dat hij net tegen de beweging van het gebouw in schommelt. Doordat de massa achterloopt op het gebouw, duwt zijn traagheid de andere kant op en halen de dempers energie uit de trilling, zoals een uitgebalanceerde tegenhanger die je heen-en-weer beweging afremt. Zo dalen de uitslag en de versnellingen flink, zonder dat de constructie zelf zwaarder of stijver hoeft.' },
  { id: 157, categorie: 'Bouwkunde & constructie', vraag: 'Waarom differentiële zetting — ongelijk verzakken — gevaarlijker is dan gelijkmatig verzakken', uitleg: 'Als een heel gebouw gelijkmatig zakt, blijft de vorm intact en ontstaan er nauwelijks extra spanningen; hooguit leiding- of stoepaansluitingen geven last. Bij ongelijke verzakking zakt het ene steunpunt meer dan het andere, waardoor de constructie wordt gedwongen scheef te trekken en te vervormen. Die opgelegde verdraaiing wekt extra buig- en schuifkrachten op in balken, kolommen en vooral in stijve, brosse delen zoals metselwerk en beton, die daar niet tegen kunnen. Het gevolg zijn scheuren, klemmende constructies en soms lokaal bezwijken, terwijl gelijkmatig zakken relatief onschuldig blijft.' },
  { id: 158, categorie: 'Bouwkunde & constructie', vraag: 'Waarom een boog alleen drukkrachten kent en daarom zonder mortel eeuwen blijft staan', uitleg: 'Een goed gevormde boog leidt de last via een gebogen lijn naar de steunpunten, zodat elk voegvlak op druk staat en de stenen tegen elkaar geklemd blijven. Steen en metselwerk zijn juist heel sterk op druk maar bijna machteloos op trek, en zolang die drukkende lijn binnen de dikte van de boog blijft, ontstaat er nergens trek die de voegen open zou trekken. De wrijving en klemming tussen de wigvormige stenen houden alles op zijn plaats, waardoor mortel eerder vulling is dan lijm. Daardoor blijven droog gestapelde bogen eeuwen staan, zolang de steunpunten de zijwaartse spatkracht opvangen.' },
  { id: 159, categorie: 'Bouwkunde & constructie', vraag: 'Waarom koudebruggen in een muur van binnenuit condens en schimmel veroorzaken', uitleg: 'Een koudebrug is een plek in de muur waar warmte veel makkelijker naar buiten lekt, bijvoorbeeld door een doorlopende betonbalk of een gat in de isolatie. Daardoor is het binnenoppervlak daar duidelijk kouder dan de rest van de wand. Warme binnenlucht bevat waterdamp, en als die lucht dat koude plekje raakt en onder het dauwpunt afkoelt, slaat de damp neer als vocht, net als beslag op een koud raam. Dat oppervlak blijft permanent te vochtig, vaak al boven ongeveer 80 procent luchtvochtigheid vlak bij de wand, en dat is de ideale voedingsbodem voor schimmel, ook zonder zichtbare druppels.' },
  { id: 160, categorie: 'Bouwkunde & constructie', vraag: 'Waarom wapeningsstaal exact evenveel uitzet als beton, waardoor ze niet losscheuren bij temperatuurwisseling', uitleg: 'Staal en beton zetten toevallig bijna precies even veel uit bij opwarming, in de orde van tien tot twaalf micrometer per meter per graad. Daardoor rekken en krimpen de wapeningsstaven en het omhullende beton bij temperatuurwisselingen samen op, zonder dat het een langs het ander schuift en zonder grote spanning aan hun grensvlak. Zou het staal veel meer uitzetten dan het beton, dan zou het bij elke opwarming langs het beton willen glijden en de hechting losscheuren, waardoor de twee niet meer samenwerken. Deze toevallige gelijkheid is een belangrijke reden dat gewapend beton zo sterk en duurzaam is.' },
  { id: 161, categorie: 'Bouwkunde & constructie', vraag: 'Waarom Romeins beton met vulkanische as en zeewater zijn eigen scheuren juist dichtgroeit', uitleg: 'Romeins beton bevat vulkanische as en brokjes ongebluste kalk, dus de massa zit vol reactieve, kalk- en aluminiumrijke stof. Sijpelt er zeewater door een haarscheurtje, dan lost die kalk op en reageert met de as en het zeewater tot nieuwe mineralen, zoals een speciaal calcium-aluminiummineraal en kalksteen, die in de scheur uitkristalliseren. Zo groeit de scheur als het ware weer dicht en herstelt het beton zichzelf ter plekke. Doordat elke nieuwe waterindringing opnieuw mineraalgroei aanjaagt, wordt dit beton in zout zeewater juist sterker, terwijl modern beton daar afbrokkelt.' },
  { id: 162, categorie: 'Bouwkunde & constructie', vraag: 'Waarom een expansievoeg in een brug nodig is omdat staal per 100 meter centimeters uitzet in de zomer', uitleg: 'Staal wordt langer bij warmte, ongeveer twaalf micrometer per meter per graad, dus een brugdek van honderd meter dat veertig graden opwarmt, wordt zo\'n vijf centimeter langer. Zat dat dek aan beide kanten muurvast, dan zou die verhinderde uitzetting reusachtige drukkrachten opwekken die de brug kunnen laten knikken of bezwijken. Een expansievoeg, een naad met wat ruimte, laat het dek vrij langer en korter worden terwijl het verkeer er toch overheen kan rijden. Zo wordt de temperatuurbeweging spanningsloos opgevangen in plaats van omgezet in gevaarlijke krachten.' },
  { id: 163, categorie: 'Bouwkunde & constructie', vraag: 'Waarom "progressive collapse" — het pannenkoek-effect — een gebouw laat instorten als één draagpunt faalt (Ronan Point)', uitleg: 'Progressieve instorting is een kettingreactie waarbij het falen van één draagdeel veel meer schade veroorzaakt dan die ene fout zelf. Valt een kolom of dragend paneel weg, dan moeten de buren opeens die last plus een klap opvangen, en zijn ze daar niet op berekend, dan bezwijken zij ook. De vloer erboven valt dan op de vloer eronder, die de klap niet kan dragen, waarna verdieping na verdieping op elkaar stort als een stapel pannenkoeken. Bij Ronan Point blies een gasexplosie een dragend hoekpaneel weg, waarna de hoeken erboven en eronder zonder alternatief draagpad na elkaar instortten. De les was dat gebouwen reserve-draagpaden en samenhang nodig hebben.' },
  { id: 164, categorie: 'Bouwkunde & constructie', vraag: 'Waarom liquefactie bij een aardbeving vaste grond in drijfzand verandert en gebouwen laat wegzakken', uitleg: 'In los, met water verzadigd zand rusten de korrels normaal op elkaar en dragen ze de last via wrijving. Schudt een aardbeving snel heen en weer, dan willen de korrels dichter opeen zakken, maar het water tussen de korrels kan niet snel genoeg weg, waardoor de waterdruk oploopt. Zodra dat water bijna de hele last overneemt, verliezen de korrels hun onderlinge contact en gedraagt het zand zich als een dikke vloeistof zonder stevigheid. Gebouwen zonder diepe fundering zakken dan weg of kantelen, terwijl lichte ondergrondse constructies juist kunnen opdrijven.' },
  { id: 165, categorie: 'Scheikunde, toegepast', vraag: 'Waarom je door distilleren nooit sterker dan ~96% alcohol krijgt: een azeotroop verdampt als vast mengsel', uitleg: 'Ethanol en water vormen bij ongeveer 95,6 gewichtsprocent alcohol een azeotroop: een mengsel waarbij de damp exact dezelfde samenstelling heeft als de vloeistof. Normaal is de damp rijker aan de vluchtigste stof, zodat je die kunt opconcentreren, maar op dit punt verdwijnt dat verschil. Daardoor levert doorkoken alleen nog damp van diezelfde 96 procent, en kom je met gewoon distilleren niet hoger. Wil je pure alcohol, dan moet je het azeotroop breken, bijvoorbeeld met een hulpstof, met moleculaire zeven of met membranen.' },
  { id: 166, categorie: 'Scheikunde, toegepast', vraag: 'Waarom ketchup pas loopt als je schudt (thixotropie) en oobleck juist hard wordt als je slaat (dilatantie)', uitleg: 'Beide zijn vloeistoffen die niet volgens de normale regels vloeien: hun dikte hangt af van hoe snel je ze roert of slaat. Ketchup wordt juist dunner als je schudt: in rust vormt de tomatenpuree een zwak netwerkje dat door schudden afbreekt, waardoor de viscositeit daalt en het gaat lopen, en zich in rust weer herstelt. Oobleck, maïzena in water, doet het omgekeerde: sla je er snel op, dan kunnen de dicht opeengepakte deeltjes niet snel genoeg langs elkaar wegglijden en klemmen ze vast, zodat het even keihard aanvoelt. Het verschil zit dus in of de microstructuur onder belasting uiteenvalt of juist vastloopt.' },
  { id: 167, categorie: 'Scheikunde, toegepast', vraag: 'Waarom een las in roestvast staal opnieuw gepassiveerd moet worden, anders roest juist de warmtegetinte zone', uitleg: 'Roestvast staal blijft roestvrij dankzij een flinterdunne, chroomrijke beschermlaag die zich vanzelf vormt zolang er genoeg opgelost chroom aan het oppervlak zit. Bij lassen ontstaat rond de naad een verkleurde, verhitte zone waar door de hitte een dikkere, chroomarme oxidelaag groeit en chroom zich bindt in andere verbindingen, zodat het metaal daar plaatselijk te weinig chroom heeft en kan gaan roesten. Passiveren betekent die aangetaste laag verwijderen, meestal door beitsen met zuur, en daarna een schone, chroomrijke beschermlaag laten terugkomen. Zonder die nabehandeling begint corrosie juist in de kwetsbare lasnaad.' },
  { id: 168, categorie: 'Scheikunde, toegepast', vraag: 'Waarom eutectisch soldeer bij één scherpe temperatuur smelt in plaats van eerst pasteus te worden', uitleg: 'Een legering heeft meestal een smelttraject: tussen twee temperaturen bestaan vaste en vloeibare stof naast elkaar en is het materiaal pasteus. Bij precies de eutectische mengverhouding vallen die twee temperaturen samen tot één punt, het laagste smeltpunt van het systeem. Daar smelten beide vaste bestanddelen tegelijk en in vaste verhouding tot een gelijkmatige vloeistof, zonder pasteuze tussenfase. Eutectisch soldeer, zoals de oude tin-loodmix rond 63/37, smelt en stolt daarom scherp op één temperatuur, wat handig is omdat de verbinding snel vast wordt en er tijdens het stollen minder zwakke plekken ontstaan.' },
  { id: 169, categorie: 'Scheikunde, toegepast', vraag: 'Waarom chelaten metaalionen zo strak binden dat ze kalk oplossen of loodvergiftiging behandelen', uitleg: 'Een chelaat is een molecuul met meerdere grijparmen die tegelijk op verschillende plekken aan hetzelfde metaalion vastklikken en er zo een ringetje omheen vormen. Die meervoudige greep maakt het geheel veel stabieler dan losse grijpers, mede omdat één chelaatmolecuul meerdere watermoleculen van het ion verdringt, wat energetisch gunstig uitpakt. Daardoor trekt een chelaat als EDTA calcium- of loodionen effectief uit hun omgeving en houdt ze vast in een goed oplosbaar, ongevaarlijk complex. Zo lost EDTA kalkaanslag op, en bindt het bij chelatietherapie giftig lood tot een pakketje dat via de nieren het lichaam verlaat.' },
  { id: 170, categorie: 'Scheikunde, toegepast', vraag: 'Waarom een buffer de pH stabiel houdt zolang je niet te veel zuur of base toevoegt', uitleg: 'Een buffer bevat tegelijk een zwak zuur en zijn tegenhanger (de bijbehorende base) in ongeveer gelijke hoeveelheden. Voeg je zuur toe, dan vangt de base de extra protonen op; voeg je base toe, dan geeft het zwakke zuur protonen af, zodat de zuurgraad nauwelijks verandert. De pH hangt af van de verhouding tussen die twee, en die verhouding verschuift maar langzaam zolang van beide genoeg aanwezig is. Pas als je zoveel zuur of base toevoegt dat een van de twee bijna op is, raakt de buffer uitgeput en klapt de pH alsnog om.' },
  { id: 171, categorie: 'Scheikunde, toegepast', vraag: 'Waarom supergeleidende magneten met vloeibaar helium gekoeld moeten worden en een "quench" explosief gas vrijmaakt', uitleg: 'Supergeleidende spoelen, bijvoorbeeld van niobium-titaan, verliezen hun elektrische weerstand pas onder een paar graden boven het absolute nulpunt, wat alleen vloeibaar helium bij ongeveer 4 kelvin kan bereiken. Zolang de spoel supergeleidend is, loopt er een enorme stroom weerstandsloos in rond die het sterke magneetveld in stand houdt. Bij een quench schiet een stukje wikkeling opeens terug naar de gewone toestand met weerstand, waar de grote stroom nu warmte in dumpt, wat de omgeving verder opwarmt in een zichzelf voortplantende reactie. Die warmte laat het vloeibare helium plots verdampen, en omdat heliumgas honderden keren meer ruimte inneemt, kan dat gevaarlijke overdruk en zuurstofverdringing geven als het niet veilig wordt afgevoerd.' },
  { id: 172, categorie: 'Scheikunde, toegepast', vraag: 'Waarom katalysatoren een reactie versnellen door de activeringsdrempel te verlagen zonder zelf op te raken', uitleg: 'Een katalysator biedt de reactie een omweg met een lagere drempel, bijvoorbeeld door de reactanten vast te houden, goed te richten of tussenvormen te stabiliseren. Omdat het aandeel moleculen dat genoeg energie heeft om de drempel te halen sterk toeneemt als die drempel daalt, versnelt de reactie flink. De katalysator doet mee in tussenstappen, maar komt aan het eind weer onveranderd tevoorschijn, zodat hij niet opraakt en telkens opnieuw kan werken. Belangrijk: hij verandert alleen de snelheid, niet waar het chemisch evenwicht ligt, want hij verlaagt de drempel in beide richtingen even veel.' },
  { id: 173, categorie: 'Scheikunde, toegepast', vraag: 'Waarom een vlamvertrager werkt door bij hitte zuurstof of radicalen weg te vangen, niet door koeling', uitleg: 'Een vlam houdt zichzelf gaande via een kettingreactie in het gas, waarin zeer reactieve brokstukjes (radicalen) van waterstof, zuurstof en hydroxyl de verbranding aanjagen. Veel vlamvertragers met halogeen of fosfor vallen bij die hitte uiteen en geven stoffen af die juist deze radicalen wegvangen en omzetten in veel tammere deeltjes, waardoor de ketting breekt. Zonder genoeg radicalen dooft de vlam, ook al is er nog brandstof en warmte. Dit chemische kettingbrekende trucje speelt zich af in het gas en is iets anders dan koelen; sommige extra middelen, zoals aluminiumhydroxide, koelen daarnaast wel doordat ze warmte opnemen en water afgeven.' },
  { id: 174, categorie: 'Scheikunde, toegepast', vraag: 'Waarom kristallisatiewarmte van natriumacetaat een hot pack spontaan laat opwarmen zodra je het knikplaatje buigt', uitleg: 'Een hot pack bevat een oververzadigde oplossing van natriumacetaat: door voorzichtig af te koelen zit er meer opgeloste stof in dan bij die temperatuur eigenlijk stabiel is, zonder dat het uitkristalliseert. Die toestand is wankel en wacht op een startpunt. Als je het metalen knikplaatje buigt, geeft dat een schokje of losse deeltjes die als kiem werken, waarna de stof razendsnel uitkristalliseert tot vaste natriumacetaatkristallen. Bij dat kristalliseren komt de eerder opgeslagen warmte weer vrij, zoals bevriezen warmte afgeeft, en warmt de pack duidelijk op. Kook je hem daarna in water, dan lost alles weer op en is hij opnieuw bruikbaar.' },
  { id: 175, categorie: 'Scheikunde, toegepast', vraag: 'Waarom osmose water door een membraan naar de zoutste kant trekt — de basis van je nieren én van ontzilting', uitleg: 'Een semipermeabel membraan laat wel watermoleculen door maar houdt opgeloste zoutdeeltjes tegen. Water stroomt netto van de kant met weinig opgeloste stof naar de kant met veel, omdat het systeem de concentraties gelijk wil trekken. Dat gaat door tot de opgebouwde druk, de osmotische druk, de stroom stopt. In de nieren gebruikt het lichaam zulke zoutverschillen om water uit de voorurine terug te winnen; bij ontzilting doet men het omgekeerde en perst men met een druk hóger dan de osmotische druk zoet water tegen de natuurlijke richting in door het membraan.' },
  { id: 176, categorie: 'Scheikunde, toegepast', vraag: 'Waarom chiraliteit maakt dat één spiegelvorm van een molecuul geneest en de andere vergiftigt (Softenon)', uitleg: 'Chirale moleculen komen in twee spiegelbeelden voor die niet op elkaar passen, net als je linker- en rechterhand. Receptoren en enzymen in het lichaam zijn zelf ook zulke handvormen, dus ze grijpen de twee spiegelvormen verschillend vast en die kunnen dan totaal andere effecten hebben. Bij thalidomide (Softenon) werkte de ene spiegelvorm kalmerend en tegen misselijkheid, terwijl de andere ernstige aangeboren afwijkingen veroorzaakte. Zelfs zuiver toedienen van de goede vorm hielp niet, omdat het lichaam de ene vorm in de andere kan omzetten, zodat scheiden het probleem niet had opgelost.' },
  { id: 177, categorie: 'Scheikunde, toegepast', vraag: 'Waarom vulkanisatie met zwavel rubber van kleverig naar veerkrachtig omzet door de ketens te verknopen', uitleg: 'Onbewerkt natuurrubber bestaat uit lange kettingmoleculen die langs elkaar kunnen glijden, waardoor het plakkerig is, bij warmte vervormt en bij kou bros wordt. Bij vulkanisatie reageert zwavel tijdens verhitten met de ketens en legt zwavelbruggetjes tussen naburige ketens. Die dwarsverbindingen knopen de ketens tot één driedimensionaal net, zodat ze niet meer blijvend langs elkaar wegglijden maar na uitrekken terugveren, zoals een net dat zijn vorm terugpakt. Zo wordt het materiaal elastisch, sterker en veel minder gevoelig voor temperatuur; hoe meer bruggen, hoe harder en stijver, van zachte band tot keihard eboniet.' },
  { id: 178, categorie: 'Scheikunde, toegepast', vraag: 'Waarom elektrolyse van pekel tegelijk chloor, waterstof en natronloog oplevert — de basis van de chemische industrie', uitleg: 'Bij het chlooralkaliproces stuurt men gelijkstroom door een sterk geconcentreerde keukenzoutoplossing (pekel). Aan de ene elektrode geven de chloride-ionen elektronen af en ontstaat chloorgas; aan de andere elektrode wordt water omgezet in waterstofgas, waarbij hydroxide-ionen vrijkomen. De achtergebleven natriumionen vormen samen met die hydroxide-ionen natronloog in de oplossing. Om te voorkomen dat het chloor en de loog met elkaar reageren, houdt men de twee kanten gescheiden met een membraan. Deze drie producten, chloor, waterstof en natronloog, zijn grondstoffen voor talloze andere processen, en dat maakt dit proces zo centraal in de chemie.' },
  { id: 179, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom weefsel juist beschadigt als het bloed terugkeert na zuurstoftekort ("reperfusieschade") door een stortvloed vrije radicalen', uitleg: 'Tijdens zuurstoftekort schakelt weefsel over op noodstofwisseling zonder zuurstof, stapelen afbraakstoffen zich op en verandert een bepaald enzym in een vorm die op zuurstof reageert, terwijl er brandstof voor dat enzym ophoopt. Zodra het bloed terugkeert en er plots weer zuurstof binnenstroomt, produceert dit systeem in één klap een stortvloed agressieve zuurstofdeeltjes (vrije radicalen). Die radicalen beschadigen celwanden, eiwitten en DNA en zetten in de energiefabriekjes van de cel de deur naar celdood open. Bovendien lokt de terugkeer een ontsteking en calciumoverbelasting uit, zodat de schade na herstel van de doorbloeding soms groter is dan tijdens het tekort zelf.' },
  { id: 180, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom een uitgehongerd lichaam kan sterven als je te snel voedt ("refeeding syndrome") door instortende fosfaatspiegels', uitleg: 'Bij langdurige honger leeft het lichaam van vet en eiwit, is de insuline laag en raken de voorraden fosfaat, kalium en magnesium in de cellen uitgeput, ook al lijken de bloedwaarden eerst nog normaal. Geef je dan plots veel koolhydraten, dan schiet de insuline omhoog en drijft die glucose, fosfaat, kalium en magnesium massaal de cellen in voor de weer opgestarte stofwisseling. Daardoor storten de bloedspiegels in, vooral van fosfaat, dat onmisbaar is voor het maken van energie (ATP) en voor de celwanden. Dat plotse fosfaattekort, samen met lage kalium-, magnesium- en vitamine B1-waarden, kan hartritmestoornissen, hartfalen en verlammingen geven, soms dodelijk, en daarom moet je uitgehongerde mensen langzaam en gecontroleerd bijvoeden.' },
  { id: 181, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom je hartspier zichzelf niet kan verkrampen zoals een gewone spier: een lange refractaire periode beschermt het ritme', uitleg: 'In een gewone spier duurt de elektrische prikkel maar enkele milliseconden, zodat snel opeenvolgende prikkels kunnen optellen tot één langdurige, kramp-achtige samentrekking. Hartspiercellen hebben daarentegen een prikkel met een lang plateau, doordat trage calciumpoortjes lang openblijven, waardoor de cel bijna even lang onprikkelbaar blijft als de samentrekking duurt. Tijdens die lange \'rustperiode\' kan een nieuwe prikkel de cel niet opnieuw aanzetten voordat hij alweer bijna ontspannen is. Zo kan het hart niet in kramp schieten en blijft er tussen elke slag ontspanning over, waarin het zich met bloed kan vullen, wat nodig is om te blijven pompen.' },
  { id: 182, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom hemoglobine zuurstof juist loslaat in warm, zuur, CO₂-rijk weefsel (het Bohr-effect)', uitleg: 'Hoe goed hemoglobine zuurstof vasthoudt, hangt af van zijn omgeving. In hard werkend weefsel ontstaat kooldioxide dat het bloed daar zuurder maakt, en zijn ook de temperatuur en een hulpstofje verhoogd. Die omstandigheden duwen hemoglobine in een vorm die zuurstof minder graag vasthoudt, waardoor het bij dezelfde zuurstofdruk juist méér zuurstof loslaat, precies waar de weefsels het het hardst nodig hebben. In de longen gebeurt het omgekeerde: daar verdwijnt de kooldioxide met de uitademing, wordt het bloed minder zuur en pakt hemoglobine de zuurstof weer stevig op.' },
  { id: 183, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom een "grensinfarct" (watershed) ontstaat op het niemandsland tussen twee slagaders bij bloeddrukval', uitleg: 'Grenszones liggen op het uiterste randje van de voedingsgebieden van twee naburige slagaders, waar de bloeddruk het laagst is omdat ze het verst van beide bronnen liggen. Zakt de bloeddruk of de pompkracht van het hart in het algemeen weg, bijvoorbeeld bij shock of een hartstilstand, dan krijgen juist deze verste randgebieden als eerste te weinig bloed. Anders dan bij een afgesloten slagader, waar één vat plots dichtzit, ontstaat de schade hier doordat het overal tegelijk te weinig doorstroomt. In de hersenen ligt zo\'n zone tussen de gebieden van de grote hersenslagaders, wat een kenmerkend uitvalspatroon geeft.' },
  { id: 184, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom je nieren met tegenstroom een extreem zoute merg opbouwen om water terug te winnen', uitleg: 'De lis van Henle in de nier werkt als een slimme lus: het opstijgende been pompt zout naar buiten maar laat geen water door, terwijl het afdalende been juist wél water doorlaat. Doordat de twee benen tegengesteld naast elkaar liggen, wordt een klein zoutverschil telkens verder opgeteld tot een zeer steile zoutgradiënt, met diep in het niermerg extreem zout weefsel. De omringende bloedvaten volgen dezelfde lusvorm zodat ze dat zout niet wegspoelen. Wordt onder invloed van het hormoon ADH de afvoerbuis waterdoorlatend, dan trekt dat zoute merg water uit de urine terug het lichaam in, zodat er sterk geconcentreerde urine ontstaat en water bespaard wordt.' },
  { id: 185, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom pinguïn- en meeuwpoten niet bevriezen dankzij tegenstroom-warmtewisseling tussen slagader en ader', uitleg: 'In de poten liggen de slagaders die warm bloed omlaag brengen dicht tegen de aders die koud bloed terugvoeren, in een fijn vatennetwerk. Doordat het bloed in beide vaten tegengesteld stroomt, geeft het warme bloed dat naar beneden gaat zijn warmte geleidelijk af aan het koude bloed dat omhoog komt. Zo komt het bloed al flink afgekoeld in de poot aan, waardoor er nauwelijks warmte naar de koude grond weglekt, terwijl het terugkerende bloed alweer voorverwarmd de romp binnenkomt. De poot werkt daardoor net boven het vriespunt met minimaal warmteverlies, wat cruciaal is voor vogels op ijs of in koud water.' },
  { id: 186, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom je milt bij duiken en inspanning samentrekt en een extra scheut rode bloedcellen vrijgeeft', uitleg: 'De milt slaat een deel van de rode bloedcellen op als reserve, buiten de gewone bloedsomloop. Bij inspanning of bij het duiken zet het lichaam de spieren in de miltwand aan het samentrekken, zodat het opgeslagen, celrijke bloed in de bloedbaan wordt geperst. Daardoor stijgt tijdelijk het aantal rode cellen en dus het zuurstoftransport, wat bij duiken helpt om langer onder water te blijven. Bij getrainde vrijduikers is dit effect duidelijk sterker meetbaar, en de milt vult zich daarna weer aan. Het is dus een acute, door zenuwen gestuurde eigen bloedtransfusie, geen nieuwe aanmaak.' },
  { id: 187, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom "hypoxische pulmonale vasoconstrictie" bloed juist wégstuurt van slecht beademde longdelen (uniek voor de longen)', uitleg: 'In de meeste organen gaan bloedvaten bij zuurstoftekort juist open om meer bloed aan te trekken, maar in de longen gebeurt het omgekeerde: waar in de longblaasjes weinig zuurstof zit, knijpen de kleine longslagaders juist dicht. Zo stuurt de long het bloed weg van slecht beademde delen naar delen die wél goed van lucht worden voorzien. Daardoor stroomt het bloed niet nutteloos langs blaasjes zonder zuurstof, en keert het minder zuurstofarm terug. Dit is handig bij een lokaal probleem, maar schadelijk bij zuurstofgebrek in de hele long, zoals op grote hoogte of bij chronische longziekte, want dan vernauwt alles tegelijk en loopt de druk in de longvaten gevaarlijk op.' },
  { id: 188, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom te snel stijgen uit diepte decompressieziekte geeft: opgelost stikstof borrelt als in een openende frisdrankfles', uitleg: 'Onder water staat een duiker onder hoge druk, waardoor er meer inert gas, vooral stikstof, in bloed en weefsels oplost naarmate hij dieper en langer duikt. Bij het opstijgen daalt de druk, zodat het weefsel opeens meer stikstof bevat dan het kan vasthouden, en dat gas moet er weer uit. Stijg je langzaam, dan kan het overtollige gas rustig via de longen worden uitgeademd, maar stijg je te snel, dan zakt de druk sneller dan het gas kan wegdiffunderen en vormt het ter plekke belletjes, net als bij het openen van een frisdrankfles. Die belletjes verstoppen bloedvaten en drukken op weefsel en zenuwen, wat de pijn en verlammingen van decompressieziekte veroorzaakt.' },
  { id: 189, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom zuurstof zélf onder hoge druk giftig wordt en duikers laat stuiptrekken (Paul Bert-effect)', uitleg: 'Onder hoge druk stijgt ook de druk van de zuurstof zelf, en boven ongeveer 1,4 tot 1,6 bar zuurstof wordt die giftig voor het zenuwstelsel. De hoge zuurstofspanning jaagt de vorming van agressieve zuurstofdeeltjes aan en verstoort de balans van boodschapperstoffen en enzymen in de hersenen, zodat de zenuwcellen te prikkelbaar worden. Het gevolg kan een plotselinge epileptische aanval met stuiptrekkingen zijn, wat onder water levensgevaarlijk is omdat de duiker kan verdrinken. Dit effect begrenst hoe diep men met zuurstofrijke ademmengsels mag duiken, los van een ander, trager longeffect bij langdurige matige overdruk.' },
  { id: 190, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom je lichaam het calcium in je bloed liever constant houdt en het desnoods uit je botten sloopt', uitleg: 'Het calciumgehalte in je bloed moet heel precies blijven, want calcium is onmisbaar voor zenuwprikkeling, spiersamentrekking inclusief het hart, bloedstolling en talloze celsignalen; te veel of te weinig geeft meteen gevaarlijke stoornissen. Dreigt de bloedwaarde te dalen, dan geven de bijschildklieren parathormoon af, dat botafbrekende cellen aanzet om bot af te breken en calcium vrij te maken, de nieren calcium laat terugwinnen en de aanmaak van actief vitamine D stimuleert voor betere opname uit de darm. Het skelet dient hierbij als een grote calciumvoorraad die het lichaam desnoods aanspreekt om de bloedwaarde te redden. Op korte termijn weegt de bloedwaarde dus zwaarder dan de botsterkte, wat bij langdurige ontregeling tot botontkalking kan leiden.' },
  { id: 191, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom doorverwezen pijn een hartinfarct in je linkerarm laat voelen: zenuwen delen hetzelfde ruggenmergsegment', uitleg: 'Pijnsignalen van inwendige organen en van bepaalde huidgebieden komen op hetzelfde niveau het ruggenmerg binnen en gaan daar over op dezelfde doorgeefzenuwcellen. De hersenen kunnen dan niet goed zien of het signaal van het hart of van de huid komt, en gokken vaak op de vertrouwdere lichaamsoppervlakte. Omdat het hart zijn gevoelszenuwen deelt met de segmenten die ook de linkerarm en -schouder verzorgen (ongeveer T1 tot T4), wordt de pijn bij een hartinfarct dáárheen geprojecteerd. Ditzelfde verschijnsel verklaart ook andere klassieke uitstralingspatronen, zoals naar de kaak of de bovenbuik.' },
  { id: 192, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom je lever als enig orgaan kan hergroeien tot bijna de volledige omvang', uitleg: 'De lever kan als enig orgaan opvallend goed aangroeien: na verlies van weefsel, door operatie of schade, gaan de overgebleven rijpe levercellen zelf weer delen. Groeifactoren en ontstekingsboodschappers zetten die deling kort na het verlies op een gecoördineerde manier in gang. De lever herstelt vooral zijn massa en werking, niet exact de oude vorm, en stopt de groei zodra de juiste verhouding tussen levergrootte en lichaam weer is bereikt. Dankzij dit nauwkeurig geregelde proces kan een stuk lever van een levende donor worden getransplanteerd, waarna beide levers weer aangroeien.' },
  { id: 193, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom de duikreflex je hartslag onderwater dropt en drenkelingen soms na lang onder ijs nog reanimeerbaar zijn', uitleg: 'Zodra vooral een koud gezicht in het water komt, treedt de duikreflex in werking: via bepaalde hersenzenuwen daalt de hartslag en knijpen de bloedvaten in armen, benen en huid dicht. Zo wordt het bloed met zijn zuurstof gecentreerd naar hart en hersenen, de organen die zuurstof het minst kunnen missen. De felle kou verlaagt bovendien de stofwisseling en de zuurstofbehoefte van de hersenen flink. Bij onderdompeling in ijskoud water, vooral bij kinderen, kan de combinatie van trage hartslag, herverdeeld bloed en onderkoeling de hersenen zo lang beschermen dat reanimatie na tientallen minuten onder water soms nog lukt, volgens de regel dat iemand pas dood is als hij warm én dood is.' },
  { id: 194, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom een zware maaltijd flauwvallen kan geven doordat bloed naar de darmen wordt weggeleid', uitleg: 'Na een grote maaltijd gaan de bloedvaten van maag en darmen ver open om de spijsvertering te helpen, waardoor een flink deel van het bloed zich in de buik verzamelt. Normaal vangt het lichaam dit op met een snellere hartslag en dichtgeknepen vaten elders, zodat de bloeddruk en de doorbloeding van de hersenen op peil blijven. Bij kwetsbare mensen, vaak ouderen, schiet die compensatie tekort, zakt de bloeddruk en krijgen de hersenen even te weinig bloed, wat duizeligheid of flauwvallen geeft. Het effect is sterker na koolhydraatrijke maaltijden en kan door alcohol of bepaalde bloeddrukmedicijnen worden versterkt.' },
  { id: 195, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom gluconeogenese je lichaam suiker uit eiwit laat maken als de koolhydraten opraken', uitleg: 'Sommige weefsels, vooral de hersenen en rode bloedcellen, draaien bijna volledig op glucose, terwijl de suikervoorraad in de lever al na ongeveer een dag vasten op is. Om de bloedsuiker toch op peil te houden, gaat de lever (en deels de nier) zelf nieuwe glucose maken uit niet-suikerbronnen, wat gluconeogenese heet. Belangrijke grondstoffen zijn aminozuren uit spiereiwit, melkzuur en glycerol uit vetafbraak, die via tussenstappen glucose worden. Vooral het aminozuur alanine reist vanuit de spier naar de lever om als bouwstof te dienen, wat verklaart waarom langdurig vasten spiereiwit afbreekt om de suikervoorziening te redden.' },
  { id: 196, categorie: 'Fysiologie & interne geneeskunde', vraag: 'Waarom je bloed-hersenbarrière de meeste stoffen weert maar glucose en alcohol wél doorlaat', uitleg: 'De bloed-hersenbarrière bestaat uit hersenhaarvaten waarvan de wandcellen door zeer strakke naden bijna niets tussen de cellen door laten, zodat stoffen alleen dwars door de cellen heen kunnen. Kleine, vetoplosbare, ongeladen moleculen zoals alcohol lossen makkelijk op in de celwanden en glippen zo vanzelf de hersenen in. Glucose is juist niet vetoplosbaar, maar wordt door speciale transporteiwitten actief naar binnen gesluisd, omdat de hersenen die brandstof hard nodig hebben. De meeste andere, grotere of geladen stoffen missen zo\'n transporter en worden zo effectief buiten de hersenen gehouden, wat het brein beschermt tegen gifstoffen en schommelingen.' },
  { id: 197, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom niemand exact weet hóe algehele narcose bewustzijn uitschakelt (de Meyer-Overton-correlatie blijft onverklaard)', uitleg: 'De Meyer-Overton-correlatie laat zien dat een narcosegas sterker werkt naarmate het beter in vet oplost, wat lang deed vermoeden dat narcose gewoon ontstaat doordat de stof de vetachtige celwanden verstoort. Die simpele vet-theorie blijkt echter niet te kloppen, onder meer omdat sommige even vetoplosbare stoffen géén narcose geven en de effecten afhangen van de precieze spiegelvorm van het molecuul. Tegenwoordig weet men dat narcosemiddelen op specifieke eiwitten inwerken, vooral door remmende receptoren te versterken en prikkelende kanalen af te remmen. Toch ontbreekt nog steeds een sluitende verklaring hoe die effecten samen precies het bewustzijn uitschakelen, waardoor het echte mechanisme onopgelost blijft.' },
  { id: 198, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom een druppel adrenaline bij een verdoving de werking urenlang rekt door de bloedvaten dicht te knijpen', uitleg: 'Adrenaline is een krachtige vaatvernauwer die de bloedvaten rond de prikplek laat samentrekken. Doordat de doorbloeding daar afneemt, wordt de verdovingsstof veel langzamer afgevoerd en blijft die langer in hoge concentratie bij de zenuw, wat de verdoving langer en dieper maakt. Tegelijk komt de stof trager in de rest van het bloed, waardoor de piekconcentratie lager blijft en men veiliger een wat hogere lokale dosis kan geven. De vaatvernauwing zorgt bovendien voor een droger, minder bloedend operatiegebied. Daarom vermijdt men adrenaline juist bij vingers, tenen en neuspunt, waar te sterke vaatvernauwing het weefsel kan beschadigen.' },
  { id: 199, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom lokale verdoving in ontstoken (zuur) weefsel slechter werkt omdat het molecuul de cel niet meer in komt', uitleg: 'Verdovingsmiddelen zijn zwakke basen die in twee vormen naast elkaar bestaan: een geladen vorm en een ongeladen, vetoplosbare vorm. Alleen de ongeladen vorm kan door de zenuwcelwand naar binnen glippen, terwijl juist de geladen vorm bínnen de cel het natriumkanaal blokkeert en zo de verdoving veroorzaakt. Ontstoken weefsel is zuur, en bij die lage zuurgraad verschuift het evenwicht naar de geladen vorm, zodat er veel minder ongeladen molecuul overblijft om de wand te passeren. Daardoor bereikt te weinig werkzame stof de binnenkant van de zenuw en werkt de verdoving in een ontstoken abces duidelijk slechter.' },
  { id: 200, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom "first-pass metabolisme" in de lever maakt dat een pil veel hoger gedoseerd moet dan een injectie', uitleg: 'Een ingeslikt medicijn gaat vanuit de darm eerst via de poortader naar de lever voordat het de rest van het lichaam bereikt. Tijdens die eerste passage kunnen leverenzymen, en soms al de darmwand, een flink deel van de stof afbreken of omzetten, wat het first-pass-effect heet. Daardoor komt maar een deel van de ingenomen dosis onveranderd in het bloed, wat de werkzaamheid van een pil verlaagt. Een injectie in de ader slaat de darm en de lever over en levert bijna de volledige dosis meteen aan de bloedsomloop. Om met een pil dezelfde bloedspiegel te bereiken, moet de dosis dus flink hoger zijn dan bij een injectie.' },
  { id: 201, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom sommige pillen "enteric coated" zijn om pas in de darm en niet in het maagzuur op te lossen', uitleg: 'Een enteric coating is een dun laagje polymeer om de pil dat oplost afhankelijk van de zuurgraad. In de maag is het heel zuur (pH ongeveer 1 tot 3); daar blijft het laagje dicht. Pas in de dunne darm, waar het minder zuur is (pH boven 5,5), valt de laag uit elkaar. Zo blijven zuurgevoelige stoffen zoals maagzuurremmers heel, en wordt tegelijk het maagslijmvlies beschermd tegen prikkelende stoffen zoals aspirine. Het is dus geen tijdklok maar een zuur-schakelaar; nadeel is dat de maag onvoorspelbaar leegt, waardoor de opname wisselt.' },
  { id: 202, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom grapefruit een enzym (CYP3A4) blokkeert waardoor medicijnen dodelijk kunnen stapelen', uitleg: 'Grapefruit bevat stoffen (furanocoumarines) die het enzym CYP3A4 in je darmwand kapotmaken. Dat enzym breekt normaal een groot deel van veel geslikte medicijnen al af voordat ze in je bloed komen. Zet je dat enzym uit, dan komt er ineens veel meer werkzame stof in je bloed. Bij medicijnen met een smalle veilige marge, zoals sommige cholesterolverlagers of bloeddrukpillen, kan de spiegel daardoor giftig hoog worden. Omdat het enzym echt kapot is en het lichaam dagen nodig heeft om nieuw aan te maken, houdt het effect lang aan.' },
  { id: 203, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom een "loading dose" hoger is: je moet eerst het hele lichaamscompartiment vullen voor de spiegel klopt', uitleg: 'De eerste, hogere dosis (oplaaddosis) hangt af van hoe ver een medicijn zich door het lichaam verspreidt, niet van hoe snel het wordt afgebroken. Stoffen die zich sterk in weefsels nestelen hebben veel materiaal nodig voordat het bloed het juiste niveau bereikt. Zonder oplaaddosis zou het vier tot vijf halfwaardetijden duren voor de spiegel klopt, wat bij traag afgebroken middelen dagen kost. De oplaaddosis vult het lichaam in één keer, waarna de kleinere gewone dosis alleen nog bijhoudt wat er wordt afgebroken.' },
  { id: 204, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom de halfwaardetijd bepaalt dat een medicijn pas na ~5 doseringen zijn stabiele spiegel bereikt', uitleg: 'De halfwaardetijd is de tijd waarin de helft van een medicijn verdwijnt. Slik je regelmatig bij, dan stapelt de stof op tot er per keer evenveel wordt afgebroken als je erbij neemt; dat evenwicht heet de stabiele spiegel. Dat vult zich stap voor stap: na één halfwaardetijd zit je op de helft, na twee op driekwart, na drie op bijna 90 procent, en na vier tot vijf op ruim 95 procent. Daarom duurt het steeds ongeveer vier tot vijf halfwaardetijden voor de spiegel stabiel is, en net zo lang voor het middel weer is uitgewerkt als je stopt.' },
  { id: 205, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom "diffusiehypoxie" kort na lachgas ontstaat als het snel uitstromende gas de zuurstof in je longen verdringt', uitleg: 'Lachgas lost slecht op in bloed, dus als je stopt met toedienen stroomt het razendsnel en in grote hoeveelheid terug je longblaasjes in. Die golf gas verdunt de lucht in je longen, waardoor er tijdelijk minder zuurstof en minder koolzuur in zit. Minder zuurstof betekent minder opname in je bloed, en minder koolzuur zwakt je ademprikkel af, zodat je nog minder ademt. Samen kan dat kort een zuurstoftekort geven. Daarom laat men iemand na een lachgasnarcose een paar minuten pure zuurstof inademen.' },
  { id: 206, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom tolerantie ontstaat doordat cellen receptoren terugtrekken bij aanhoudende blootstelling', uitleg: 'Als een receptor (het slot waarop een medicijn past) steeds wordt geprikkeld, stelt de cel hem eerst tijdelijk buiten werking door er een remmend eiwit op te zetten. Daarna trekt de cel de receptor naar binnen en breekt hem deels af, zodat er minder slots overblijven. Je hebt dan een hogere dosis nodig voor hetzelfde effect: dat is tolerantie. Daarnaast kan het lichaam het middel ook sneller gaan afbreken, maar het terugtrekken van receptoren verklaart waarom de cel zelf ongevoeliger wordt.' },
  { id: 207, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom prodrugs pas in het lichaam in de werkzame vorm worden omgezet (codeïne wordt morfine)', uitleg: 'Een prodrug is een medicijn dat zelf nog niet werkt en pas in het lichaam wordt omgezet in de werkzame vorm, vaak voor betere opname of gerichte werking. Codeïne wordt in de lever door het enzym CYP2D6 omgezet in morfine, dat het eigenlijke pijnstillende werk doet. Mensen verschillen genetisch in hoeveel van dat enzym ze hebben: bij trage omzetters werkt codeïne nauwelijks, bij snelle omzetters kan het juist gevaarlijk veel morfine geven. Hetzelfde principe zie je bij enalapril, dat pas in het lichaam actief wordt.' },
  { id: 208, categorie: 'Farmacologie & anesthesie', vraag: 'Waarom een antagonist als naloxon een overdosis in seconden opheft door de opioïdreceptor te bezetten', uitleg: 'Naloxon past heel goed op dezelfde receptor als opioïden zoals heroïne of fentanyl, maar het geeft zelf geen signaal af. Het duwt de opioïden van de receptor af en bezet hun plek, zodat de receptor niet meer wordt aangezet. Daardoor komt de ademhaling vrijwel meteen weer op gang en verdwijnt de levensgevaarlijke ademstilstand, bij een prik in de ader binnen één tot twee minuten. Gevaar is wel dat naloxon korter werkt dan veel opioïden, zodat de ademnood kan terugkeren en een nieuwe dosis nodig kan zijn.' },
  { id: 209, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom je hersenen elk beeld actief "voorspellen" en je pas een fractie later corrigeren (predictive coding)', uitleg: 'Volgens het idee van predictive coding maken je hersenen voortdurend een gok over wat je zo meteen gaat zien, en sturen die verwachting naar de lagere hersengebieden. Die vergelijken de gok met wat de ogen echt binnenkrijgen en sturen alleen het verschil terug omhoog. Zo hoeft er veel minder informatie doorgestuurd te worden. De hersenen passen hun gok steeds aan om dat verschil klein te maken, een soort slim afwegen van kansen. Omdat zenuwsignalen tijd kosten, is wat je ziet dus deels een goed gekalibreerde voorspelling die pas achteraf wordt bijgesteld.' },
  { id: 210, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom je je vroege babyjaren niet herinnert: de hippocampus rijpt pas later (infantiele amnesie)', uitleg: 'Je herinnert je je babytijd niet doordat de hippocampus, het hersendeel dat samenhangende herinneringen vastlegt, dan nog niet rijp is. In die vroege jaren worden er bovendien volop nieuwe hersencellen aangemaakt, en die kunnen bestaande geheugensporen overschrijven of verstoren. Ook zijn taal en zelfbesef nog te weinig ontwikkeld om ervaringen in een verhaal te vatten dat je later kunt terughalen. Het gaat dus niet om verdringen, maar om herinneringen die onvolledig worden opgeslagen en snel weer vervagen.' },
  { id: 211, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom je oog een blinde vlek heeft die je brein onzichtbaar invult', uitleg: 'Op één plek in je oog, de plek waar de oogzenuw het netvlies verlaat, zitten geen lichtgevoelige cellen. Wat daar op valt wordt niet geregistreerd; dat is de blinde vlek. Je merkt het meestal niet omdat je andere oog dat stukje wel ziet en de twee blinde vlekken niet op dezelfde plaats liggen. Zelfs met één oog dicht valt het gat niet op: je hersenen vullen het gebied bij op basis van de kleur, textuur en patronen eromheen. Je brein verzint daar dus actief een geloofwaardige invulling in plaats van een gat te tonen.' },
  { id: 212, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom "saccadische onderdrukking" je blind maakt tijdens de flitsende oogbewegingen zelf, zodat de wereld niet verspringt', uitleg: 'Als je ogen razendsnel van punt naar punt springen (een saccade), schiet het beeld met hoge snelheid over je netvlies en zou je een onbruikbare veeg zien. Daarom zetten je hersenen het zien vlak voor en tijdens die sprong even uit. Dat kan omdat het commando om de ogen te bewegen ook een kopie naar het zichtsysteem stuurt, met de boodschap: deze beweging maak ik zelf. Vooral het kanaal dat gevoelig is voor snelle beweging wordt gedempt. Zo mis je de veeg en lijkt de wereld stabiel, alsof het beeld van vóór en ná de sprong naadloos aan elkaar plakt.' },
  { id: 213, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom de McGurk-illusie laat zien dat wat je ziet verandert welke klank je hóórt', uitleg: 'Bij de McGurk-illusie hoor je een klank, bijvoorbeeld \'ba\', terwijl je lippen ziet die een andere klank vormen, bijvoorbeeld \'ga\'. Veel mensen horen dan een derde klank, zoals \'da\'. Dit laat zien dat je bij spraak niet alleen luistert maar ook kijkt: je hersenen versmelten wat je hoort en ziet tot één waarneming. Bij tegenstrijdige info kiest het brein een compromis dat het beste bij allebei past, waarbij de lipbeweging zwaar meetelt. Het gebeurt onbewust en blijft werken, zelfs als je de truc kent, wat erop wijst dat de versmelting vroeg en automatisch gebeurt.' },
  { id: 214, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom kleuren bij schemer verschuiven zodat rood zwart wordt en blauw oplicht (Purkinje-effect)', uitleg: 'Je oog heeft twee soorten lichtcellen: kegels voor kleur bij daglicht en staafjes voor zwak licht. Ze zijn gevoelig voor verschillende kleuren: bij daglicht zie je geelgroen het helderst, maar de staafjes reageren het sterkst op blauwgroen. Wordt het donker en nemen de staafjes het over, dan verschuift je gevoeligheid naar blauw, waardoor blauwe tinten oplichten en rood, waar staafjes bijna niet op reageren, wegvalt naar zwart. Dat heet het Purkinje-effect. Omdat staafjes geen kleur zien, neem je in echte duisternis alleen nog licht en donker waar.' },
  { id: 215, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom je eigen stem lager klinkt in je hoofd door beengeleiding en je een opname vreemd vindt', uitleg: 'Als je zelf praat, bereikt het geluid je binnenoor op twee manieren: door de lucht via je gehoorgang, en door trillingen die via je schedelbotten rechtstreeks je slakkenhuis aantrillen. Die botgeleiding brengt vooral de lage tonen goed door, waardoor je eigen stem voor jou voller en lager klinkt dan hij echt is. Een opname bevat alleen het deel dat door de lucht ging, zonder die extra lage tonen, en klinkt daardoor hoger en dunner. Omdat je gewend bent aan de door je botten gekleurde versie, vind je de opname vreemd.' },
  { id: 216, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom het faseverschil tussen je twee oren (< een milliseconde) je vertelt uit welke richting een laag geluid komt', uitleg: 'Een geluid van opzij bereikt je dichtstbijzijnde oor iets eerder dan het andere, met een verschil van hooguit ongeveer 0,6 duizendste seconde. Bij lage tonen, waarvan de golf breder is dan je hoofd, kan je brein aan het verschoven ritme van die golf tussen beide oren precies aflezen waar het geluid vandaan komt. Speciale zenuwcellen werken daarbij als tijdvergelijkers die het minieme tijdsverschil meten. Bij hoge tonen wordt dat verschil onduidelijk, en dan schakelt je brein over op het verschil in luidheid, doordat je hoofd het verste oor een beetje in de geluidsschaduw zet.' },
  { id: 217, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom fantoompijn en jeuk-op-afstand bewijzen dat de hersenkaart van je lichaam plastisch is', uitleg: 'In de hersenschors ligt een soort landkaart van je lichaam, waarbij naast elkaar liggende lichaamsdelen ook naast elkaar op de kaart staan. Na een amputatie krijgt het gebied van bijvoorbeeld de hand geen signalen meer, en dan groeien buurgebieden, zoals dat van het gezicht, eroverheen. Prikkel je dan het gezicht, dan kan dat als gevoel in de verdwenen hand aankomen, en het brein blijft signalen uit dat gebied uitleggen alsof ze uit de hand komen. Zo ontstaan fantoompijn en jeuk op de verkeerde plek. Het bewijst dat die lichaamskaart geen vaste bedrading is maar zich blijft aanpassen.' },
  { id: 218, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom proprioceptie — je "zesde zintuig" — je met dichte ogen precies laat weten waar je hand is', uitleg: 'Proprioceptie is je gevoel voor de stand van je lichaam. Het werkt met speciale sensoren: spierspoeltjes meten hoe lang en hoe snel een spier verandert, peesorganen meten de spanning, en sensoren in gewrichten en huid melden de hoek van een gewricht. Die signalen stromen continu via het ruggenmerg naar de hersenschors en de kleine hersenen, die ze samenvoegen tot een beeld van je houding. Daardoor weet je zonder te kijken waar je hand is en hoe die beweegt, wat nodig is voor coördinatie en balans. Bij uitval, bijvoorbeeld door zenuwschade, moeten mensen elke beweging met hun ogen controleren.' },
  { id: 219, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom je bij te snel opstaan sterretjes ziet: netvliescellen vuren bij zuurstoftekort willekeurig', uitleg: 'Sta je te snel op, dan zakt door de zwaartekracht even je bloeddruk in je hoofd voordat je lichaam dat corrigeert, en krijgt je netvlies kort te weinig bloed. De lichtcellen en zenuwcellen daar zijn energieslurpers en raken bij dat zuurstof- en suikertekort ontregeld, waardoor ze uit zichzelf willekeurig gaan vuren. Je brein leest die signalen als lichtflitsen, de sterretjes, ook al valt er geen licht in je oog. Zodra je bloeddruk zich herstelt, verdwijnen ze weer.' },
  { id: 220, categorie: 'Neurowetenschap & zintuigen', vraag: 'Waarom tinnitus vaak geen oorprobleem is maar het brein dat ontbrekende input met eigen ruis opvult', uitleg: 'Bij veel tinnitus ligt de oorzaak wel in het oor, meestal beschadigde haarcellen in het slakkenhuis voor een bepaald toonhoogtegebied, maar het fantoomgeluid zelf ontstaat in de hersenen. Krijgen de hersenen minder signaal uit dat gebied, dan draaien ze het volume van die zenuwcellen omhoog om het gemis te compenseren. Die overversterkte cellen gaan uit zichzelf en gelijk op vuren, wat je waarneemt als een aanhoudende toon of ruis zonder echte geluidsbron. Daarom blijft tinnitus vaak bestaan ook al is het oor behandeld, en hangt het samen met veranderingen in het gehoorgebied van de hersenen.' },
  { id: 221, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom het méér energie kost om in de zon te vallen dan om het zonnestelsel te verlaten: je moet eerst de baansnelheid van de aarde wegremmen', uitleg: 'De aarde suist met zo\'n 30 kilometer per seconde in een baan om de zon, en een sonde die vanaf de aarde vertrekt neemt die enorme zijwaartse snelheid mee. Wil je recht in de zon vallen, dan moet je vrijwel al die 30 km/s wegremmen zodat het object zijn baan verliest en naar binnen tuimelt, en dat kost gigantisch veel. Om juist het zonnestelsel te verlaten hoef je vanaf de aardbaan maar ongeveer 12 km/s extra bij te winnen. Daarom is een reis naar de zon energetisch zwaarder dan een reis de ruimte in, en gebruikt men zwaartekrachtslingers langs planeten om alsnog af te remmen.' },
  { id: 222, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom een raketmotor efficiënter is diep in een zwaartekrachtput (Oberth-effect): dezelfde stuwstof levert daar meer kinetische energie', uitleg: 'De bewegingsenergie van een raket groeit niet recht evenredig met de snelheid, maar met het kwadraat ervan: dezelfde snelheidsboost levert meer energie op als je al hard gaat. Diep in een zwaartekrachtput, bijvoorbeeld op het laagste, snelste punt van een baan, ga je het hardst, dus daar zet dezelfde hoeveelheid brandstof om in de grootste energiewinst. Bovendien halen de uitlaatgassen daar meer nuttige arbeid uit, omdat ze relatief langzamer achterblijven. Daarom plannen missieontwerpers grote motorstoten het liefst op het snelste punt van de baan, om brandstof te sparen. Dit heet het Oberth-effect.' },
  { id: 223, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom een "gravity assist" langs een planeet snelheid wint terwijl de planeet minuscuul afremt', uitleg: 'Bij een gravity assist valt de sonde in het zwaartekrachtveld van een bewegende planeet en verlaat dat weer. Ten opzichte van de planeet komt ze er even snel weer uit als ze erin ging, alleen in een andere richting. Maar ten opzichte van de zon telt de snelheid van de planeet mee, zodat die verdraaide snelheid van de sonde in totaal groter (of kleiner) kan uitpakken. Eigenlijk ruilen sonde en planeet bewegingsenergie: de sonde wint precies wat de planeet verliest, maar omdat de planeet onvoorstelbaar veel zwaarder is, remt die onmeetbaar weinig af. Zo halen missies zoals Voyager gratis snelheid zonder brandstof.' },
  { id: 224, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom een geostationaire baan exact op 35.786 km ligt en alleen boven de evenaar kan', uitleg: 'Een satelliet lijkt stil boven één plek te hangen als hij precies even snel rondgaat als de aarde draait, in één etmaal. Uit de wetten van Kepler, die omlooptijd aan baanhoogte koppelen, volgt dat dit maar op één hoogte lukt: ongeveer 35.786 kilometer boven het aardoppervlak. Bovendien moet de baan precies boven de evenaar liggen. Bij elke andere helling zou de satelliet vanaf de grond gezien elke dag een lus naar noord en zuid maken en dus niet echt stilstaan. Alleen een ronde baan boven de evenaar op die exacte hoogte geeft een echt vast punt aan de hemel.' },
  { id: 225, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom het ISS door restatmosfeer op 400 km hoogte constant moet "reboosten" om niet te vallen', uitleg: 'Op zo\'n 400 kilometer hoogte is nog een flinterdunne rest lucht, en door de hoge baansnelheid van bijna 8 kilometer per seconde voelt het grote ISS daar toch merkbare wrijving. Die wrijving haalt steeds energie uit de baan, zodat het station langzaam zakt, tientallen meters per dag. Vreemd genoeg gaat het bij het zakken juist sneller, omdat een lagere baan een hogere snelheid vereist, terwijl de totale energie afneemt. Daarom moet het ISS af en toe \'reboosten\': met raketmotoren van aangekoppelde vrachtschepen wordt de verloren energie aangevuld zodat het op hoogte blijft.' },
  { id: 226, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom in een baan versnellen je juist naar een hógere, tragere baan brengt (de orbitale-mechanica-paradox)', uitleg: 'Versnel je in je bewegingsrichting, dan voeg je energie toe aan je baan, waardoor het punt aan de overkant omhoog schuift en je baan groter en gemiddeld hoger wordt. Op een grotere baan is de vereiste rondgaande snelheid volgens Kepler juist lager, dus na het opklimmen ga je langzamer rond de aarde. Kortom: versnellen geeft even meer snelheid, maar levert uiteindelijk een hogere, tragere baan met een langere omlooptijd op. Daarom moet een ruimtevaartuig dat een hoger object wil inhalen soms juist afremmen, om naar een lagere en snellere baan te zakken.' },
  { id: 227, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom een "Hohmann-transfer" met twee korte branden de zuinigste manier is om tussen twee banen te wisselen', uitleg: 'Een Hohmann-transfer gebruikt een langgerekte, ovale tussenbaan die zowel de lage als de hoge cirkelbaan raakt. Eén motorstoot brengt je vanaf de lage baan die ovaal in, en een tweede stoot bij aankomst maakt er weer een cirkel van op de gewenste hoogte. Doordat beide stoten precies in de bewegingsrichting gaan, wordt de energie zo zuinig mogelijk gebruikt en zijn de snelheidsveranderingen minimaal. Alleen bij heel grote hoogteverschillen is een andere route soms nog iets zuiniger. De prijs voor die zuinigheid is de reistijd: je legt een halve ovaal af, wat lang duurt.' },
  { id: 228, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom "Lagrange-punten" plekken zijn waar zwaartekracht en middelpuntvliedende kracht elkaar opheffen (waar telescopen parkeren)', uitleg: 'In een systeem van twee grote massa\'s, zoals zon en aarde, zijn er vijf plekken waar de zwaartekracht van beide samen precies genoeg trekt om een klein object met dezelfde snelheid mee te laten draaien. Zo\'n Lagrange-punt houdt daardoor een vaste plaats ten opzichte van beide grote lichamen. Drie ervan liggen op de lijn tussen de twee en zijn wankel; twee andere liggen in de baan en zijn stabiel, en vangen daar stof en planetoïden. Telescopen zoals James Webb parkeren bij het zon-aarde-punt L2, waar ze met bijna geen brandstof meebewegen en steeds van zon, aarde en maan afgekeerd blijven, ideaal koel en stabiel voor waarnemingen.' },
  { id: 229, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom een satelliet aan het eind van zijn leven naar een "graveyard orbit" wordt gebracht om de geostationaire ring vrij te houden', uitleg: 'De geostationaire ring op 35.786 kilometer is een schaarse, drukke baanstrook waar een kapotte satelliet een blijvend botsingsgevaar zou vormen. Naar beneden laten vallen en laten opbranden kost vanaf die hoogte veel te veel brandstof. Daarom duwt men de satelliet aan het eind van zijn leven met een laatste zetje een paar honderd kilometer omhoog, naar een \'kerkhofbaan\' boven de werkring, wat veel minder brandstof kost. Internationale regels schrijven voor hoe ver dat minstens moet zijn, zodat de zonlichtdruk het object niet terug laat drijven. Zo blijft de kostbare geostationaire ring vrij voor nieuwe satellieten.' },
  { id: 230, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom herintreding hitte geeft door compressie van de lucht vóór het schild, niet door wrijving', uitleg: 'Bij terugkeer in de atmosfeer gaat het voertuig zo snel dat de lucht ervoor niet weg kan wijken, maar hard wordt samengeperst in een schokgolf voor de neus. Die samenpersing zet de bewegingsenergie van de lucht om in enorme hitte, zodat het gas achter de schok duizenden graden wordt en zelfs verandert in gloeiend plasma. Die hete gaslaag, en niet de wrijving langs de buitenkant, is de grootste warmtebron voor het hitteschild. Daarom kiest men expres een bot, stomp schild: dat houdt de schokgolf op afstand voor de neus, zodat de heetste lucht van het voertuig weg blijft.' },
  { id: 231, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom een ablatief hitteschild expres verbrandt en zo de warmte met de wegvloeiende laag afvoert', uitleg: 'Een ablatief hitteschild is gemaakt van materiaal dat bij de extreme terugkeerhitte met opzet verbrandt en verdampt in plaats van heel te blijven. De energie die nodig is om het materiaal te ontleden en weg te laten koken, wordt weggehaald bij het oppervlak, wat sterk koelt. Bovendien vormen de wegstromende gassen een koelere laag die de gloeiend hete schoklucht van het oppervlak afschermt. Doordat de warmte samen met de wegvloeiende laag verdwijnt, blijft de capsule eronder koel, ten koste van het opgeofferde schildmateriaal.' },
  { id: 232, categorie: 'Ruimtevaart & baanmechanica', vraag: 'Waarom ruimtevaartuigen "reaction wheels" gebruiken om te draaien zonder brandstof — en falen als die vastlopen (Kepler-telescoop)', uitleg: 'Reactiewielen zijn zware, goed uitgebalanceerde vliegwielen die door een motor sneller of langzamer worden gedraaid. Door natuurkunde (behoud van draaimoment) draait het ruimtevaartuig dan zelf de andere kant op, en zo kan het heel precies richten zonder brandstof, wat telescopen nodig hebben om maandenlang stil op een ster te blijven. Kleine krachten zoals de druk van zonlicht dwingen de wielen wel steeds sneller te draaien tot ze \'vol\' zijn; dan moeten ze met kleine raketstoten of magneetkracht weer afgeremd worden. Loopt een wiel mechanisch vast, zoals bij de Kepler-telescoop, dan verliest het voertuig een draai-as en kan het niet meer stabiel richten, waarmee de missie eindigt.' },
  { id: 233, categorie: 'Astronomie & astrofysica', vraag: 'Waarom een theelepel neutronenstermaterie evenveel weegt als een berg: kernen op elkaar geperst zonder lege ruimte', uitleg: 'In een gewoon atoom zit bijna alle massa in een piepkleine kern, terwijl de rest vooral lege ruimte is waar de elektronen omheen zwerven. In een neutronenster is de zwaartekracht zo sterk dat de elektronen in de protonen worden geperst tot neutronen, waardoor de materie wordt samengeklonterd tot ongelofelijke kerndichtheid. De neutronen liggen dan bijna tegen elkaar, zonder de gewone lege ruimte, zodat één theelepel ervan evenveel weegt als een berg. Wat de ster tegen verder instorten behoedt, is een kwantumdruk van de opeengepakte neutronen die niet verder samengeperst willen worden.' },
  { id: 234, categorie: 'Astronomie & astrofysica', vraag: 'Waarom de zon oorverdovend bruist maar we niets horen: geluid reist niet door het ruimtevacuüm', uitleg: 'Geluid is een trilling in de druk die een stof nodig heeft om zich voort te planten: lucht, water, of het gloeiende gas van de zon zelf. In de zon razen inderdaad krachtige geluidsgolven, die wetenschappers gebruiken om de binnenkant te bestuderen. Maar tussen de zon en de aarde ligt vrijwel volledig vacuüm, en zonder stof om de trilling door te geven kan het geluid die lege ruimte niet oversteken. Licht heeft daarentegen geen stof nodig en overbrugt de afstand wel, daarom zien we de zon wel maar horen we hem niet.' },
  { id: 235, categorie: 'Astronomie & astrofysica', vraag: 'Waarom de maan elk jaar 3,8 cm wegdrijft en de aardse dag daardoor traag langer wordt (getijdenwrijving)', uitleg: 'De zwaartekracht van de maan trekt een \'bult\' op in de oceanen en de aardkorst, maar doordat de aarde snel draait en er wrijving is, loopt die bult iets vóór op de maan in plaats van er recht onder. De extra massa van die vooruitlopende bult trekt de maan een beetje vooruit, waardoor draaienergie van de aarde overgaat naar de baan van de maan. Daardoor schuift de maan langzaam naar een hogere baan, ongeveer 3,8 centimeter per jaar (gemeten met laserspiegels), terwijl de aarde iets afremt en de dag over heel lange tijd langer wordt. De totale draai-energie van het geheel blijft daarbij behouden.' },
  { id: 236, categorie: 'Astronomie & astrofysica', vraag: 'Waarom Venus heter is dan Mercurius ondanks de grotere afstand: een op hol geslagen broeikas', uitleg: 'Venus heeft een extreem dikke atmosfeer van bijna alleen koolstofdioxide, met een druk van ongeveer 92 keer die op aarde. Dat gas laat het zichtbare zonlicht deels door tot de grond, maar houdt de warmtestraling die de grond terugzendt vast, waardoor de hitte niet meer weg kan: een op hol geslagen broeikaseffect. Zo wordt het oppervlak overal ongeveer 465 graden Celsius, heter dan de dagkant van Mercurius, dat veel dichter bij de zon staat. Mercurius heeft namelijk bijna geen atmosfeer en straalt zijn warmte ongehinderd de ruimte in, met enorme verschillen tussen dag en nacht.' },
  { id: 237, categorie: 'Astronomie & astrofysica', vraag: 'Waarom sterren twinkelen en planeten niet: een planeet is een schijfje dat de luchtturbulentie uitmiddelt', uitleg: 'Sterren twinkelen doordat woelige luchtlagen met wisselende temperatuur het sterrenlicht onderweg alle kanten op buigen, zodat helderheid en positie snel schommelen. Een ster staat zo ver weg dat hij een enkel puntje licht is, waarvan alle straling langs bijna dezelfde weg komt, zodat de luchtverstoring het hele beeld tegelijk laat flikkeren. Een planeet staat veel dichterbij en is een klein schijfje dat uit vele puntjes bestaat; hun aparte twinkelingen gebeuren op verschillende plekken en middelen elkaar uit. Daardoor blijft het licht van een planeet rustig terwijl dat van een ster flikkert.' },
  { id: 238, categorie: 'Astronomie & astrofysica', vraag: 'Waarom een witte dwerg niet verder inzakt dankzij "ontaardingsdruk" van elektronen (Pauli-principe)', uitleg: 'In een witte dwerg is de kernfusie gestopt, dus er is geen hitte meer die met haar stralingsdruk de zwaartekracht tegenhoudt. Wat de ster nu overeind houdt, is een kwantumeffect: volgens het Pauli-principe mogen geen twee elektronen in exact dezelfde toestand zitten, dus bij samenpersen worden ze in steeds hogere bewegingstoestanden gedwongen en verzetten ze zich. Die druk hangt bijna niet van temperatuur af en is zo sterk dat hij het verder instorten stopt. Zo blijft de ster een compact object ter grootte van de aarde maar met de massa van de zon, dat over miljarden jaren alleen nog afkoelt.' },
  { id: 239, categorie: 'Astronomie & astrofysica', vraag: 'Waarom boven de Chandrasekhar-limiet van 1,4 zonsmassa\'s die druk het begeeft en de ster als supernova explodeert', uitleg: 'De elektronendruk die een witte dwerg overeind houdt, kan maar tot een bepaalde massa tegen de zwaartekracht op. Bij verder samenpersen gaan de elektronen bijna zo snel als het licht, en dan groeit hun tegendruk langzamer dan de zwaartekracht toeneemt. Die grens ligt bij ongeveer 1,4 keer de massa van de zon: de Chandrasekhar-limiet. Groeit een witte dwerg daaroverheen, dan bezwijkt de druk en stort de kern in; bij een koolstof-zuurstofdwerg ontsteekt daarbij explosief de fusie, die de hele ster uiteenrijt als een type-Ia-supernova. Bij zwaardere sterkernen leidt de instorting juist tot een neutronenster of zwart gat.' },
  { id: 240, categorie: 'Astronomie & astrofysica', vraag: 'Waarom we de kosmische microgolf-achtergrond zien als de nagloed van ~380.000 jaar na de oerknal', uitleg: 'In de eerste honderdduizenden jaren was het heelal zo heet en dicht dat materie een geladen gas was, waarin losse elektronen het licht steeds tegenhielden, zodat alles ondoorzichtig was. Toen het door het uitdijen afkoelde tot zo\'n 3000 graden, na ongeveer 380.000 jaar, konden elektronen en protonen zich binden tot neutrale waterstof, en ineens kon het licht vrij door de ruimte reizen. Dat vrijgekomen licht zien we nu nog als de kosmische microgolf-achtergrond, de nagloed van dat moment. Door het uitdijen is de golflengte sindsdien duizenden keren opgerekt, zodat het ooit gloeiend hete licht nu een zwak microgolfsignaal van ongeveer 2,7 graden boven het absolute nulpunt is.' },
  { id: 241, categorie: 'Astronomie & astrofysica', vraag: 'Waarom roodverschuiving ons vertelt dat verre sterrenstelsels van ons wegsnellen en het heelal uitdijt', uitleg: 'Elk element zendt licht uit op vaste kleuren (golflengten), maar in het licht van verre sterrenstelsels blijken die allemaal naar het rode, langere kant verschoven. Dat komt doordat de ruimte zelf uitdijt terwijl het licht onderweg is en de golflengte meerekt; hoe verder weg, hoe langer onderweg en hoe groter de verschuiving. Edwin Hubble ontdekte dat deze roodverschuiving netjes toeneemt met de afstand, wat betekent dat verdere stelsels sneller van ons weg lijken te gaan. Dit is het directe bewijs dat het hele heelal uitdijt en ooit klein en heet begon.' },
  { id: 242, categorie: 'Astronomie & astrofysica', vraag: 'Waarom een zwart gat geen "gat" is maar een gebied waar de ontsnappingssnelheid de lichtsnelheid overtreft', uitleg: 'Een zwart gat is geen leegte, maar een plek waar zoveel massa in zo\'n klein gebied zit dat de ruimtetijd extreem gekromd is. De rand ervan, de waarnemingshorizon, is het punt waar je de lichtsnelheid zou moeten halen om te ontsnappen, en omdat niets sneller dan het licht kan, kan van binnenuit niets meer weg, zelfs geen licht. Het is dus juist een uiterst compact object, met in de klassieke beschrijving een oneindig dicht punt in het midden. Voor een niet-draaiend zwart gat wordt de grootte van die rand gegeven door de Schwarzschild-straal, die groter is naarmate de massa groter is.' },
  { id: 243, categorie: 'Astronomie & astrofysica', vraag: 'Waarom sterren via kernfusie tot ijzer kunnen bouwen maar niet verder — zwaardere elementen kósten juist energie', uitleg: 'Bij het samensmelten van atoomkernen komt energie vrij zolang de nieuwe kern steviger gebonden is dan de oude. Die \'stevigheid\' per bouwsteen wordt steeds groter tot je bij ijzer en nikkel komt, rond massagetal 56: dat is het meest stabiele punt. Smelt je nog verder samen dan ijzer, dan levert dat geen energie meer op maar kost het juist energie, omdat de stevigheid daarna weer afneemt. Daarom kan een ster met fusie bouwen tot ijzer, maar niet verder. Zwaardere elementen ontstaan pas via energie-slurpende processen zoals het invangen van neutronen in supernova\'s en bij botsende neutronensterren.' },
  { id: 244, categorie: 'Astronomie & astrofysica', vraag: 'Waarom een groot deel van het goud in het heelal bij botsende neutronensterren ontstond, niet in gewone sterren', uitleg: 'Elementen zwaarder dan ijzer kunnen niet ontstaan door gewone, energieleverende fusie; daarvoor moeten kernen neutronen invangen. Goud ontstaat vooral via het snelle \'r-proces\', waarbij kernen in een omgeving met heel veel neutronen razendsnel vele neutronen opslokken voordat ze kunnen vervallen. Zulke omstandigheden zijn er als twee neutronensterren botsen en enorme hoeveelheden neutronrijke materie de ruimte in slingeren. Dat werd in 2017 bevestigd door de lichtflits (kilonova) bij een gemeten zwaartekrachtgolf. Een flink deel van het goud in het heelal komt dus uit zulke botsingen, niet uit gewone sterren.' },
  { id: 245, categorie: 'Kernfysica & energie', vraag: 'Waarom een kernreactor "vertraagde neutronen" nodig heeft om regelbaar te blijven — zonder zou hij onbestuurbaar snel zijn', uitleg: 'Bij kernsplijting komen de meeste neutronen meteen vrij, maar een heel klein deel (bij uranium-235 ongeveer 0,65 procent) pas seconden tot minuten later, uit het verval van splijtingsresten. Een reactor wordt zo gebouwd dat hij met alleen de directe neutronen net niet aan de gang blijft, en pas doorloopt dankzij die trage nakomers. Daardoor wordt de snelheid van de reactie bepaald door die trage neutronen, wat de vermogensveranderingen langzaam genoeg maakt om met regelstaven bij te sturen. Draait de reactor door op de directe neutronen alleen, dan loopt het vermogen onbeheersbaar snel op.' },
  { id: 246, categorie: 'Kernfysica & energie', vraag: 'Waarom "xenon-vergiftiging" een reactor na afschakelen tijdelijk niet opnieuw laat starten (mede-oorzaak Tsjernobyl)', uitleg: 'Xenon-135 is een afvalstof van splijting die extreem goed neutronen opslokt en dus als een sterk \'gif\' voor de kettingreactie werkt. Het ontstaat deels direct, maar vooral uit het verval van jodium-135, en in een draaiende reactor wordt het door de neutronen ook weer weggebrand, in evenwicht. Zak je sterk in vermogen, dan stopt dat wegbranden terwijl het jodium blijft vervallen, zodat het xenon eerst nog uren oploopt en zoveel neutronen wegvangt dat opnieuw starten tijdelijk niet lukt. Bij Tsjernobyl trok men in die \'xenonput\' de regelstaven ver uit om toch vermogen te forceren, wat de reactor gevaarlijk instabiel maakte.' },
  { id: 247, categorie: 'Kernfysica & energie', vraag: 'Waarom verrijkt uranium maar een paar procent U-235 hoeft te zijn voor een centrale, maar ~90% voor een bom', uitleg: 'Natuurlijk uranium bestaat voor ruim 99 procent uit U-238 en maar 0,7 procent uit het splijtbare U-235. In een reactor worden de neutronen met een moderator afgeremd, en bij die lage snelheid splijt U-235 veel gemakkelijker, zodat een paar procent verrijking al genoeg is voor een beheerste kettingreactie. Een bom werkt juist met snelle neutronen zonder moderator en moet in een fractie van een microseconde exploderen voordat hij zichzelf uiteen blaast, wat een heel hoge dichtheid aan splijtbare kernen vereist. Daarom heb je voor een wapen uranium van ongeveer 90 procent of meer U-235 nodig, om een kleine kritische massa en een snelle keten te halen.' },
  { id: 248, categorie: 'Kernfysica & energie', vraag: 'Waarom een moderator (water of grafiet) neutronen juist afremt om splijting waarschijnlijker te maken', uitleg: 'De neutronen die bij splijting vrijkomen zijn snel, maar U-235 splijt veel gemakkelijker bij lage snelheid. Een moderator bestaat uit lichte kernen, zoals waterstof in water of koolstof in grafiet, waartegen de neutronen bij elke botsing veel snelheid verliezen, net als biljartballen die op even zware ballen stuiten. Na een reeks botsingen zijn de neutronen zo ver afgeremd dat ze veel vaker een nieuwe splijting veroorzaken. Zo houdt de moderator de kettingreactie in stand met maar weinig verrijkt uranium, mits hij zelf weinig neutronen wegslurpt.' },
  { id: 249, categorie: 'Kernfysica & energie', vraag: 'Waarom splijtstofstaven jaren na gebruik nog actief gekoeld moeten worden door "vervalwarmte" (ramp Fukushima)', uitleg: 'Ook nadat de kettingreactie is stilgelegd, blijven de opgehoopte radioactieve splijtingsresten vervallen, en daarbij komt warmte vrij: de vervalwarmte. Vlak na uitschakelen is dat nog enkele procenten van het volle vermogen en het neemt daarna langzaam af, maar het blijft jarenlang zo groot dat de gebruikte splijtstof actief gekoeld moet worden. Valt die koeling weg, dan lopen de staven zo heet op dat hun zirkonium-omhulling met stoom reageert, waarbij waterstof vrijkomt en de kern uiteindelijk kan smelten. Bij Fukushima verwoestte de tsunami de koelsystemen, waarna juist deze vervalwarmte tot kernsmelting en waterstofexplosies leidde.' },
  { id: 250, categorie: 'Kernfysica & energie', vraag: 'Waarom fusie op aarde zo moeilijk is: je moet plasma heter dan de zonkern lang genoeg opgesloten houden', uitleg: 'Om waterstofkernen te laten samensmelten moeten ze elkaars afstoting overwinnen, want gelijke ladingen stoten af; dat vergt razendhoge snelheden en dus enorme temperaturen. In de zonkern helpen de immense druk en een kwantumtruc (tunnelen) daarbij, maar op aarde ontbreekt die druk, zodat een fusiereactor met deuterium en tritium ongeveer 100 tot 150 miljoen graden nodig heeft, nog heter dan het hart van de zon. Bij die hitte is de brandstof een plasma dat geen enkel materiaal mag raken en daarom wordt vastgehouden door sterke magneetvelden of samengeperst met lasers. Bovendien moeten dichtheid, temperatuur en opsluitingstijd tegelijk hoog genoeg zijn voor netto winst, en juist dat samenspel lang volhouden is de grote uitdaging.' },
  { id: 251, categorie: 'Kernfysica & energie', vraag: 'Waarom een "breeder reactor" meer splijtstof maakt dan hij verbruikt door U-238 in plutonium om te zetten', uitleg: 'Natuurlijk uranium bestaat voor meer dan 99% uit U-238, dat zelf niet splijt maar wel een neutron kan opvangen. Vangt zo\'n atoom een neutron, dan verandert het via twee tussenstappen in plutonium-239, dat wél splijtbaar is. Een kweekreactor werkt zo dat elke splijting genoeg extra neutronen vrijmaakt om meer dan één nieuw brandstofatoom te kweken dan er wordt opgestookt. Dat lukt alleen met snelle neutronen (die niet worden afgeremd), want bij plutonium leveren die gemiddeld meer neutronen per splijting op. Zo maakt de reactor meer splijtstof dan hij verbruikt.' },
  { id: 252, categorie: 'Kernfysica & energie', vraag: 'Waarom kritikaliteit een kwestie van geometrie is: dezelfde massa is veilig als staaf maar explosief als bol', uitleg: 'Een kernkettingreactie loopt door zolang elke splijting meer neutronen oplevert dan er ontsnappen. Neutronen ontsnappen langs de buitenkant, maar nieuwe worden overal in het volume gemaakt. Een dunne staaf heeft veel oppervlak ten opzichte van zijn inhoud, dus lekken de neutronen weg voordat ze een nieuwe splijting starten: veilig. Een bol heeft juist het minste oppervlak per inhoud en houdt de neutronen het beste binnen. Daarom kan dezelfde massa ongevaarlijk zijn als staaf, maar explosief zodra je haar tot een compacte bol samenperst, precies het idee achter een implosiewapen.' },
  { id: 253, categorie: 'Kernfysica & energie', vraag: 'Waarom radioactief verval exact een halfwaardetijd volgt zonder dat één atoom "weet" wanneer het aan de beurt is', uitleg: 'Elk radioactief atoom heeft per seconde een vaste kans om te vervallen, en die kans verandert nooit, hoe oud het atoom ook is. Een atoom van een miljoen jaar oud heeft dus exact dezelfde vervalkans als een vers atoom; het proces heeft geen geheugen. Bij enorme aantallen atomen middelt die willekeur uit tot een gladde, voorspelbare afname: telkens na dezelfde tijd is de helft weg. Die halfwaardetijd is dus een eigenschap van de hele groep, niet van één atoom dat zijn beurt zou \'weten\'. De willekeur zit in het individu, de regelmaat in de massa.' },
  { id: 254, categorie: 'Kernfysica & energie', vraag: 'Waarom een RTG (radio-isotoop-generator) ruimtesondes decennia van stroom voorziet zonder bewegende delen', uitleg: 'Een RTG gebruikt de warmte die vrijkomt bij het radioactieve verval van een isotoop, meestal plutonium-238 dat er zo\'n 88 jaar over doet om te halveren. Die warmte wordt rechtstreeks in stroom omgezet met thermokoppels: leg je een temperatuurverschil over twee verschillende materialen, dan ontstaat er vanzelf een spanning (het Seebeck-effect). Het verval gaat spontaan en onstopbaar door, en er zijn geen pompen, turbines of andere bewegende delen die kunnen slijten of vastlopen. Daardoor werkt het decennialang zonder onderhoud. Het rendement is laag, maar het gaat lang mee en werkt ook ver van de zon, waar zonnepanelen te weinig licht krijgen.' },
  { id: 255, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom een golfbal met putjes verder vliegt: de kuiltjes maken een turbulente grenslaag die later loslaat en minder zog geeft', uitleg: 'Bij de snelheid van een golfbal komt de meeste luchtweerstand niet van wrijving, maar van het lagedrukgebied (het \'zog\') achter de bal. Bij een gladde bal glijdt de lucht al vroeg van het oppervlak los, wat een breed zog en veel weerstand geeft. De putjes maken de luchtlaag vlak langs de bal juist woelig; die woelige laag heeft meer energie en blijft langer tegen de bal aan liggen. Daardoor komt de lucht pas verder naar achteren los en wordt het zog kleiner. Dat kan de totale weerstand bijna halveren, zodat de bal met putjes duidelijk verder vliegt.' },
  { id: 256, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom de "boundary layer" bepaalt of stroming glad meeloopt of loslaat en de weerstand verdrievoudigt', uitleg: 'De grenslaag is het flinterdunne laagje lucht vlak langs een oppervlak, waar de snelheid oploopt van nul aan de wand tot de volle stroomsnelheid iets verderop. Voorbij het dikste punt van een voorwerp loopt de druk weer op, en die tegendruk remt de trage lucht in de grenslaag af. Komt die lucht helemaal tot stilstand en keert ze om, dan laat de stroming los en ontstaat een breed, wervelend zog met veel weerstand. Of dat vroeg of laat gebeurt, hangt af van het karakter van de grenslaag: een woelige laag houdt langer stand dan een gladde. Zo bepaalt dit dunne laagje of de weerstand laag blijft of sterk oploopt.' },
  { id: 257, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom laminaire stroming plots in turbulente omslaat bij een kritisch Reynolds-getal', uitleg: 'Het Reynolds-getal vergelijkt twee krachten in een stroming: de vaart waarmee de vloeistof wil doorstromen tegenover de stroperigheid die haar afremt. Bij lage waarden wint de stroperigheid en worden kleine verstoringen gladgestreken, zodat de stroming netjes in evenwijdige lagen blijft lopen. Boven een kritische waarde wint de vaart en groeien kleine verstoringen juist snel uit, waardoor de nette lagen instabiel worden en omslaan in chaotische, kolkende turbulentie. Dat omslagpunt is geen scherpe grens: ruwheid, vorm en trillingen in de omgeving verschuiven het, waardoor de overgang soms grillig verloopt.' },
  { id: 258, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom een supersone straaljager een "Prandtl-Glauert"-condenswolk maakt door de plotse drukval achter de schokgolf', uitleg: 'Rond een vliegtuig dat bijna de geluidssnelheid haalt, vormen zich plaatselijke schokgolven, en vlak daarachter zet de lucht plotseling uit met een scherpe daling van druk én temperatuur. Door die snelle afkoeling zakt de vochtige lucht even onder het punt waarop waterdamp condenseert, waardoor een korte, kegelvormige wolk zichtbaar wordt. Zodra de lucht dat lagedrukgebied voorbij is, warmt ze weer op en verdampt de wolk meteen, dus ze is er maar even. Er hoeft dus geen echte geluidsbarrière te worden doorbroken; genoeg vaart plus vochtige lucht is al voldoende.' },
  { id: 259, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom een "de Laval-tuit" gas eerst vernauwt en dan verwijdt om het supersoon te versnellen (raketmotoren)', uitleg: 'Bij lage snelheid gaat gas sneller stromen als de doorgang smaller wordt, net als water in een knijpende slang. In de nauwste plek, de keel, bereikt het gas precies de geluidssnelheid, en dan draait de regel om: om nog sneller te gaan dan het geluid moet de doorgang juist wijder worden. Dat komt doordat het gas boven de geluidssnelheid zo sterk uitdunt dat een breder kanaal nodig is om dezelfde hoeveelheid door te laten. Die vorm, eerst nauwer en dan wijder, zet de hitte en druk van de verbrandingsgassen om in een enorme uitlaatsnelheid, en dat levert de stuwkracht van een raket.' },
  { id: 260, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom "vortex shedding" een schoorsteen of kabel in resonantie kan laten trillen — en spiraalstrips dat tegengaan', uitleg: 'Als wind langs een ronde paal of kabel strijkt, laat de lucht afwisselend links en rechts los en vormt zo een nette rij ronddraaiende wervels achter het object. Dat wisselende loslaten duwt het object beurtelings naar links en naar rechts, met een ritme dat sneller wordt naarmate de wind harder waait. Valt dat ritme samen met de natuurlijke trillingsfrequentie van de constructie, dan versterkt elke duw de vorige en kunnen de trillingen gevaarlijk groot worden (resonantie). Spiraalvormige strips langs een schoorsteen zorgen dat de wervels over de hoogte niet meer gelijktijdig loskomen, zodat de duwtjes elkaar niet meer opzwepen en de trilling verdwijnt.' },
  { id: 261, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom water in een afvoer geen vaste draairichting heeft: de Coriolis is op die schaal veel te zwak', uitleg: 'De draaikracht van de aarde (de Corioliskracht) is er wel degelijk, maar hij is piepklein en groeit pas mee bij grote afstanden en langzame bewegingen. In een wasbak of toilet zijn de afmetingen zo klein dat andere invloeden veel sterker zijn: de vorm van de bak, hoe het water er al bewoog en scheefheden in de afvoer. Die factoren bepalen de draairichting volledig, en die kan per keer anders zijn. Pas op de reuzenschaal van orkanen en oceaanstromingen wordt de Corioliskracht de baas en legt hij wél een vaste draairichting op, tegen de klok in op het noordelijk halfrond.' },
  { id: 262, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom een "hydraulische sprong" in de gootsteen de ring vormt waar snel water plots dik en traag wordt', uitleg: 'Waar de kraanstraal de gootsteenbodem raakt, spat het water als een flinterdunne, razendsnelle laag naar buiten, sneller dan golfjes zich over dat water kunnen bewegen. Op een bepaalde afstand van het middelpunt lukt het die snelle laag niet meer om al het water af te voeren, en dan springt de stroming plotseling over in een dikkere, tragere laag. Bij die sprong gaat snelheid verloren en wordt het water woelig, zichtbaar als een scherpe cirkel waar het opeens dik en rustig wordt. Het kantelpunt ligt precies waar de stroomsnelheid en de golfsnelheid aan elkaar gelijk zijn.' },
  { id: 263, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom cavitatie bij scheepsschroeven én bij pistoolgarnalen belletjes laat imploderen met een schokgolf', uitleg: 'Cavitatie treedt op waar de druk in water zo laag wordt dat het water gaat koken bij gewone temperatuur en er dampbelletjes ontstaan. Bij een snel draaiende scheepsschroef gebeurt dat aan de zuigkant van de bladen; bij de pistoolgarnaal door de bliksemsnelle waterstraal die zijn schaar wegschiet. Zodra zo\'n belletje in een gebied met hogere druk komt, klapt de damp vrijwel meteen samen en stort het omringende water met enorme vaart naar het midden. Dat levert een krachtige schokgolf en een piek van extreme hitte op precies dat puntje. Die imploderende belletjes vreten metaal weg bij schroeven en verlammen de prooi bij de garnaal.' },
  { id: 264, categorie: 'Stromingsleer & aerodynamica', vraag: 'Waarom een vleugel lift maakt door lucht impuls omlaag te geven — de "gelijke looptijd"-uitleg is aantoonbaar fout', uitleg: 'Een vleugel duwt voortdurend een grote hoeveelheid lucht naar beneden, en volgens Newton duwt die lucht dan met een even grote kracht de vleugel omhoog: dat is de lift. De bekende uitleg dat lucht bovenlangs sneller moet lopen om \'op tijd\' weer bij de onderkant te komen, klopt niet: de bovenlangse lucht komt in werkelijkheid juist eerder aan, en er is geen natuurwet die gelijke looptijd eist. Er is wél een echt snelheidsverschil, dat via de wet van Bernoulli samenhangt met een drukverschil, maar dat beschrijft hetzelfde luchtstroompatroon, het is geen aparte oorzaak naast de neerwaartse afbuiging. Beide manieren van kijken beschrijven dus één en dezelfde stroming.' },
  { id: 265, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom er in de oceaan een "SOFAR-kanaal" zit waardoor walvisgeluid duizenden kilometers ver reist', uitleg: 'Geluid gaat in zeewater sneller als het warmer is en ook als de druk hoger is. Op ongeveer een kilometer diepte is het al koud maar de druk nog niet heel hoog, en daar is de geluidssnelheid het laagst. Geluidsgolven buigen altijd naar het gebied met de laagste snelheid, dus golven die omhoog of omlaag willen, worden telkens teruggebogen naar die diepte. Zo blijft het geluid als in een onzichtbare buis gevangen en waaiert het alleen zijwaarts uit in plaats van alle kanten op. Doordat er nauwelijks energie weglekt, kunnen lage walviskreten in dit SOFAR-kanaal duizenden kilometers ver reizen.' },
  { id: 266, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom het aardmagnetisch veld af en toe volledig omklapt — en waarom het nu meetbaar verzwakt', uitleg: 'Het aardmagnetisch veld ontstaat doordat vloeibaar, elektrisch geleidend ijzer in de buitenkern rondstroomt en zo als een zichzelf versterkende dynamo werkt. Die stromingen zijn van nature chaotisch en wervelend, waardoor het veld voortdurend langzaam verandert: het kan verzwakken, verschuiven of zelfs helemaal van noord en zuid wisselen. Zulke poolomkeringen gebeuren onregelmatig, gemiddeld een paar keer per miljoen jaar, en zijn terug te lezen als magnetische strepen in gestold gesteente van de oceaanbodem. De verzwakking die we nu meten, zoals boven de Zuid-Atlantische Anomalie, past binnen die normale grillige schommelingen en betekent niet per se dat er snel een omkering aankomt.' },
  { id: 267, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom aardbevingsgolven in twee soorten komen (P en S) en de trage S-golf niet door de vloeibare kern kan — zo weten we dat die vloeibaar is', uitleg: 'Een aardbeving stuurt twee soorten golven door de aarde. P-golven persen het gesteente afwisselend samen en uit elkaar, in de richting waarin ze reizen. S-golven schudden het gesteente juist zijdelings, dwars op hun looprichting. Zo\'n zijdelingse schudbeweging kan alleen door vast materiaal, want een vloeistof biedt daar geen weerstand tegen. Meetstations aan de andere kant van de aarde ontvangen daarom wel de P-golven maar geen S-golven: dat lege gebied bewijst rechtstreeks dat de buitenkern vloeibaar is. Uit de manier waarop de P-golven onderweg afbuigen, is bovendien de gelaagde opbouw van de aarde afgeleid.' },
  { id: 268, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom "seismische versterking" op zachte bodem trillingen uitvergroot en juist daar gebouwen instorten (Mexico-Stad 1985)', uitleg: 'Als aardbevingsgolven van hard gesteente in een zachte, slappe bodem komen, gaan ze langzamer lopen. Omdat de energie behouden blijft, moet het trillen dan juist heftiger worden: de bodem schudt met grotere uitslag. Bovendien kan zo\'n losse grondlaag meetrillen op zijn eigen ritme, dat afhangt van hoe dik en slap de laag is. Valt het ritme van de aardbeving samen met dat eigen ritme van de bodem, dan versterken ze elkaar en wordt het schudden dramatisch groter. In Mexico-Stad, gebouwd op de zachte klei van een oud meer, viel dat bodemritme samen met het ritme van middelhoge gebouwen, waardoor juist die gebouwen extreem meetrilden en instortten.' },
  { id: 269, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom de diepste oceaantroggen ontstaan waar een plaat onder een andere duikt (subductie)', uitleg: 'Waar twee aardplaten op elkaar botsen, duikt de zwaardere, meestal oude en koude oceaanplaat onder de andere de aardmantel in; dat heet subductie. Omdat die plaat zwaarder is dan het materiaal eronder, zakt hij weg en trekt daarbij de rand van de aardkorst mee naar beneden. Precies op de plek waar de plaat naar de diepte buigt, ontstaat een lange, smalle en extreem diepe geul in de oceaanbodem. De Marianentrog, met bijna elf kilometer de diepste, markeert zo\'n knikpunt. De koude plaat blijft dalen omdat hij zwaarder is dan zijn omgeving, en dat gewicht is ook de motor achter de hele subductie.' },
  { id: 270, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom een geiser ritmisch uitbarst: onderin kookt water dat door de druk van de kolom erboven wordt tegengehouden tot het knapt', uitleg: 'Een geiser heeft een nauwe, diepe schacht die zich vult met grondwater, dat onderin door vulkanische hitte wordt opgewarmd. Het gewicht van al het water erboven drukt op de bodem, en onder die hoge druk stijgt het kookpunt, zodat het water daar ruim boven de honderd graden kan komen zonder te koken. Zodra het onderin toch begint te koken, duwt de ontstane stoom een deel van het water omhoog, waardoor de kolom lichter wordt en de druk daalt. Die drukdaling verlaagt op slag het kookpunt, waardoor in één klap een grote hoeveelheid water tot stoom verspringt en de geiser uitbarst. Daarna vult de schacht zich weer en begint de cyclus opnieuw.' },
  { id: 271, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom getijden twee bulten per dag geven, óók aan de van de maan afgekeerde kant (differentiële zwaartekracht)', uitleg: 'De getijden komen niet door de kracht waarmee de maan de aarde als geheel aantrekt, maar door het verschil in die aantrekking van de ene kant naar de andere. Aan de kant die naar de maan wijst, is de trekkracht iets sterker dan gemiddeld, en daar bolt het water naar de maan toe op. Aan de van de maan afgekeerde kant is de trekkracht juist iets zwakker dan gemiddeld, waardoor het water daar als het ware achterblijft en een tweede bult vormt, van de maan af. Doordat de aarde in ongeveer een dag onder deze twee vaste bulten door draait, krijgt elke kust twee keer hoogwater en twee keer laagwater per etmaal.' },
  { id: 272, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom een "rogue wave" veel hoger kan worden dan de statistiek voorspelt doordat golven optellen', uitleg: 'De zee bestaat niet uit één golf, maar uit talloze golftreinen met verschillende lengtes, richtingen en snelheden die door elkaar heen lopen. Heel af en toe komen veel van die golven op één plek toevallig gelijk omhoog, en tellen hun toppen bij elkaar op tot één uitzonderlijk hoge, steile golf. Daar bovenop kan een golf spontaan energie van zijn buren wegtrekken en op hun kosten extra hard groeien. Ook kunnen stromingen en de bodemvorm golfenergie bundelen op één plek. Door al die versterkende effecten samen komen monstergolven veel vaker en hoger voor dan een simpele kansberekening zou voorspellen.' },
  { id: 273, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom zand in duinen en woestijnen "zingt" op een specifieke bromtoon door lawineachtige laagjes', uitleg: 'Zingende duinen ontstaan als een dikke laag droog, gelijkmatig zand langs een steile duinhelling naar beneden schuift in een kleine lawine. In die glijdende laag gaan de zandkorrels niet willekeurig door elkaar botsen, maar ze raken in de maat en springen samen in een regelmatig ritme. Dat gelijk op bewegen wekt drukgolven in de lucht op met één duidelijke toonhoogte, en zo klinkt er een verrassend zuivere, aanhoudende bromtoon. Hoe hoog die toon is, hangt vooral af van hoe strak de korrels in de maat botsen, niet simpelweg van de grootte van het duin.' },
  { id: 274, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom diamant diep in de mantel ontstaat en alleen via explosieve "kimberliet-pijpen" naar boven komt', uitleg: 'Diamant kan alleen ontstaan bij de enorme druk en hitte die pas dieper dan zo\'n honderdvijftig kilometer in de aardmantel heersen; hoger op zou koolstof gewoon grafiet worden. Daar diep kristalliseert de diamant dus, maar op een langzame, warme tocht omhoog zou hij tijd hebben om alsnog in grafiet te veranderen. Kimberlietmagma redt hem: dat schiet uitzonderlijk snel en explosief door verticale pijpen omhoog, aangedreven door gassen die uitzetten zodra de druk afneemt. Door die razendsnelle rit koelt de meegevoerde diamant snel genoeg af om zijn vorm te behouden en heelhuids het oppervlak te bereiken.' },
  { id: 275, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom de oceaan gelaagd is (thermocline) en onderzeeërs zich onder zo\'n laag voor sonar kunnen verstoppen', uitleg: 'De oceaan zit in lagen: de zon warmt de bovenste laag op, terwijl het water eronder koud blijft, met daartussen een dunne overgangszone (de thermocline) waar de temperatuur snel omslaat. Omdat geluid in warm en koud water verschillend snel gaat, buigen sonargolven scherp af zodra ze die overgang raken. Een onderzeeër die net onder de thermocline vaart, kaatst de van boven komende sonarbundel weg en creëert zo een \'blinde\' zone waarin hij bijna niet te horen is. De laag werkt daardoor als een soort akoestische spiegel die het opsporen door schepen aan de oppervlakte flink bemoeilijkt.' },
  { id: 276, categorie: 'Aarde, geologie & oceaan', vraag: 'Waarom onderzeese modderlawines ("turbidity currents") trans-Atlantische kabels knapten en zo hun snelheid verrieden', uitleg: 'Een turbiditeitsstroom is een onderwaterlawine: water dat vol modder en zand zit, is zwaarder dan schoon zeewater en raast daardoor als een dichte, snelle stroom langs de zeebodemhelling naar beneden. Bij de aardbeving bij Grand Banks in 1929 sneed zo\'n stroom, steeds dieper, achter elkaar de transatlantische telegraafkabels door. Elke kabelbreuk werd op de seconde nauwkeurig geregistreerd, en omdat men wist waar de kabels lagen, kon uit die tijdstippen de snelheid worden teruggerekend: tot zo\'n tachtig kilometer per uur. Zo leverden de knappende kabels per ongeluk het eerste harde bewijs dat zulke stromen bestaan en hoe krachtig ze zijn.' },
  { id: 277, categorie: 'Meteorologie', vraag: 'Waarom het doodstil en helder is in het "oog" van een orkaan terwijl er direct omheen de zwaarste wind staat', uitleg: 'In een orkaan draait vochtige lucht naar binnen en stijgt hard omhoog in de oogwand, de ring van zware onweerswolken rond het centrum, waar de wind en regen op hun hevigst zijn. In het midden houden twee krachten elkaar in evenwicht, waardoor de lucht niet verder naar binnen kan stromen. In plaats daarvan zakt daar lucht langzaam omlaag, en dalende lucht warmt op en droogt uit, zodat de wolken oplossen en de lucht opklaart. De combinatie van die neerdalende, drogende lucht en de bijna afwezige wind maakt het oog opvallend stil en helder, terwijl er vlak omheen het grootste geweld woedt.' },
  { id: 278, categorie: 'Meteorologie', vraag: 'Waarom föhn aan de lijzijde van een berg warme, droge wind geeft doordat de dalende lucht opwarmt', uitleg: 'Als vochtige lucht tegen de windzijde van een bergketen omhoog wordt geduwd, koelt ze af, en de waterdamp wordt regen die daar valt. Bij dat condenseren komt warmte vrij, waardoor de lucht onderweg omhoog minder snel afkoelt. Boven op de bergkam is de lucht dus afgekoeld én grotendeels drooggeregend. Aan de andere kant zakt die droge lucht weer omlaag en warmt daarbij op, en droge lucht warmt sneller op dan de vochtige lucht aan de opgaande kant afkoelde. Netto komt de lucht in het dal warmer én veel droger aan dan waar ze begon: dat is het föhneffect.' },
  { id: 279, categorie: 'Meteorologie', vraag: 'Waarom een temperatuurinversie smog en geluid vasthoudt door warme lucht als deksel op koude', uitleg: 'Normaal wordt het kouder naarmate je hoger komt, zodat warme grondlucht kan opstijgen en vuil de hoogte in verdunt. Bij een inversie ligt er juist een laag warme lucht bovenop de koude lucht aan de grond, precies andersom. Omdat de koude onderlucht zwaarder is dan de warme laag erboven, blijft alles keurig op zijn plaats en kan de onderste lucht niet omhoog; smog en fijnstof zitten er als onder een deksel gevangen. Diezelfde warme-koude grens buigt bovendien geluidsgolven terug naar de grond in plaats van ze de hoogte in te laten verdwijnen, waardoor geluiden van verder weg toch hoorbaar blijven.' },
  { id: 280, categorie: 'Meteorologie', vraag: 'Waarom hagelstenen laagjes hebben als een ui: ze pendelen meermaals op en neer door de onweersbui', uitleg: 'Een hagelsteen groeit in een onweerswolk waar sterke stromen lucht omhoog en omlaag razen. Telkens als de steen door een gebied met onderkoelde waterdruppels beweegt, vriest er water aan, en het soort ijs hangt af van hoe koud en hoe nat dat gebied is. In een nattere, warmere zone bevriest het water traag tot helder, doorzichtig ijs; in een koude, droge zone vriezen druppels meteen vast, met luchtbelletjes erin, tot melkwit troebel ijs. Doordat de opwaartse en neerwaartse stromen de steen keer op keer door verschillende zones voeren, komen er om en om heldere en troebele laagjes op, net als de ringen van een ui.' },
  { id: 281, categorie: 'Meteorologie', vraag: 'Waarom bliksem in "stappen" naar beneden zoekt en de zichtbare flits juist van de grond omhoog schiet', uitleg: 'Een neerwaartse bliksem begint met een zwak lichtend kanaaltje van geleidende lucht dat in sprongetjes van enkele tientallen meters omlaag tast, telkens op zoek naar het gemakkelijkste pad. Nadert dit kanaal de grond, dan schieten vanaf hoge punten kleine ontladingen omhoog die het contact sluiten. Op het moment dat er een doorlopend geleidend pad is, ontlaadt de enorme lading zich in een terugslag die met bijna een derde van de lichtsnelheid van de grond omhoog schiet en het kanaal fel verlicht. Die opwaartse terugslag voert de meeste stroom en het meeste licht, en dáárom lijkt de zichtbare flits eigenlijk van beneden naar boven te gaan.' },
  { id: 282, categorie: 'Meteorologie', vraag: 'Waarom "sprites" en "blue jets" boven onweer flitsen — bliksem die de ándere kant op, de ruimte in, gaat', uitleg: 'Hoog boven zware onweersbuien kunnen zeldzame ontladingen naar de bovenste atmosfeer optreden. Sprites verschijnen als een krachtige bliksem naar de grond het elektrische veld hoog in de lucht, op zestig tot negentig kilometer, plotseling verstoort; de ijle lucht licht daar dan op in rode, kwalachtige vormen. Blue jets schieten juist als smalle blauwe kegels vanaf de wolktop omhoog, tot in de stratosfeer. Omdat de lucht daarboven veel dunner is dan bij de grond, verlopen deze ontladingen anders dan gewone bliksem, en de aangeslagen stikstof geeft ze hun kenmerkende rode of blauwe kleur.' },
  { id: 283, categorie: 'Meteorologie', vraag: 'Waarom onweer dichtbij een korte knal is maar veraf lang gerommel (verschillende afstanden langs de bliksembaan)', uitleg: 'Een bliksemkanaal is kilometerslang en sterk gebogen, en over de hele lengte wordt de lucht in één klap verhit, zodat er langs het hele kanaal tegelijk een knal ontstaat. Het geluid van de dichtstbijzijnde stukken bereikt je vrijwel meteen, terwijl het geluid van verder weg gelegen stukken van datzelfde kanaal later aankomt, want dat moet een langere weg afleggen. Slaat de bliksem vlakbij in, dan liggen alle stukken op ongeveer dezelfde korte afstand en vallen de knallen samen tot één scherpe klap. Bij verre bliksem lopen de aankomsttijden juist ver uiteen, en verdwijnen de hoge tonen onderweg, waardoor het geluid uitsmeert tot langgerekt, dof gerommel.' },
  { id: 284, categorie: 'Meteorologie', vraag: 'Waarom "virga" regen laat vallen die verdampt vóór hij de grond raakt', uitleg: 'Virga zijn de vegen neerslag die je zichtbaar uit een wolk ziet vallen, maar die de grond nooit halen. Dat gebeurt als de regen onder de wolk door een laag warme, erg droge lucht valt. In die dorstige lucht verdampen de druppels, of verdwijnen ijskristallen rechtstreeks als damp, voordat ze de bodem raken. Dat verdampen kost warmte en koelt de lucht daar af, wat plaatselijk een neerwaartse windvlaag kan versterken. Virga zie je vooral in droge streken en hoger in de lucht, waar het onder de wolk droog genoeg is om alle vallende neerslag onderweg te laten opgaan.' },
  { id: 285, categorie: 'Meteorologie', vraag: 'Waarom een "microburst" een neerstortende luchtkolom is die vliegtuigen bij de landing uit de lucht kan drukken', uitleg: 'Een microburst is een geconcentreerde, krachtige stortkolom van lucht die uit een onweersbui naar beneden valt, vaak versterkt doordat verdampende regen of smeltende hagel de lucht sterk afkoelt en zwaar maakt. Raakt die dalende kolom de grond, dan spat hij horizontaal alle kanten op uiteen, als water dat op een vloer klettert. Een landend vliegtuig vliegt eerst in de tegenwind daarvan, die extra lift geeft, en komt dan plotseling in de neerstortende lucht en vervolgens in de meewind, waardoor het opeens veel snelheid en lift verliest. Door die snelle omslag van tegen- naar meewind, vlak boven de grond, kan het toestel de lift niet op tijd terugwinnen en wordt het naar beneden gedrukt.' },
  { id: 286, categorie: 'Meteorologie', vraag: 'Waarom gevoelstemperatuur (wind chill) bestaat doordat bewegende lucht je isolerende grenslaagje wegblaast', uitleg: 'Rond warme huid ligt een dun laagje opgewarmde, bijna stilstaande lucht dat als een jasje isoleert en het warmteverlies afremt. Wind blaast dat laagje steeds weg en vervangt het door koude lucht, zodat het verschil met de huidtemperatuur groot blijft en je lichaam veel sneller warmte kwijtraakt. Bovendien versnelt de wind het verdampen van vocht op je huid, en verdampen kost extra warmte. De gevoelstemperatuur vertaalt dat versnelde warmteverlies naar een getal: de temperatuur die het bij windstilte even koud zou laten voelen, ook al is de echte luchttemperatuur onveranderd.' },
  { id: 287, categorie: 'Informatica & rekenen', vraag: 'Waarom 0,1 + 0,2 in vrijwel elke computer niet exact 0,3 is: binaire drijvende komma kan 0,1 niet precies weergeven', uitleg: 'Computers slaan getallen meestal op als binaire breuken met een beperkt aantal cijfers. Net zoals een derde in ons decimale stelsel een oneindige rij 0,333... wordt, is 0,1 in het binaire stelsel een oneindig herhalende breuk die moet worden afgekapt en afgerond. Zowel 0,1 als 0,2 worden zo als heel kleine benaderingen opgeslagen, en bij het optellen stapelen die minieme afrondingsfouten zich op tot een uitkomst die net naast 0,3 valt, zoals 0,30000000000000004. Vergelijk je dat met de eveneens afgeronde opslag van 0,3, dan blijkt het net niet gelijk, en dat is precies de bekende verrassing.' },
  { id: 288, categorie: 'Informatica & rekenen', vraag: 'Waarom "cache misses" een moderne processor vaker op geheugen laten wachten dan op rekenen', uitleg: 'Een moderne processor rekent veel sneller dan het werkgeheugen data kan aanleveren; die kloof heet de \'memory wall\'. Om dat te overbruggen bewaart de chip veelgebruikte data in kleine, supersnelle geheugentjes vlak bij de rekenkern, de cache. Zit de gevraagde data in de cache, dan is ze bijna meteen beschikbaar, maar bij een misser (cache miss) moet de kern haar uit het veel tragere hoofdgeheugen halen, wat honderden rekentikken kan duren. Al die tijd staat de rekeneenheid vaak stil te wachten. Daardoor bepaalt niet de pure rekensnelheid de prestatie, maar hoe vaak de cache mist en hoe lang het geheugen erover doet.' },
  { id: 289, categorie: 'Informatica & rekenen', vraag: 'Waarom "branch prediction" een CPU alvast laat gokken welke kant een if-tak op gaat — en Spectre daar een lek van maakte', uitleg: 'Een processor werkt aan meerdere instructies tegelijk en begint aan een volgende voordat de vorige klaar is. Bij een \'als\'-vertakking is echter nog niet bekend welke kant het opgaat, dus voorspelt de branch predictor op basis van eerdere keren welke tak het waarschijnlijk wordt, en voert die alvast gokkenderwijs uit. Blijkt de gok fout, dan draait de chip die voorlopige resultaten terug, zodat het programma toch klopt. Maar het terugdraaien wist niet alles: de gegokte tak heeft ondertussen sporen in de cache achtergelaten. Spectre buit dat uit door de voorspeller expres verkeerd te laten gokken, geheime data alvast te laten inlezen, en die daarna via kleine tijdsverschillen in het cachegeheugen af te lezen.' },
  { id: 290, categorie: 'Informatica & rekenen', vraag: 'Waarom "out-of-order execution" instructies door elkaar uitvoert maar naar buiten toe keurig op volgorde lijkt', uitleg: 'Instructies moeten vaak wachten op data uit traag geheugen, en strikt op volgorde werken zou de rekeneenheden nutteloos laten stilstaan. Een out-of-order processor voert daarom instructies uit zodra hun gegevens klaar zijn, ongeacht hun plek in het programma, en gebruikt slimme boekhouding om te zorgen dat ze elkaar niet in de weg zitten. De uitkomsten worden echter niet meteen definitief, maar in een wachtrij (de reorder buffer) verzameld, die ze pas in de oorspronkelijke programmavolgorde afsluit en naar buiten zichtbaar maakt. Zo werkt de kern vanbinnen zo veel mogelijk parallel, terwijl het van buiten lijkt alsof alles keurig op volgorde gebeurde.' },
  { id: 291, categorie: 'Informatica & rekenen', vraag: 'Waarom een "race condition" alleen soms misgaat en daardoor de moeilijkste bug is om te vinden', uitleg: 'Een race condition ontstaat als twee taken tegelijk aan dezelfde gedeelde gegevens komen zonder goede afspraken over wie wanneer mag, zodat de uitkomst afhangt van hun precieze onderlinge timing. Die timing wordt bepaald door van alles wat je niet in de hand hebt: de planning van het systeem, de belasting, het geheugen. Meestal komen de taken elkaar net niet in de weg en lijkt alles goed te gaan, maar heel af en toe overlappen ze ongelukkig en raakt de data beschadigd. Doordat het bijna nooit misgaat én de fout juist verdwijnt zodra je met een debugger of extra logregels de timing verandert, is zo\'n bug berucht lastig te vinden.' },
  { id: 292, categorie: 'Informatica & rekenen', vraag: 'Waarom "garbage collection" een programma onvoorspelbaar even laat haperen om geheugen op te ruimen', uitleg: 'Bij automatisch geheugenbeheer houdt een \'garbage collector\' bij welke stukjes data nog gebruikt worden, en ruimt hij de rest op zodat dat geheugen weer vrijkomt. Om die controle betrouwbaar te doen, moet hij het programma af en toe heel even stilzetten (de stop-the-world-pauze), zodat er tijdens het opruimen niets verandert. Wanneer die opruiming precies gebeurt en hoe lang ze duurt, hangt af van hoeveel geheugen er in gebruik is, en dat is vanuit het programma gezien niet te voorspellen. Daardoor kan er op een willekeurig moment een korte hapering optreden, wat vervelend is voor toepassingen die altijd binnen een strakke reactietijd moeten blijven.' },
  { id: 293, categorie: 'Informatica & rekenen', vraag: 'Waarom een hash-collisie onvermijdelijk is (duiventilprincipe) en toch zeldzaam genoeg om op te vertrouwen', uitleg: 'Een hashfunctie perst een in principe eindeloze reeks mogelijke invoeren samen tot een uitkomst van vaste, beperkte lengte. Omdat er meer invoeren dan mogelijke uitkomsten zijn, moeten er onvermijdelijk verschillende invoeren op dezelfde uitkomst belanden; dat heet een botsing (het duiventilprincipe: meer duiven dan hokjes). Bij een goede cryptografische hash is het aantal mogelijke uitkomsten echter astronomisch groot, bijvoorbeeld 2 tot de macht 256, zodat de kans om per ongeluk of gericht een botsing te vinden verwaarloosbaar klein is. Het beroemde verjaardagseffect maakt zoeken sneller dan je zou denken, maar zelfs dan blijft het praktisch onhaalbaar, en daarom kun je in de praktijk op de uniciteit vertrouwen.' },
  { id: 294, categorie: 'Informatica & rekenen', vraag: 'Waarom "big-endian" en "little-endian" bepalen in welke volgorde bytes staan — en ooit een echte twist waren', uitleg: 'Een getal dat meer dan één byte in beslag neemt, moet in een bepaalde volgorde in het geheugen worden gezet. Bij big-endian komt de zwaarste byte eerst, net zoals wij een getal van links naar rechts lezen; bij little-endian komt de lichtste byte eerst, wat bij rekenen en het vergroten van getallen soms handiger uitkomt. Allebei zijn ze intern consistent en geen van beide is echt beter, wat lang tot een bijna geloofskwestie tussen processorontwerpers leidde. Het wordt pas een probleem als twee systemen met verschillende volgorde gegevens uitwisselen; daarom spreken netwerkprotocollen één vaste bytevolgorde af.' },
  { id: 295, categorie: 'Informatica & rekenen', vraag: 'Waarom een memory leak een programma langzaam laat opzwellen tot het crasht zonder één zichtbare fout', uitleg: 'Een memory leak ontstaat als een programma geheugen reserveert maar het na gebruik nooit meer teruggeeft, terwijl het ook geen verwijzing meer heeft om dat stuk opnieuw te gebruiken. Bij elke lekkende handeling groeit het gebruikte geheugen een beetje, zonder dat er meteen iets fout lijkt te gaan; het programma draait gewoon door. Pas na lange tijd of veel herhalingen stapelt het verloren geheugen zich op tot al het beschikbare geheugen op is. Dan pas mislukt een reservering of grijpt het besturingssysteem in en crasht het programma, ver van de plek en het moment waar het lek eigenlijk zat, wat het zo lastig te vinden maakt.' },
  { id: 296, categorie: 'Informatica & rekenen', vraag: 'Waarom drijvende komma bij grote getallen gaten heeft: boven een grens is het eerstvolgende gehele getal niet meer weer te geven', uitleg: 'Een drijvende-kommagetal bewaart een vast aantal betekenisvolle cijfers (de mantisse) plus een schaalfactor die aangeeft hoe groot het getal ongeveer is. Naarmate het getal groter wordt, wordt die schaalfactor groter, en daarmee ook de afstand tussen twee getallen die je nog exact kunt opslaan: de kleinst mogelijke stap wordt telkens verder opgeblazen. Bij dubbele precisie is die stap boven ongeveer negen biljard groter dan één, zodat niet elk heel getal meer past. Getallen daartussen worden dan naar de dichtstbijzijnde opslaanbare waarde afgerond, en zo ontstaan de karakteristieke \'gaten\' bij grote getallen.' },
  { id: 297, categorie: 'Cryptografie & beveiliging', vraag: 'Waarom moderne encryptie leunt op "trapdoor"-functies die één kant op triviaal en terug praktisch onmogelijk zijn', uitleg: 'Een trapdoorfunctie is makkelijk te berekenen in de ene richting, maar zonder een geheim praktisch onmogelijk terug te rekenen. Bij RSA is twee grote priemgetallen vermenigvuldigen kinderspel, maar uit het product weer die twee priemfactoren terugvinden is bij grote getallen ondoenlijk voor een gewone computer. De veiligheid berust dus niet op het geheimhouden van de methode, maar op dat enorme verschil in moeite tussen heen en terug. Wie de geheime sleutel (het \'valdeurtje\') heeft, kan de bewerking wél snel omkeren, terwijl een aanvaller zonder die sleutel tegen een onoplosbaar rekenprobleem aan loopt.' },
  { id: 298, categorie: 'Cryptografie & beveiliging', vraag: 'Waarom een "side-channel attack" een sleutel steelt uit stroomverbruik of timing zonder de wiskunde te kraken', uitleg: 'Een side-channel-aanval kraakt niet de wiskunde, maar bespiedt de chip die de versleuteling uitvoert. Tijdens het rekenen lekt zo\'n chip onbedoeld aanwijzingen naar buiten via meetbare dingen als rekentijd, stroomverbruik, elektromagnetische straling of zelfs geluid, en die hangen samen met de bits die hij verwerkt, dus met de geheime sleutel. Door bijvoorbeeld het stroomverbruik tijdens heel veel bewerkingen statistisch te analyseren, kan een aanvaller de sleutel stukje bij beetje reconstrueren. De onderliggende wiskunde blijft daarbij helemaal veilig; het lek zit in hoe de hardware zich tijdens het rekenen fysiek gedraagt.' },
  { id: 299, categorie: 'Cryptografie & beveiliging', vraag: 'Waarom "perfect forward secrecy" zorgt dat een later gestolen sleutel oude gesprekken niet alsnog ontcijfert', uitleg: 'Bij perfect forward secrecy krijgt elk gesprek een eigen, tijdelijke sleutel, die de twee partijen ter plekke samen afspreken en na afloop weggooien, meestal via een efemere Diffie-Hellman-uitwisseling. De vaste langetermijnsleutel, zoals de private sleutel van een servercertificaat, wordt alleen gebruikt om te bewijzen wie je bent, niet om die sessiesleutel te versleutelen of te versturen. Wordt die langetermijnsleutel later gestolen, dan valt er niets mee terug te rekenen: de tijdelijke sleutels zijn allang gewist. Zo blijven eerder opgenomen versleutelde gesprekken beschermd, ook als de hoofdsleutel achteraf in verkeerde handen valt.' },
  { id: 300, categorie: 'Cryptografie & beveiliging', vraag: 'Waarom een quantumcomputer met Shors algoritme de huidige encryptie in principe kan breken — en waarom we nu al "post-quantum" overstappen', uitleg: 'Shors algoritme kan op een voldoende grote quantumcomputer razendsnel grote getallen in priemfactoren ontbinden en verwante wiskundige puzzels oplossen, precies de problemen waarop RSA en elliptische-krommecryptografie hun veiligheid bouwen. Het gebruikt een quantumtruc om de \'periode\' van een functie te vinden, en dat versnelt het factoriseren enorm ten opzichte van de beste gewone computers. Zulke krachtige quantumcomputers bestaan nog niet, maar aanvallers kunnen versleuteld verkeer nú al opslaan om het later, zodra de techniek er is, alsnog te ontcijferen (het \'harvest now, decrypt later\'-risico). Daarom stappen we nu al over op post-quantum-versleuteling, die leunt op problemen (zoals roosters) die ook een quantumcomputer niet makkelijk kraakt.' },
]
